@dataclass
class FootageItem:
    index: int
    path: Path
    is_video: bool


@dataclass
class FootageResult:
    items: list["FootageItem"] = field(default_factory=list)
    reused: int = 0          # scenes restored from cache (skipped fetch)
    # scene.index -> [clip per beat] (distinct footage for each ~3.4s beat)
    beat_clips: dict = field(default_factory=dict)
    # AI generation accounting (populated by fetch_footage)
    ai_stats: dict = field(default_factory=dict)
