def _stream_download_atomic(link, dest, *, timeout: int = 60,
                            min_bytes: int = 50_000, headers=None) -> bool:
    """Download `link` to `dest` ATOMICALLY (encode-pool reliability).

    Streams into a sibling ``<dest>.part`` file, flushes + fsyncs, size-
    gates, then ``os.replace``s into place. Because rename is atomic on the
    same filesystem, a concurrent reader (the parallel encode pool) NEVER
    observes a half-written or zero-byte clip — the file either is absent or
    is the complete download. Returns True iff a file > ``min_bytes`` was
    published. Never raises."""
    part = Path(dest).with_name(Path(dest).name + ".part")
    try:
        with requests.get(link, stream=True, timeout=timeout,
                          headers=headers) as dl:
            dl.raise_for_status()
            with open(part, "wb") as fh:
                for chunk in dl.iter_content(1 << 16):
                    fh.write(chunk)
                fh.flush()
                os.fsync(fh.fileno())
    except Exception:                                          # noqa: BLE001
        try:
            part.unlink(missing_ok=True)
        except Exception:                                      # noqa: BLE001
            pass
        return False
    try:
        if part.stat().st_size <= min_bytes:
            part.unlink(missing_ok=True)
            return False
        os.replace(part, dest)                 # atomic publish
        return True
    except OSError:
        try:
            part.unlink(missing_ok=True)
        except Exception:                                      # noqa: BLE001
            pass
        return False


def _scene_intent(scene: Scene) -> tuple[str, str]:
    """Dominant narrative intent + a cinematic footage modifier, read from
    the SENTENCE (semantic), not just its nouns. shot_type is a strong
    director signal too. Returns ('calm', '') when nothing fires."""
    t = " " + re.sub(r"[^a-z0-9 ]", " ", (scene.narration or "").lower()) + " "
    best, score = "calm", 0
    for name, (trigs, _mod) in _INTENTS.items():
        s = sum(1 for w in trigs if w in t)
        if s > score:
            best, score = name, s
    st = (getattr(scene, "shot_type", "") or "").lower()
    if st == "archival" and best in ("calm",):
        return "historical", _INTENTS["historical"][1]
    if best == "calm":
        return "calm", ""
    return best, _INTENTS[best][1]


# Prepositions / linking verbs / filler that aren't good stock-search
# terms (the subject NOUNS are what Pexels matches on).
_DISTILL_SKIP = {
    "through", "amid", "amidst", "across", "along", "behind", "beneath",
    "beside", "toward", "towards", "above", "below", "around", "near",
    "fills", "rests", "resting", "sits", "sitting", "stands", "standing",
    "holds", "holding", "held", "press", "presses", "pressing", "push",
    "approaches", "approaching", "contacts", "contacting", "glides",
    "gliding", "drifts", "drifting", "cascades", "cascading", "running",
    "runs", "glowing", "glows", "reaching", "reaches", "visible",
    "single", "lone", "slowly", "deeply", "firmly", "subtle", "vivid",
    "against", "between", "where", "while", "onto", "front", "back",
    # spatial / camera-direction filler that isn't a SUBJECT and would
    # otherwise eat the 4-word budget before the real noun (e.g. s19
    # 'upward tilted inside garden' was hiding 'cabbage moth')
    "upward", "downward", "tilted", "inside", "outside", "skyward",
    "looking", "facing", "from", "along", "beyond", "past", "within",
    # ambiguous for STOCK search — these send Pexels to the wrong thing
    # (e.g. 'printed' -> a screen-printing workshop, 'text' -> typography
    # clips). The doc/graph itself is drawn by the graphic card anyway.
    "printed", "printing", "print", "insert", "page", "text",
    "typeface", "clinical", "screen", "stylized", "styled",
}


def _distill_visual(scene: Scene) -> str:
    """Turn the LLM cinematic SHOT sentence into a concise stock-search
    SUBJECT phrase — sentence-level understanding with the camera jargon
    removed. e.g. 'Extreme low-angle shot through dew-wet cabbage leaves
    at golden-hour sunrise; a steaming ceramic mug…' -> 'dew wet cabbage
    leaves'. Hyphens are split first so 'low-angle' (camera) drops while
    'dust-covered' (content) survives. The whole sentence is scanned (NOT
    clause-split) so the 'Macro shot — a beetle…' pattern still yields
    'beetle …'. Keeps the first 4 distinct content words, in order."""
    vis = (getattr(scene, "visual", "") or "").replace("-", " ").lower()
    keep: list[str] = []
    for w in re.findall(r"[a-z][a-z']+", vis):
        w = w.strip("'")
        if w.endswith("'s"):           # possessive -> bare noun
            w = w[:-2]                 # "strip's"->"strip", "eli's"->"eli"
        if (len(w) <= 2 or w in _CAM_WORDS or w in _STOPWORDS
                or w in _DISTILL_SKIP):
            continue
        if w not in keep:
            keep.append(w)
        if len(keep) >= 4:
            break
    return " ".join(keep)


# Nouns whose dominant stock-video meaning is NOT the one a topical video
# usually intends. Pexels ranks by popularity, so a bare "beetle" surfaces
# vintage VW *cars*, "crane" a construction crane, "mouse" a computer
# mouse, etc. When the video has a clear subject DOMAIN we pin these to it
# so the match is deterministic instead of Pexels-popularity roulette.
_AMBIGUOUS = {
    "beetle", "beetles", "bug", "bugs", "mouse", "mice", "crane",
    "cranes", "seal", "seals", "bass", "jaguar", "jaguars", "mole",
    "moles", "tank", "tanks", "spring", "springs", "bow", "bows",
    "cricket", "crickets", "turkey", "cookie", "cookies", "python",
    "shell", "shells", "spider", "spiders", "fly", "flies", "mint",
}

# Subject DOMAIN -> (trigger lexicon, the word appended to an ambiguous
# query to pin its meaning). The domain with the most aggregate hits
# across title + all narration + all keywords wins, and only if it clears
# _DOMAIN_MIN (so a video with no clear subject behaves exactly as before).
_DOMAINS: tuple[tuple[str, tuple[str, ...], str], ...] = (
    ("pest", ("insect", "insects", "pest", "pests", "bug", "bugs",
              "beetle", "beetles", "aphid", "aphids", "slug", "slugs",
              "cutworm", "cutworms", "earwig", "earwigs", "caterpillar",
              "larvae", "infestation", "pesticide", "garden", "gardening",
              "crop", "crops", "soil", "plant", "plants", "harvest"),
     "insect"),
    ("wildlife", ("wildlife", "animal", "animals", "predator", "prey",
                  "habitat", "species", "mammal", "mammals", "bird",
                  "birds", "forest", "jungle", "savanna", "ocean",
                  "marine", "reef", "migration", "nest"),
     "animal"),
    ("automotive", ("car", "cars", "engine", "vehicle", "vehicles",
                    "automobile", "driving", "road", "wheels", "motor",
                    "garage", "highway", "horsepower", "dealership"),
     "car"),
    ("military", ("military", "army", "soldier", "soldiers", "war",
                  "weapon", "weapons", "missile", "combat", "battlefield",
                  "troops", "artillery"),
     "military"),
    ("tech", ("computer", "software", "code", "coding", "keyboard",
              "server", "internet", "programming", "developer",
              "database", "algorithm", "laptop"),
     "computer"),
)
_DOMAIN_MIN = 3


def _video_domain(scenes: list[Scene], title: str = "") -> str:
    """Deterministically read the video's recurring subject domain from
    its title + every narration + every keyword, and return the word that
    disambiguates ambiguous-noun stock queries (e.g. 'insect', so a
    Colorado-potato-BEETLE scene can't pull a vintage VW BEETLE car).
    Returns '' when nothing clears the threshold -> behaviour unchanged."""
    parts = [title or ""]
    for s in scenes:
        parts.append(s.narration or "")
        parts.extend(s.keywords or [])
    blob = " " + re.sub(r"[^a-z ]", " ", " ".join(parts).lower()) + " "
    best, best_score = "", 0
    for _name, trigs, term in _DOMAINS:
        score = sum(blob.count(" " + w + " ") for w in trigs)
        if score > best_score:
            best, best_score = term, score
    return best if best_score >= _DOMAIN_MIN else ""


# Period / historical markers — when a video is clearly set in the past,
# modern stock footage is fundamentally WRONG (a 1955 Cold-War tunnel can
# never be a real Pexels clip), so for those videos we skip stock video and
# go straight to the period-accurate AI-directed shot. Conservative: only
# unambiguous era words count, so a contemporary video is never misflagged.
_PERIOD_WORDS = (
    "soviet", "ussr", "cold war", "kgb", "stasi", "nazi", "hitler",
    "wehrmacht", "gestapo", "reich", "world war", "wwi", "wwii", "ww2",
    "ww1", "great war", "civil war", "prohibition", "victorian",
    "edwardian", "medieval", "renaissance", "ancient", "roman empire",
    "byzantine", "ottoman", "dynasty", "pharaoh", "colonial", "feudal",
    "crusade", "viking", "samurai", "wild west", "gold rush",
    "industrial revolution", "1800s", "1900s", "1910s", "1920s", "1930s",
    "1940s", "1950s", "1960s", "th century", "bygone", "centuries ago",
    "decades ago",
)


def _is_period_video(scenes: list[Scene], title: str = "") -> bool:
    """True when the video is clearly a HISTORICAL / period piece, so the
    footage ladder should prefer the period-accurate AI shot over modern
    stock video. Deterministic; reads title + all narration + keywords.
    Signals: explicit era words, or a year < 2005 that recurs. Tuned to be
    quiet on contemporary topics (a single stray year never trips it)."""
    parts = [title or ""]
    for s in scenes:
        parts.append(s.narration or "")
        parts.extend(s.keywords or [])
    blob = " " + re.sub(r"\s+", " ", " ".join(parts).lower()) + " "
    word_hits = sum(blob.count(w) for w in _PERIOD_WORDS)
    # Recurring old years (< 2005) are a strong period signal; one lone
    # year (e.g. a single founding date in a modern story) is not enough.
    old_years = [int(y) for y in re.findall(r"\b((?:1[0-9]|20)[0-9]{2})\b",
                                             blob) if int(y) < 2005]
    title_blob = " " + (title or "").lower() + " "
    title_period = (any(w in title_blob for w in _PERIOD_WORDS)
                    or bool([y for y in re.findall(
                        r"\b((?:1[0-9]|20)[0-9]{2})\b", title_blob)
                        if int(y) < 2005]))
    return bool(title_period or word_hits >= 2 or len(old_years) >= 2)


def _disambiguate(query: str, domain: str) -> str:
    """Pin a query that contains a known-ambiguous noun to the video's
    subject domain so Pexels can't return the wrong homonym. Deterministic,
    order-preserving and idempotent; a no-op without a domain or an
    ambiguous token (so non-ambiguous scenes are byte-identical)."""
    if not domain:
        return query
    toks = query.lower().split()
    if domain in toks or not any(t in _AMBIGUOUS for t in toks):
        return query
    return f"{query} {domain}"


def _video_culture(scenes: list[Scene], title: str = "") -> str:
    """SOFT culture/region match — if the narration script is Japanese /
    Korean / Chinese, return that word so people/place footage can be
    biased to match (Japanese video -> Japanese-looking people, not
    default-Western stock). Detected deterministically from the actual
    characters used (Kana -> Japanese, Hangul -> Korean, Han-only ->
    Chinese). Returns '' for Latin scripts (language != ethnicity there,
    and default stock already fits) — so behaviour is byte-identical for
    English/European. It is only ever PREFERRED, never required: the
    caller tries the culture query first and falls straight back to the
    plain relevant query when Pexels has no culture match."""
    blob = (title or "") + " ".join(s.narration or "" for s in scenes)
    kana = sum(1 for c in blob if "぀" <= c <= "ヿ")
    hangul = sum(1 for c in blob
                 if "가" <= c <= "힣" or "ᄀ" <= c <= "ᇿ")
    han = sum(1 for c in blob if "一" <= c <= "鿿")
    if hangul >= 8 and hangul >= kana:
        return "korean"
    if kana >= 8:
        return "japanese"
    if han >= 8:
        return "chinese"
    return ""


# Shot GRAMMAR -> a stock-search composition hint. The LLM tags every
# scene with a shot_type (establishing/aerial/wide/detail/macro/reaction/
# portrait/archival/tracking) but until now it never reached the footage
# query, so a "macro" beat and an "aerial" beat searched identically and
# Pexels returned whatever was popular. Appending the composition word
# biases Pexels toward the RIGHT KIND OF SHOT (a real close-up vs a wide
# vs a drone) — PREFERRED, never required: it's tried on the subject
# keywords first and if Pexels has no such framing of the subject the
# plain keyword rung below still wins, so subject relevance is never
# sacrificed. 'archival' is intentionally absent (the historical INTENT
# modifier already handles its look); 'tracking' is absent (the bare word
# pulls railroad-track clips — a homonym trap).
_SHOT_QUERY = {
    "aerial":       "aerial drone",
    "establishing": "wide landscape",
    "wide":         "wide landscape",
    "detail":       "close up",
    "macro":        "macro close up",
    "reaction":     "face close up",
    "portrait":     "portrait close up",
}


# Video-level context shared into per-scene footage selection (set once per
# render by fetch_footage). Currently the detected ERA, so a period documentary
# biases its stock search toward era-appropriate results even on scenes whose own
# narration carries no explicit period words.
_VIDEO_CTX: dict = {}


def _pexels_queries(scene: Scene, theme_broll: str,
                    domain: str = "", culture: str = "") -> list[str]:
    """Ordered Pexels search LADDER: semantic-precise -> on-theme-safe.
    The earliest query that returns a real clip wins, so footage is as
    specific to the line as Pexels allows; if only the generic tail would
    match, the caller treats it as 'no good stock' and uses the AI shot.

    `domain` (from _video_domain) pins ambiguous-noun SPECIFIC queries to
    the video's subject so the homonym can't win on Pexels popularity."""
    kw = [k for k in (getattr(scene, "keywords", None) or []) if k]
    subj = _distill_visual(scene)
    intent, mod = _scene_intent(scene)
    mod1 = mod.split()[0] if mod else ""
    gkind = (getattr(scene, "graphic_kind", "") or "").lower()
    # For proof / document / chart / historical / stat scenes the literal
    # "shot" is a study page / graph / archival plate that stock can't
    # depict well (and the GRAPHIC CARD already covers the screen) — so
    # lead with the INTENT LOOK (archive / laboratory / vintage / data)
    # plus the topic word, not a literal distillation that can go sideways
    # (this is the s15 'printed -> printing-press' class of failure).
    doc_like = (gkind in ("document", "chart")
                or intent in ("proof", "historical", "statistic"))
    # REGRESSION FIX: the LLM `visual` sentence is camera/editing-heavy,
    # so distilling it often yields junk Pexels queries ("camera
    # positioned soil row", "montage split four shots", "explainer
    # animation rendered") -> poor match or AI fallback. The LLM
    # `keywords` are curated CONCRETE FILMABLE NOUNS — clean and
    # reliable (this is what matched well before Issue #1). So: keywords
    # LEAD; the distilled subject is only used when it passes a strict
    # cleanliness gate (2-4 plain tokens, no camera/skip/stub words) —
    # then it can ADD precision but never become the junk primary.
    st = subj.split()
    subj_ok = (
        2 <= len(st) <= 4
        and all(len(w) >= 3 for w in st)
        and all(w not in _CAM_WORDS and w not in _DISTILL_SKIP
                for w in st)
    )

    # ── IMP_001 — Intensity-aware tone tags ──────────────────────────────
    # Match the Pexels query's emotional register to the scene's energy
    # level and narration content, not just subject matter.
    #   • intensity 4-5  → promote dark/dramatic modifier rungs EARLY
    #     (before plain keywords), so Pexels mood bias doesn't randomly
    #     land on a sunny cheerful clip for a death/threat scene.
    #   • intensity 1-2  → add "peaceful calm" to late rungs so
    #     contemplative/resolution scenes get slower serene footage.
    #   • spy/covert narration → append "shadows covert" tag so the
    #     clip pool skews cinematic-dark rather than "office stock".
    _imp001_intensity = int(getattr(scene, "intensity", 0) or 0)
    _narr_low = " " + re.sub(
        r"[^a-z0-9 ]", " ", (scene.narration or "").lower()
    ) + " "
    _covert_markers = (
        " spy ", " spies ", " espionage ", " covert ", " classified ",
        " cia ", " mossad ", " kgb ", " mi6 ", " mi5 ", " fsb ",
        " undercover ", " smuggle ", " assassin ", " infiltrate ",
        " defector ", " double agent ",
    )
    _is_covert = any(m in _narr_low for m in _covert_markers)
    # IMP_007 — true-crime cinematic tone. Crime-specific markers (kept
    # deliberately NARROW so a history/war doc that merely says "killed"
    # doesn't trip it) bias the stock pool toward forensic / crime-scene
    # imagery instead of generic office/handshake b-roll.
    _crime_markers = (
        " murder ", " murdered ", " homicide ", " serial killer ",
        " detective ", " forensic ", " forensics ", " crime scene ",
        " autopsy ", " coroner ", " cold case ", " suspect ",
        " interrogation ", " manhunt ", " crime lab ", " ballistics ",
    )
    _is_crime = any(m in _narr_low for m in _crime_markers)
    # Derive tone supplement — prefer the existing intent mod word so we
    # don't contradict the INTENTS map; fall back to generic.
    if _is_covert:
        _tone_tag = "shadows silhouette covert"   # IMP_007: richer spy mood
    elif _is_crime:
        _tone_tag = "crime scene forensic"        # IMP_007: true-crime mood
    elif _imp001_intensity >= 4 and mod1:
        _tone_tag = mod1               # e.g. "dark", "stark", "fast"
    elif _imp001_intensity >= 4:
        _tone_tag = "dark dramatic"
    elif 0 < _imp001_intensity <= 2:
        _tone_tag = "peaceful calm"
    else:
        _tone_tag = ""
    # ────────────────────────────────────────────────────────────────────

    ladder: list[tuple[str, bool]] = []          # (query, is_specific)
    # SOFT CULTURE MATCH — for a Japanese/Korean/Chinese narration, try a
    # culture-biased version of the strongest relevant query FIRST so the
    # people/places look like the audience (not default-Western stock).
    # It's only PREFERRED: if Pexels has no culture-matching clip these
    # rungs simply return nothing and the plain relevant rungs below win
    # (relevance is never sacrificed). Skipped for doc/chart scenes (the
    # graphic card covers them) and for Latin scripts (culture == '').
    if culture and not doc_like:
        if len(kw) >= 2:
            ladder.append((f"{culture} {' '.join(kw[:2])}", True))
        if kw:
            ladder.append((f"{culture} {kw[0]}", True))
        if subj_ok:
            ladder.append((f"{culture} {subj}", True))
    if doc_like and mod:
        topic = kw[0] if kw else (st[0] if subj_ok else "")
        ladder.append(((f"{topic} {mod}" if topic else mod).strip(), True))
        ladder.append((mod, True))
    # SHOT-GRAMMAR PREFERENCE — bias to the right KIND of shot (a real
    # macro/aerial/close-up of the subject) before the plain keyword
    # rung. Tried on the subject keywords so relevance is preserved; if
    # Pexels has no such framing these simply return nothing and the
    # plain rungs below win. Skipped for doc/chart scenes (the graphic
    # card covers the frame, a "face close up" there would be wrong).
    shotmod = _SHOT_QUERY.get(
        (getattr(scene, "shot_type", "") or "").lower())
    if shotmod and not doc_like:
        if len(kw) >= 2:
            ladder.append((f"{' '.join(kw[:2])} {shotmod}", True))
        elif kw:
            ladder.append((f"{kw[0]} {shotmod}", True))
        if subj_ok:
            ladder.append((f"{subj} {shotmod}", True))
    # IMP_001 — HIGH-INTENSITY / COVERT tone-priority rungs.
    # For intense (4-5) or covert scenes, add mood-tagged rungs BEFORE
    # the plain keyword backbone. This ensures Pexels biases toward the
    # right emotional register rather than landing on whatever the
    # popularity ranking returns for a bare noun.
    if _tone_tag and not doc_like and (
            _imp001_intensity >= 4 or _is_covert or _is_crime):  # IMP_007
        if kw:
            ladder.append((f"{kw[0]} {_tone_tag}", True))
        if subj_ok:
            ladder.append((f"{subj} {_tone_tag}", True))
        if len(kw) >= 2:
            ladder.append((f"{kw[1]} {_tone_tag}", True))
    # PRIMARY — clean LLM keyword phrases (real-stock backbone)
    if len(kw) >= 3:
        ladder.append((" ".join(kw[:3]), True))
    if len(kw) >= 2:
        ladder.append((" ".join(kw[:2]), True))
    # SECONDARY — semantic precision, ONLY if the distill is clean
    if subj_ok:
        ladder.append((subj, True))
        if mod1 and not doc_like:
            ladder.append((f"{subj} {mod1}", True))
    if kw:
        ladder.append((kw[0], True))
        if mod1 and not doc_like:
            ladder.append((f"{kw[0]} {mod1}", True))
    # IMP_001 — CALM-SCENE tone rungs (peaceful calm) added late so they
    # never override a specific match but still guide the fallback shot.
    if _tone_tag and not doc_like and 0 < _imp001_intensity <= 2:
        if kw:
            ladder.append((f"{kw[0]} {_tone_tag}", True))
        if subj_ok:
            ladder.append((f"{subj} {_tone_tag}", True))
    # ── CHANNEL FOOTAGE TASTE (P-footage) ──────────────────────────
    # When a channel declares `footage.query_suffix`, ADD a rung that
    # appends the suffix to the strongest keyword so Pexels biases
    # toward the channel's visual identity ON THE TAIL — i.e. relevance
    # never loses, but when semantic precision can't disambiguate
    # between visually different clips, the channel taste decides:
    #   • Atlas    → "modern clean studio"   (dataviz-explainer look)
    #   • Amber    → "vintage archival 16mm" (museum / period look)
    #   • Midnight → "cinematic moody dark"  (Netflix-doc look)
    try:
        from .look_dna import current as _ld_current, look_get
        if _ld_current() is not None:
            _fs = (look_get("footage.query_suffix", "") or "").strip()
            if _fs and not doc_like:
                if kw:
                    ladder.append((f"{kw[0]} {_fs}", True))
                if subj_ok:
                    ladder.append((f"{subj} {_fs}", True))
                ladder.append((_fs, False))      # last-ditch channel taste
    except Exception:                                          # noqa: BLE001
        pass
    ladder.append((theme_broll, False))          # generic on-theme tail
    seen: set[str] = set()
    out: list[tuple[str, bool]] = []
    for q, spec in ladder:
        if spec:
            q = _disambiguate(q, domain)
        q = re.sub(r"\s+", " ", q).strip()
        if q and q.lower() not in seen:
            seen.add(q.lower())
            out.append((q, spec))
    # PERIOD GUARD: for a period documentary, try ERA-BIASED variants of the best
    # queries FIRST so Pexels returns era-appropriate clips rather than leading
    # with a modern-city result on a 19th-century beat. Additive + defensive.
    try:
        from . import period_guard as _pg
        _era = _VIDEO_CTX.get("era")
        if _era and _era.get("period_sensitive"):
            _bias = _pg.query_bias(_era)
            if _bias:
                _btag = " ".join(_bias[:2])
                _front = [(f"{q} {_btag}", spec) for q, spec in out[:3]]
                out = _front + out
    except Exception:                                          # noqa: BLE001
        pass
    return out  # type: ignore[return-value]


# Pexels slugs that mark CORPORATE / ABSTRACT / TECH / UI / "data
# dashboard" stock — completely off-topic for documentary work. These
# clips (dark bg with thin white/cyan dashboards + world maps + concentric
# UI rings + line charts) leak in via tangential matches on words like
# "data" or "analysis" in narration. Any candidate whose Pexels slug
# contains ANY of these tokens is rejected BEFORE download.
_PEXELS_BAD_SLUG = (
    # Generic motion-graphics / loop tropes — already filtered
    "dashboard", "analytics", "infographic", "hud", "interface",
    "cyber", "futuristic", "hologram", "loop-animation", "loop animation",
    "motion-graphics", "motion graphics", "abstract-background", "background-loop",
    "particle", "particles", "geometric-shape", "data-visualization", "datavis",
    "world-map-animation", "earth-globe", "globe-rotation", "ai-generated",
    "stock-chart", "trading", "crypto", "blockchain", "fintech",
    "ui-design", "user-interface", "matrix-code", "matrix-rain",
    "neon", "vaporwave", "synthwave", "abstract-tech", "tech-background",
    "digital-tunnel", "wave-loop", "screen-saver",
    # ── EDITORIAL pass: kill the obvious "corporate stock" tropes that
    # leak into documentary footage and make the cut feel like an ad.
    # These are the smiling-businessperson, hands-on-keyboard signatures
    # that every viewer reads as "stock library."
    "businessman", "businesswoman", "business-meeting", "meeting-room",
    "office-meeting", "team-meeting", "office-team", "coworkers",
    "handshake", "shaking-hands", "thumbs-up", "high-five",
    "happy-family", "smiling-couple", "couple-laughing",
    "model-posing", "fashion-shoot", "lifestyle-couple",
    "influencer", "vlogger", "youtuber",
    "phone-scroll", "scrolling-phone", "social-media",
    "person-with-laptop", "typing-on-laptop", "laptop-typing",
    "yoga-class", "fitness-model", "workout-routine",
    "drone-city-aerial", "city-skyline-night",
    "abstract-paint", "paint-pour", "ink-drop",
    "slow-motion-water", "water-droplet-loop",
    "green-screen", "chroma-key",
)


# A stock clip's public slug/title scoring at/above this on period_guard.period_risk
# carries at least one full-strength modern anachronism marker. One undampened
# marker scores ~18-23; a marker dampened by a genuine landscape/nature term
# (a "snowy mountain road") scores ~9-11 and is KEPT — so the threshold drops
# clearly-modern clips while never penalising genuine period-neutral footage.
_PERIOD_SLUG_DROP_RISK = 18


def _period_blocked(text: str) -> bool:
    """True if `text` (a stock clip's public slug / title / tags / description)
    describes something anachronistic for THIS video's era — so the clip is
    dropped at the METADATA level, BEFORE download.

    TWO era regimes, both SEARCH-SIDE (the source's own text), both feeding the
    existing fail-closed ladder (restock → period-grounded fal still → subject
    slide) rather than a new pixel reject:

      • PRE-1945 period documentary → period_risk: a modern NOUN in the slug (a
        modern-Moscow street, a COVID-masked protest crowd, a 1960s home movie)
        that the pixel gate cannot separate from genuine period footage.
      • 1945–1999 HISTORICAL-CONFLICT documentary (RC5, 2026-06-05) → the
        period-neutral pixel gate AND period_risk both stay silent (cars, cities,
        aircraft existed in the 1980s, so they are NOT anachronistic), yet the
        stock/web search still surfaces 2010s–2020s b-roll, a video-game /
        simulation capture, a modern-military-UI loop, COVID crowds, or "4K
        cinematic" promo footage. period_guard.conflict_modern_marker screens the
        slug for ONLY unambiguously-modern / non-photographic tokens (every one
        post-dates ~2005 or names a game/render), so genuine period-conflict
        footage — a desert, a tank column, soldiers, an explosion, a city under
        fire — is never dropped. This is the weak-period → fal down-rank.

    NEVER acts on a genuinely-modern / unknown-era video (both probes return
    empty there), so contemporary topics are never over-filtered. Defensive +
    fail-open: any error keeps the clip — a guard misfire must never block a real
    download."""
    try:
        era = (_VIDEO_CTX or {}).get("era")
        if not isinstance(era, dict):
            return False
        from . import period_guard as _pg
        norm = re.sub(r"[^a-z0-9]+", " ", (text or "").lower())
        if era.get("period_sensitive"):
            if _pg.period_risk(norm, era)["risk"] >= _PERIOD_SLUG_DROP_RISK:
                return True
        # Historical-conflict band (1945–1999): metadata-side modern-marker reject.
        # No-op (returns "") for pre-1945 and for genuinely-modern/unknown eras.
        if _pg.conflict_modern_marker(norm, era):
            return True
        return False
    except Exception:                                          # noqa: BLE001
        return False


def _is_dashboard_clip(video_path: Path) -> bool:
    """Detect a generic 'data dashboard / abstract UI' stock clip after
    download — the kind that's predominantly DARK with sparse thin
    white/cyan graphics (charts, world maps, concentric rings) and NO real
    photographic content. Extracts a mid-clip frame and applies the same
    sparse-graphics-on-dark heuristic that catches text pages — adapted for
    dark-bg / light-glyph dashboards instead of light-bg / dark-glyph pages."""
    try:
        from .ffmpeg_tool import ffmpeg_exe
        import subprocess, tempfile
        with tempfile.NamedTemporaryFile(suffix=".jpg", delete=False) as tf:
            frame_path = tf.name
        # grab a frame ~2s in (skip any blank intro)
        r = subprocess.run(
            [ffmpeg_exe(), "-y", "-hide_banner", "-loglevel", "error",
             "-ss", "2.0", "-i", str(video_path),
             "-frames:v", "1", "-q:v", "3", frame_path],
            capture_output=True, text=True, timeout=15)
        if r.returncode != 0 or not Path(frame_path).exists():
            return False
        import numpy as np
        img = Image.open(frame_path).convert("RGB")
        Path(frame_path).unlink(missing_ok=True)
        if min(img.size) < 60:
            return False
        a = np.asarray(img.resize((128, 72), Image.BILINEAR),
                       dtype="float32")
        L = 0.299 * a[..., 0] + 0.587 * a[..., 1] + 0.114 * a[..., 2]
        dark = float((L < 50).mean())              # near-black background
        bright = float((L > 200).mean())           # thin glyph pixels
        mid = float(((L >= 50) & (L <= 200)).mean())  # photo mid-tones
        sat = float((a.max(axis=2) - a.min(axis=2)).mean())  # colour life
        # dashboard: lots of black + a sparse fraction of bright + very few
        # mid-tones + near-monochrome. Real footage (a face, a city, a
        # landscape) always has photographic mid-tones and colour.
        return (dark > 0.55 and 0.005 < bright < 0.10
                and mid < 0.30 and sat < 25.0)
    except Exception:                                       # noqa: BLE001
        return False


def _is_generic_stock_clip(video_path: Path) -> bool:
    """Detect the OTHER common "stock library" tell — the perfectly-lit,
    centered-subject, evenly-saturated, no-blacks corporate clip.  Real
    documentary footage has natural shadows, asymmetric composition,
    handheld noise.  Corporate stock clips look like a softbox-lit
    studio product shot with everything in the safe middle of the
    histogram.

    Heuristic (cheap, frame-only):
      * **No deep shadows** — very few pixels below 20% luminance
      * **No specular highlights** — very few pixels above 90% luma
      * **High midtone density** — most pixels packed in [60%, 80%]
      * **Saturated AND clean** — colour is present but uniform
        (cheap-stock LUT), distinct from documentary's grit
      * **Symmetric horizontal histogram** — corporate shots tend to
        center the subject; we proxy by checking left/right-half
        average luminance similarity

    Returns True when ≥ 3 of the 4 signals fire — the threshold is
    deliberately conservative so we don't accidentally reject a real
    on-location shot that happens to be evenly lit.
    """
    try:
        from .ffmpeg_tool import ffmpeg_exe
        import subprocess, tempfile, numpy as np
        with tempfile.NamedTemporaryFile(suffix=".jpg", delete=False) as tf:
            frame_path = tf.name
        r = subprocess.run(
            [ffmpeg_exe(), "-y", "-hide_banner", "-loglevel", "error",
             "-ss", "2.0", "-i", str(video_path),
             "-frames:v", "1", "-q:v", "3", frame_path],
            capture_output=True, text=True, timeout=15)
        if r.returncode != 0 or not Path(frame_path).exists():
            return False
        img = Image.open(frame_path).convert("RGB")
        Path(frame_path).unlink(missing_ok=True)
        if min(img.size) < 100:
            return False
        a = np.asarray(img.resize((192, 108), Image.BILINEAR),
                       dtype="float32") / 255.0
        L = 0.299 * a[..., 0] + 0.587 * a[..., 1] + 0.114 * a[..., 2]
        deep_shadow = float((L < 0.10).mean())                 # < 10% luma
        bright_spec = float((L > 0.92).mean())                 # > 92% luma
        midtone_mass = float(((L >= 0.45) & (L <= 0.80)).mean())
        sat = float((a.max(axis=2) - a.min(axis=2)).mean())
        # Symmetric histogram → centred composition
        left_mean = float(L[:, :L.shape[1] // 2].mean())
        right_mean = float(L[:, L.shape[1] // 2:].mean())
        symmetry = 1.0 - min(1.0, abs(left_mean - right_mean) / 0.30)
        # Score: each signal contributes 1 point
        signals = 0
        if deep_shadow < 0.02:           signals += 1
        if bright_spec < 0.005:          signals += 1
        if midtone_mass > 0.65:          signals += 1
        if sat > 0.18 and sat < 0.32:    signals += 1
        if symmetry > 0.85:              signals += 1
        return signals >= 3
    except Exception:                                          # noqa: BLE001
        return False


def _is_blank_bright_clip(video_path: Path) -> bool:
    """Detect a near-WHITE / near-blank stock clip — the symmetric twin of
    the black-frame guard. Some library clips (over-exposed gradients, blown
    skies, empty light-leak / paper backgrounds) carry no real content; after
    look-grading they read as a pale "blank flash" in an otherwise dark
    documentary. The post-render black-frame repair only catches DARK gaps
    (mean_luma≈0), so a sustained ~186/255 blank span has no symmetric guard
    and survives untouched.

    Reject a candidate ONLY when its sampled frames are BOTH very bright AND
    near-uniform (i.e. almost no spatial detail). Gating on LOW VARIANCE —
    not brightness alone — is what keeps legitimate bright-but-detailed shots
    (snow with a subject, a bright lab, sky with a figure): those always carry
    edges / contrast, so their spatial std sits well above the floor even when
    the mean luma is high.

    Samples a few frames across the clip and rejects it ONLY if EVERY readable
    sample is blank-bright, so a clip that is momentarily bright-blank but has
    real content elsewhere is kept (falls through to the next footage tier /
    AI fallback instead of being used).

    Reported by user 2026-05-31 (Edison-vs-Tesla validation render): a
    near-white clip rendered as a ~5s pale empty gradient at t≈55–60s.
    """
    try:
        from .ffmpeg_tool import ffmpeg_exe
        import subprocess, tempfile, numpy as np

        def _sample(t: float):
            """(mean_luma 0–255, spatial std) of the frame at `t`, or None if
            the frame could not be read (seek at/past clip end, or a transient
            ffmpeg error). A failed extract is treated as 'no information' —
            never as blank — so a short clip can't be falsely rejected."""
            with tempfile.NamedTemporaryFile(suffix=".jpg",
                                             delete=False) as tf:
                frame_path = tf.name
            try:
                r = subprocess.run(
                    [ffmpeg_exe(), "-y", "-hide_banner", "-loglevel", "error",
                     "-ss", f"{t:.2f}", "-i", str(video_path),
                     "-frames:v", "1", "-q:v", "3", frame_path],
                    capture_output=True, text=True, timeout=15)
                if r.returncode != 0 or not Path(frame_path).exists():
                    return None
                img = Image.open(frame_path).convert("RGB")
                if min(img.size) < 60:
                    return None
                a = np.asarray(img.resize((128, 72), Image.BILINEAR),
                               dtype="float32")
                L = 0.299 * a[..., 0] + 0.587 * a[..., 1] + 0.114 * a[..., 2]
                return float(L.mean()), float(L.std())
            finally:
                Path(frame_path).unlink(missing_ok=True)

        # Sample across the first ~4s — where a ~5s beat is trimmed from.
        # Out-of-bounds seeks on a shorter clip simply return None.
        samples = [s for s in (_sample(1.0), _sample(2.5), _sample(4.0))
                   if s is not None]
        if len(samples) < 2:                  # too few readable frames -> keep
            return False
        # Reject only if EVERY readable sample is BLANK — either blown-bright
        # (mean > 170 AND luma std < 25) OR crushed near-black (mean < 16 AND
        # std < 10). The std floor is the conservative gate: a smooth blown
        # gradient OR a dead black frame sits far below it, while ANY frame
        # carrying a real subject / edges (even a dark, moody, low-key shot)
        # clears it and keeps the clip. The dark-empty arm (P2, 2026-06-01) is
        # symmetric to the bright arm so an accidentally-accepted black/empty
        # stock clip escalates down the tier ladder to a relevant AI still
        # instead of rendering as a dead frame — never over-rejecting genuine
        # low-key footage, which always carries contrast above the std floor.
        _blank_bright = all(mean > 170.0 and std < 25.0 for mean, std in samples)
        _blank_dark = all(mean < 16.0 and std < 10.0 for mean, std in samples)
        return _blank_bright or _blank_dark
    except Exception:                                          # noqa: BLE001
        return False


def _vr_judge(scene, item, seen_hashes=None):
    """VR3 — pixel-aware verdict on a chosen FootageItem for a CONCRETE scene.

    The footage ladder accepts on query/slug text overlap (see
    research/visual_relevance/VISUAL_RELEVANCE_AUDIT.md); this scores the clip's
    ACTUAL frames against the scene's expected subject with the local ONNX-CLIP
    relevance scorer (+ clarity / period / face signals). Returns
    (ok, scores, reason). Fully defensive: accepts on any error, when the flag
    is off, the scorer is unavailable, or the scene is abstract — so it only
    ever filters a CLEAR pixel-mismatch, never blocks a render."""
    try:
        if os.environ.get("VIDLORE_VISUAL_RELEVANCE", "1").strip().lower() \
                not in ("1", "true", "yes", "on"):
            return True, {}, "off"
        if item is None or getattr(item, "path", None) is None:
            return True, {}, "no-item"
        from . import visual_relevance as _vr
        if not _vr.available():
            return True, {}, "unavailable"
        from . import footage_strength as _fs
        pres = _fs.subject_presence(scene)
        # V1.3.1 — DO NOT skip abstract scenes outright. A scene that cites a
        # study/statistic ("Cornell University confirmed ... 96%") reads
        # 'abstract', yet it still gets a footage clip, and the tier — lacking a
        # strong concrete subject — sometimes grabs a blatantly wrong web image
        # (the Ahmed-Deedat portrait-collage that landed under the 96% card).
        # For abstract scenes we run the scorer in GUARD-ONLY mode (reject only a
        # wrong-dominant-concept; never the relevance/clarity floors) so that
        # class is caught while legitimate atmospheric abstract b-roll is kept.
        _concrete = bool(pres.get("concrete"))
        # Build a SPECIFIC expected subject. The bare subject_presence head-word
        # is frequently a vague single token — a verb ('spraying'/'told') or
        # 'cornell' — and "a photo of <vague word>" matches a WRONG image (a B&W
        # war crowd, a portrait collage) moderately, deflating the
        # distractor-dominance signal below the gate (the 0:18 war-crowd class).
        # The scene's KEYWORDS are the LLM's intended on-screen content — the
        # cleanest, most specific subject — so they win. (subject_presence nouns
        # are NOT used here: they pull in non-visual tokens like
        # 'because'/'built'/'rotating' that re-inflate a wrong clip's match.)
        # Only when a scene has no usable keywords do we fall back to filtered
        # concrete nouns, then the visual line.
        _ABSTRACT = {
            "study", "studies", "university", "college", "research", "report",
            "reports", "data", "control", "confirmed", "percent", "reduction",
            "result", "results", "analysis", "survey", "experiment", "theory",
            "fact", "facts", "proof", "evidence", "science", "scientist",
            "scientists", "method", "test", "told", "reason", "way", "thing",
            "time", "year", "years", "people", "because", "built", "rotating"}
        _kw = [k.strip() for k in (getattr(scene, "keywords", None) or [])
               if isinstance(k, str) and k.strip()]
        if _kw:
            exp = " ".join(_kw[:5])[:160]
        else:
            _head = (pres.get("expected_subject") or "").strip().lower()
            _nouns = sorted(
                str(n).strip().lower() for n in (pres.get("nouns") or [])
                if str(n).strip().lower() not in _ABSTRACT
                and len(str(n).strip()) > 2)
            _parts = ([_head] if _head and _head not in _ABSTRACT else []) \
                + _nouns[:4]
            exp = " ".join(dict.fromkeys(_parts))[:160]
        if not exp:
            exp = ((getattr(scene, "visual", "") or "").strip()[:80]
                   or (pres.get("expected_subject") or "").strip())
        if not exp:
            return True, {}, "no-subject"
        _txt = (exp + " " + " ".join(pres.get("nouns", []))).lower()
        person = any(w in _txt for w in (
            "man", "woman", "person", "people", "men", "women", "farmer",
            "grandfather", "child", "boy", "girl", "soldier", "officer",
            "worker", "portrait", "face", "scientist", "researcher",
            "family", "families", "community", "amish", "elder", "grower"))
        # crowd_ok — is this scene GENUINELY about a crowd / army / group, so a
        # multi-person frame is on-topic (a WWII battle, a Roman army, a protest,
        # a stadium audience, a rally)? For EVERY other scene a crowd / soldier
        # montage is wrong footage and must be rejected regardless of any
        # single-person reference in the narration ('he'/'him'/'man'/'farmer'
        # never license a war crowd). This is the niche-general person-scene
        # safety rule: the SAME gate keeps soldiers on a war/history scene and
        # drops them on agriculture / business / science / biography / spy /
        # health / tech scenes alike.
        _ctx_words = set(re.findall(r"[a-z]+", (
            exp + " " + (getattr(scene, "narration", "") or "") + " "
            + " ".join(k for k in (getattr(scene, "keywords", None) or [])
                       if isinstance(k, str))).lower()))
        crowd_ok = bool(_ctx_words & {
            "crowd", "crowds", "army", "armies", "soldier", "soldiers", "troop",
            "troops", "military", "battle", "battles", "battlefield", "war",
            "warfare", "wartime", "protest", "protests", "protesters", "riot",
            "riots", "rally", "rallies", "parade", "procession", "audience",
            "stadium", "concert", "regiment", "infantry", "cavalry", "platoon",
            "battalion", "demonstration", "mob", "marching", "militia",
            "legion", "legions", "uprising", "revolution", "revolt", "siege"})
        # vehicle_ok — is this scene GENUINELY about a car / vehicle / driving /
        # road / transport, so vehicle footage is on-topic? For EVERY other scene
        # a car / parked vehicle / people-posing-by-a-car snapshot is subject-
        # wrong even when period-correct (the 1960s home-movie-by-a-car on an
        # Amish-garden beat). Computed independently of `person` — an Amish
        # farmer scene showing a car is still wrong.
        vehicle_ok = bool(_ctx_words & {
            "car", "cars", "vehicle", "vehicles", "automobile", "automobiles",
            "truck", "trucks", "driving", "drive", "drove", "road", "roads",
            "highway", "highways", "traffic", "transport", "transportation",
            "motorcar", "motoring", "engine", "garage", "dealership", "racing"})
        _era = (_VIDEO_CTX or {}).get("era")
        # period_guard stores era as a dict {label, year, confidence}; pull the
        # numeric YEAR (a pre-1945 historical scene → modern footage conflicts).
        _era_year = _era.get("year") if isinstance(_era, dict) else _era
        modern = bool(isinstance(_era_year, (int, float)) and _era_year < 1945)
        # Scene-aware NEGATIVES (V1.3): on a scene whose subject is NOT a person,
        # generic vintage/archival people b-roll (a fairground woman, a child in
        # a field, a crowd on stairs) is the 'wrong-but-period-looking' filler
        # that slipped through — feed it as a distractor so the dominance gate
        # catches it. Person scenes (name_reveal/Eli) are exempt.
        _neg = [] if person else [
            "a vintage photograph of people", "an old family photo",
            "a child standing in a field", "a crowd of people on stairs"]
        # ERA-AWARE wrong-period negatives (2026-06-03): on a pre-1945 scene, an
        # obviously-modern frame (a modern city with cars, contemporary street,
        # people in modern clothing or face masks) is wrong even when it isn't a
        # person/crowd the other probes catch. Feed these as distractors so the
        # dominance gate can reject them — works on EITHER a person or non-person
        # scene (a modern car/city is wrong regardless). Safe by construction: a
        # negative only ADDS a reject when the frame matches it MORE than the
        # expected subject, so genuine period-neutral footage (snow/field/
        # soldiers) is never penalised (verified: good period footage stays well
        # under the gate). The pixel modern-probe (period_risk) remains the
        # primary era backstop; this is complementary, not a replacement.
        if modern:
            _neg = list(_neg) + [
                "a modern city with cars and traffic",
                "a contemporary street scene", "people in modern clothing",
                "a present-day crowd of people", "people wearing face masks"]
        return _vr.accept(
            item.path, bool(getattr(item, "is_video", False)), expected=exp,
            objects=list(pres.get("nouns", []))[:3], modern_risk=modern,
            person_expected=person, negatives=_neg, concrete=_concrete,
            guard_only=(not _concrete), crowd_ok=crowd_ok,
            vehicle_ok=vehicle_ok, seen_hashes=seen_hashes)
    except Exception:                                          # noqa: BLE001
        return True, {}, "error"


# --------------------------------------------------------------------------- #
# AI RELEVANCE GATE for enrichment STILLS (Wikimedia / Internet Archive / LoC /
# YouTube-frame / web-ref). Those still sub-sources rank by keyword + image
# WIDTH / DOWNLOADS with ONLY artifact filters (text-page / book-cover / UI /
# designed-graphic) — so a real photo of the WRONG SUBJECT sails straight
# through (the user-reported "Wikimedia/archive gives irrelevant footage").
# This reuses the VIDEO lane's CLIP topic verdict (`_vr_judge`: dominant-wrong-
# concept + designed-graphic + crowd/war/vehicle/era gates) AND adds a STRICTER
# relevance floor that only applies to stills — the video default floor is
# deliberately lenient (to keep atmospheric b-roll), but an enrichment still is
# meant to be a SPECIFIC reference image, so it must clear a higher bar.
# Fully fail-open: scorer off/unavailable, no subject, or ANY error → accept,
# so a render is never blocked; it only ever drops a CLEAR topic mismatch.
#   VIDLORE_STILL_RELEVANCE_GATE  (default "1" = on)
#   VIDLORE_STILL_RELEVANCE_MIN   (default 0.15 — calibrated: irrelevant stills
#                                  score ~0.08-0.11, on-topic ~0.20-0.40)
# --------------------------------------------------------------------------- #
def _still_relevance_gate_on() -> bool:
    return os.environ.get("VIDLORE_STILL_RELEVANCE_GATE", "1").strip().lower() \
        not in ("0", "false", "no", "off")


def _still_relevant(sc, item) -> bool:
    """True if an enrichment STILL is topic-relevant to the scene. Reuses
    `_vr_judge` (CLIP dominance/graphic/crowd gates) then applies a stricter
    still-only relevance floor. Fail-open on any error / missing scorer."""
    try:
        ok, scores, reason = _vr_judge(sc, item)
    except Exception:                                          # noqa: BLE001
        return True
    if not ok:
        try:
            print(f"  [still-relevance] scene {getattr(sc, 'index', '?')} "
                  f"REJECT {Path(item.path).name} — {reason}", flush=True)
        except Exception:                                      # noqa: BLE001
            pass
        return False
    try:
        rel = scores.get("visual_relevance")
        eng = scores.get("engine", "")
        if rel is not None and eng not in ("skipped", "cache-skip", "scorer-off"):
            floor = float(os.environ.get("VIDLORE_STILL_RELEVANCE_MIN", "0.15"))
            if rel < floor:
                print(f"  [still-relevance] scene {getattr(sc, 'index', '?')} "
                      f"REJECT {Path(item.path).name} — low relevance "
                      f"{rel:.3f} < {floor:.2f}", flush=True)
                return False
    except Exception:                                          # noqa: BLE001
        return True
    return True


# --------------------------------------------------------------------------- #
# PHASE 1 — public-domain / open-license VIDEO archives (NASA + Internet Archive)
#
# Real MOTION footage to widen the pool beyond Pexels/Pixabay and kill cross-
# video repetition. Both providers are KEYLESS, license-gated to commercial-safe
# licenses ONLY (CC0 / CC-BY / CC-BY-SA / Public-Domain — NC/ND/unclear rejected,
# fail-closed), and routed through the SAME CLIP topic-relevance gate as the rest
# of the pipeline so an off-topic archival clip is dropped. Each is ADDITIVE and
# DEFAULT-OFF (opt-in via env), so production behaviour is unchanged until enabled:
#   VIDLORE_NASA_VIDEO=1      — NASA Image & Video Library (science/space/tech, PD)
#   VIDLORE_ARCHIVE_VIDEO=1   — Internet Archive movies (history/archival, gated)
# Verified live 2026-06-06: NASA returns real downloadable MP4 renditions keyless;
# Internet Archive returns real MP4s but mixes NC/ND items — hence the hard gate.
# --------------------------------------------------------------------------- #
_NASA_SEARCH_URL = "https://images-api.nasa.gov/search"
_ARCHIVE_ADVSEARCH_URL = "https://archive.org/advancedsearch.php"
_ARCHIVE_META_URL = "https://archive.org/metadata"
_EUROPEANA_SEARCH_URL = "https://api.europeana.eu/record/v2/search.json"
_DVIDS_SEARCH_URL = "https://api.dvidshub.net/search"
_DVIDS_ASSET_URL = "https://api.dvidshub.net/asset"
_PHASE1_UA = "Vidlore/1.0 (+https://vidlore.local; PD/CC footage adapter)"


def _nasa_video_on() -> bool:
    return os.environ.get("VIDLORE_NASA_VIDEO", "0").strip().lower() \
        in ("1", "true", "yes", "on")


def _archive_video_on() -> bool:
    return os.environ.get("VIDLORE_ARCHIVE_VIDEO", "0").strip().lower() \
        in ("1", "true", "yes", "on")


def _europeana_key() -> str:
    return (os.environ.get("VIDLORE_EUROPEANA_API_KEY")
            or os.environ.get("EUROPEANA_API_KEY") or "").strip()


def _europeana_video_on() -> bool:
    """Europeana needs a free key, so it's gated on BOTH the flag and a key
    being present (no key -> silent no-op, never an error)."""
    if os.environ.get("VIDLORE_EUROPEANA_VIDEO", "0").strip().lower() \
            not in ("1", "true", "yes", "on"):
        return False
    return bool(_europeana_key())


def _dvids_key() -> str:
    """DVIDS PUBLIC key only (the `api_key` param). NOT the separate Secret Key
    — DVIDS shows both stacked in one cell, which is why a copy-paste of the cell
    mashes them together and fails the format check."""
    return (os.environ.get("VIDLORE_DVIDS_API_KEY")
            or os.environ.get("DVIDS_API_KEY") or "").strip()


def _dvids_video_on() -> bool:
    if os.environ.get("VIDLORE_DVIDS_VIDEO", "0").strip().lower() \
            not in ("1", "true", "yes", "on"):
        return False
    return bool(_dvids_key())


def _nasa_cap_bytes() -> int:
    """Max download size for a NASA rendition. NASA `~orig` masters are often
    hundreds of MB (a 700 MB+ interview) — far too big for one b-roll beat —
    so we prefer a smaller transcode under this cap. Override VIDLORE_NASA_MAX_MB."""
    try:
        return max(20, int(os.environ.get("VIDLORE_NASA_MAX_MB", "220"))) \
            * 1_000_000
    except ValueError:
        return 220_000_000


def _archive_cap_bytes() -> int:
    """Max download size for an Internet Archive mp4. An item whose smallest
    rendition exceeds this is SKIPPED (try the next item) rather than pulling a
    half-GB master for one beat. Override VIDLORE_ARCHIVE_MAX_MB."""
    try:
        return max(20, int(os.environ.get("VIDLORE_ARCHIVE_MAX_MB", "300"))) \
            * 1_000_000
    except ValueError:
        return 300_000_000


def _dvids_cap_bytes() -> int:
    """Max download size for a DVIDS mp4. DVIDS clips are full-length reels
    (minutes) — even 1080p is 300 MB+ — so we prefer a ~720p rendition and cap
    here. Override VIDLORE_DVIDS_MAX_MB."""
    try:
        return max(20, int(os.environ.get("VIDLORE_DVIDS_MAX_MB", "150"))) \
            * 1_000_000
    except ValueError:
        return 150_000_000


def _remote_size(url: str, headers=None) -> int:
    """Content-Length via HEAD (bytes), or -1 if unknown. Never raises."""
    try:
        r = requests.head(url, headers=headers, timeout=15,
                          allow_redirects=True)
        if r.status_code >= 400:
            return -1
        cl = r.headers.get("Content-Length") or r.headers.get("content-length")
        return int(cl) if cl and str(cl).isdigit() else -1
    except Exception:                                          # noqa: BLE001
        return -1


def _license_is_safe_for_commercial(licenseurl: str, rights: str = "") -> bool:
    """Phase-1 license gate. Accept ONLY CC0 / CC-BY / CC-BY-SA / Public-Domain.
    Reject NonCommercial (NC), NoDerivatives (ND), all-rights-reserved, and any
    unclear / empty license. FAIL CLOSED — unknown rights are rejected, never
    guessed: the safe default for a tool that redistributes footage inside
    finished, commercially-usable videos."""
    s = (licenseurl or "").lower().strip()
    r = (rights or "").lower().strip()
    blob = s + " " + r
    # hard-reject NC / ND first (covers by-nc, by-nd, by-nc-sa, by-nc-nd, …)
    if any(b in blob for b in ("noncommercial", "non-commercial", "noderiv",
                               "no-deriv", "by-nc", "by-nd", "/nc/", "-nc-",
                               "-nd-", "all rights reserved")):
        return False
    # accept explicit open licenses (URL form)
    if any(g in s for g in ("creativecommons.org/publicdomain",
                            "/publicdomain/zero", "/publicdomain/mark",
                            "/licenses/by/", "/licenses/by-sa/")):
        return True
    # accept public-domain markers in the rights text
    if any(g in r for g in ("public domain", "publicdomain",
                            "no known copyright", "cc0",
                            "creative commons zero")):
        return True
    return False                                              # fail closed


def _phase1_queries(sc) -> list[str]:
    """Best→broad query ladder from the scene's keywords (mirrors the stock
    ladder): most-specific phrase first so a precise archival match wins, with a
    broad single-word tail. Empty when the scene has no usable subject."""
    kw = [k for k in (getattr(sc, "keywords", None) or []) if k and str(k).strip()]
    qs: list[str] = []
    if len(kw) >= 2:
        qs.append(" ".join(kw[:3]))
        qs.append(" ".join(kw[:2]))
    if kw:
        qs.append(kw[0])
    if not qs:
        q = (getattr(sc, "query", "") or "").strip()
        if q:
            qs.append(q)
    out, seen = [], set()
    for q in qs:
        ql = q.lower().strip()
        if ql and ql not in seen:
            seen.add(ql)
            out.append(q)
    return out


def _claim_link(claim: str, seen_links, seen_lock) -> bool:
    """Atomic dedupe claim shared across beats (same contract as _pexels_fetch):
    returns True if `claim` was free and is now reserved, False if already taken.
    No shared set → always free (back-compat)."""
    if seen_links is None:
        return True
    if seen_lock is not None:
        with seen_lock:
            if claim in seen_links:
                return False
            seen_links.add(claim)
            return True
    if claim in seen_links:
        return False
    seen_links.add(claim)
    return True


def _pick_nasa_mp4(files) -> list:
    """Rank a NASA asset manifest's mp4 renditions best→worst (original/HD
    first, mobile/preview last), https-normalised. The caller HEAD-checks size
    and downloads the best rendition within a sane size cap (NASA masters can be
    700 MB+ — far too big for a single b-roll beat)."""
    if not isinstance(files, list):
        return []
    mp4s = [f for f in files
            if isinstance(f, str) and f.lower().endswith(".mp4")]
    if not mp4s:
        return []
    pref = ("~orig.mp4", "~large.mp4", "~medium.mp4", "~small.mp4", "~mobile.mp4")

    def rank(u: str) -> int:
        ul = u.lower()
        for i, suf in enumerate(pref):
            if ul.endswith(suf):
                return i
        if "~preview" in ul or "~thumb" in ul:
            return 90
        return 50
    mp4s.sort(key=rank)
    return [u.replace("http://", "https://") for u in mp4s]


def _pick_archive_mp4(ident: str, files) -> str:
    """Choose a reasonable mp4 from an Internet Archive item's file list.
    Prefers the web-friendly IA-normalized derivative and a sane size band
    (skip multi-hundred-MB masters and sub-MB stubs). Returns a download URL."""
    if not isinstance(files, list):
        return ""
    cand = []
    for f in files:
        name = f.get("name") or ""
        if not name.lower().endswith(".mp4"):
            continue
        try:
            size = int(f.get("size") or 0)
        except (TypeError, ValueError):
            size = 0
        cand.append((size, name))
    if not cand:
        return ""
    MAXB, MINB = _archive_cap_bytes(), 500_000
    # keep only renditions within the hard cap (unknown size allowed, ranked last)
    ok = [(s, n) for (s, n) in cand if (s == 0 or s <= MAXB)]
    if not ok:
        return ""                       # every rendition too big -> skip item

    def keyf(v):
        size, name = v
        ia = name.lower().endswith(".ia.mp4")            # IA h.264 normalize
        too_small = bool(size and size < MINB)
        return (too_small, not ia, size if size else (1 << 62))
    ok.sort(key=keyf)
    from urllib.parse import quote
    return f"https://archive.org/download/{ident}/{quote(ok[0][1])}"


def _nasa_clip(sc, dest, *, variant: int = 0,
               seen_links=None, seen_lock=None) -> bool:
    """NASA Image & Video Library VIDEO fetch — keyless, public-domain motion
    footage. Mirrors the _pexels_fetch contract: walks the scene query ladder,
    dedupes via the shared `seen_links` set (by NASA id), downloads an mp4 to
    `dest`, and only accepts a clip that passes the CLIP topic-relevance gate.
    Returns True on a clean, on-topic download; False on any miss. Never raises."""
    if not _nasa_video_on():
        return False
    queries = _phase1_queries(sc)
    if not queries:
        return False
    hdr = {"User-Agent": _PHASE1_UA}
    for qi, query in enumerate(queries):
        broadest = (qi == len(queries) - 1)
        try:
            r = requests.get(_NASA_SEARCH_URL,
                             params={"q": query, "media_type": "video"},
                             headers=hdr, timeout=25)
            r.raise_for_status()
            items = ((r.json().get("collection", {}) or {})
                     .get("items", []) or [])
        except Exception:                                      # noqa: BLE001
            continue
        qwords = {w for w in re.split(r"[^a-z0-9]+", query.lower())
                  if len(w) >= 3}
        cands = []                       # (relevance, nasa_id, manifest_href)
        for it in items:
            data = (it.get("data") or [{}])[0]
            nid = data.get("nasa_id") or ""
            href = it.get("href") or ""
            if not nid or not href:
                continue
            title = data.get("title") or ""
            desc = data.get("description") or ""
            blob = (title + " " + desc).lower()
            # PD by default; skip the rare item flagging third-party copyright.
            if "copyright" in blob and "no copyright" not in blob:
                continue
            text = re.sub(r"[^a-z0-9]+", " ", blob)
            rel = sum(1 for qw in qwords if f" {qw} " in f" {text} ")
            cands.append((rel, nid, href))
        if not cands:
            continue
        if not broadest and qwords:
            kept = [c for c in cands if c[0] >= 1]
            if kept:
                cands = kept
        cands.sort(key=lambda c: -c[0])
        n = len(cands)
        for off in range(n):
            relv, nid, href = cands[(variant + off) % n]
            if not _claim_link(f"nasa:{nid}", seen_links, seen_lock):
                continue
            try:
                mr = requests.get(href, headers=hdr, timeout=25)
                mr.raise_for_status()
                rends = _pick_nasa_mp4(mr.json())
            except Exception:                                  # noqa: BLE001
                continue
            if not rends:
                continue
            # SIZE GATE — NASA masters can be 700 MB+; HEAD each rendition and
            # take the best-quality one within the cap, else the smallest known,
            # else the smallest-ranked rendition (mobile) when sizes are unknown.
            cap = _nasa_cap_bytes()
            sized = [(u, _remote_size(u, hdr)) for u in rends]
            inband = [u for (u, s) in sized if 500_000 < s <= cap]
            known = [(s, u) for (u, s) in sized if s > 0]
            if inband:
                url = inband[0]                  # best quality within cap
            elif not known:
                url = rends[-1]                  # sizes unknown -> smallest rendition
            else:
                continue                         # smallest known > cap -> skip item
            if not _stream_download_atomic(url, dest, timeout=120,
                                           min_bytes=100_000, headers=hdr):
                continue
            if _is_blank_bright_clip(dest):
                dest.unlink(missing_ok=True)
                continue
            try:
                ok, _scd, _rsn = _vr_judge(
                    sc, FootageItem(getattr(sc, "index", 0), dest, True))
            except Exception:                                  # noqa: BLE001
                ok = True
            if not ok:
                dest.unlink(missing_ok=True)
                continue
            if os.environ.get("VIDLORE_LOG_STOCK_URL"):
                print(f"  [nasa-video] {dest.name} <- {url}", flush=True)
            return True
    return False


def _archive_clip(sc, dest, *, variant: int = 0,
                  seen_links=None, seen_lock=None) -> bool:
    """Internet Archive VIDEO fetch (mediatype:movies) — keyless. License-gated
    to CC0/CC-BY/CC-BY-SA/PD ONLY (fail-closed; NC/ND/unclear rejected) at BOTH
    the search field and the per-item metadata, then the CLIP topic-relevance
    gate. Mirrors the _pexels_fetch contract. Returns True on a clean, on-topic,
    commercially-safe download; False on any miss. Never raises."""
    if not _archive_video_on():
        return False
    queries = _phase1_queries(sc)
    if not queries:
        return False
    hdr = {"User-Agent": _PHASE1_UA}
    for qi, query in enumerate(queries):
        broadest = (qi == len(queries) - 1)
        try:
            r = requests.get(
                _ARCHIVE_ADVSEARCH_URL,
                params=[("q", f"mediatype:movies AND ({query}) AND "
                              f"licenseurl:(*creativecommons* OR *publicdomain*)"),
                        ("rows", "30"), ("page", "1"), ("output", "json"),
                        ("fl[]", "identifier"), ("fl[]", "title"),
                        ("fl[]", "year"), ("fl[]", "licenseurl")],
                headers=hdr, timeout=25)
            r.raise_for_status()
            docs = ((r.json().get("response", {}) or {})
                    .get("docs", []) or [])
        except Exception:                                      # noqa: BLE001
            continue
        qwords = {w for w in re.split(r"[^a-z0-9]+", query.lower())
                  if len(w) >= 3}
        cands = []                       # (relevance, identifier, licenseurl)
        for d in docs:
            ident = d.get("identifier")
            if not ident:
                continue
            # Skip YouTube/other re-uploads — uploader-declared licenses are the
            # weakest provenance on IA (a re-upload can be mis-tagged CC). We
            # trust only archive-native items for a tool that redistributes.
            if str(ident).lower().startswith(("youtube-", "yt-")):
                continue
            lic = d.get("licenseurl") or ""
            # LICENSE PRE-GATE on the search field (fail-closed: an item with
            # no / unsafe license is skipped before we ever fetch metadata).
            if not _license_is_safe_for_commercial(lic):
                continue
            title = str(d.get("title") or "")
            if _period_blocked(title):
                continue
            text = re.sub(r"[^a-z0-9]+", " ", title.lower())
            rel = sum(1 for qw in qwords if f" {qw} " in f" {text} ")
            cands.append((rel, ident, lic))
        if not cands:
            continue
        if not broadest and qwords:
            kept = [c for c in cands if c[0] >= 1]
            if kept:
                cands = kept
        cands.sort(key=lambda c: -c[0])
        n = len(cands)
        for off in range(n):
            relv, ident, lic = cands[(variant + off) % n]
            if not _claim_link(f"ia:{ident}", seen_links, seen_lock):
                continue
            try:
                mr = requests.get(f"{_ARCHIVE_META_URL}/{ident}",
                                  headers=hdr, timeout=25)
                mr.raise_for_status()
                meta = mr.json()
            except Exception:                                  # noqa: BLE001
                continue
            md = meta.get("metadata", {}) or {}
            lic2 = md.get("licenseurl") or lic
            rights = (md.get("rights")
                      or md.get("possible-copyright-status") or "")
            # LICENSE RE-CONFIRM on the authoritative item metadata.
            if not _license_is_safe_for_commercial(lic2, rights):
                continue
            url = _pick_archive_mp4(ident, meta.get("files", []))
            if not url:
                continue
            if not _stream_download_atomic(url, dest, timeout=120,
                                           min_bytes=100_000, headers=hdr):
                continue
            if _is_blank_bright_clip(dest):
                dest.unlink(missing_ok=True)
                continue
            if _archival_text_heavy(dest):            # mostly title cards -> skip
                dest.unlink(missing_ok=True)
                continue
            try:
                ok, _scd, _rsn = _vr_judge(
                    sc, FootageItem(getattr(sc, "index", 0), dest, True))
            except Exception:                                  # noqa: BLE001
                ok = True
            if not ok:
                dest.unlink(missing_ok=True)
                continue
            if os.environ.get("VIDLORE_LOG_STOCK_URL"):
                print(f"  [archive-video] {dest.name} <- {url}  "
                      f"(license={lic2})", flush=True)
            return True
    return False


def _europeana_clip(sc, dest, *, variant: int = 0,
                    seen_links=None, seen_lock=None) -> bool:
    """Europeana VIDEO fetch (EU cultural heritage; free key). `reusability=open`
    + a per-item `rights` license gate (CC0/CC-BY/CC-BY-SA/PD only, fail-closed).
    Only items whose `edmIsShownBy` is a DIRECT media file are used — landing /
    player pages (Vimeo etc.) are skipped. Then the CLIP topic-relevance gate.
    Mirrors the _pexels_fetch contract. Returns True on a clean, on-topic,
    commercially-safe download; False on any miss. Never raises."""
    if not _europeana_video_on():
        return False
    key = _europeana_key()
    if not key:
        return False
    queries = _phase1_queries(sc)
    if not queries:
        return False
    hdr = {"User-Agent": _PHASE1_UA}
    cap = _archive_cap_bytes()
    _vexts = (".mp4", ".mov", ".webm", ".ogv", ".m4v")
    for qi, query in enumerate(queries):
        broadest = (qi == len(queries) - 1)
        try:
            r = requests.get(
                _EUROPEANA_SEARCH_URL,
                params={"wskey": key, "query": query, "qf": "TYPE:VIDEO",
                        "reusability": "open", "rows": "30", "profile": "rich"},
                headers=hdr, timeout=25)
            r.raise_for_status()
            items = r.json().get("items", []) or []
        except Exception:                                      # noqa: BLE001
            continue
        qwords = {w for w in re.split(r"[^a-z0-9]+", query.lower())
                  if len(w) >= 3}
        cands = []                       # (relevance, record_id, media_url, rights)
        for it in items:
            rid = it.get("id") or it.get("guid") or ""
            if not rid:
                continue
            rights = (it.get("rights") or [None])[0] or ""
            # per-item LICENSE GATE (fail-closed).
            if not _license_is_safe_for_commercial(rights):
                continue
            isby = (it.get("edmIsShownBy") or [None])[0] or ""
            # only DIRECT media files — skip player / landing pages.
            if not (isby and isby.lower().split("?")[0].endswith(_vexts)):
                continue
            title = " ".join(it.get("title") or [])
            if _period_blocked(title):
                continue
            text = re.sub(r"[^a-z0-9]+", " ", title.lower())
            rel = sum(1 for qw in qwords if f" {qw} " in f" {text} ")
            cands.append((rel, rid, isby, rights))
        if not cands:
            continue
        if not broadest and qwords:
            kept = [c for c in cands if c[0] >= 1]
            if kept:
                cands = kept
        cands.sort(key=lambda c: -c[0])
        n = len(cands)
        for off in range(n):
            relv, rid, url, rights = cands[(variant + off) % n]
            if not _claim_link(f"eu:{rid}", seen_links, seen_lock):
                continue
            sz = _remote_size(url, hdr)
            if sz > cap:                 # too big (known) -> skip, try next
                continue
            if not _stream_download_atomic(url, dest, timeout=120,
                                           min_bytes=100_000, headers=hdr):
                continue
            if _is_blank_bright_clip(dest):
                dest.unlink(missing_ok=True)
                continue
            if _archival_text_heavy(dest):            # mostly title cards -> skip
                dest.unlink(missing_ok=True)
                continue
            try:
                ok, _scd, _rsn = _vr_judge(
                    sc, FootageItem(getattr(sc, "index", 0), dest, True))
            except Exception:                                  # noqa: BLE001
                ok = True
            if not ok:
                dest.unlink(missing_ok=True)
                continue
            if os.environ.get("VIDLORE_LOG_STOCK_URL"):
                print(f"  [europeana-video] {dest.name} <- {url}  "
                      f"(rights={rights})", flush=True)
            return True
    return False


def _pick_dvids_mp4(files, cap: int) -> str:
    """Choose a landscape mp4 from a DVIDS asset's `files[]`. Prefers the
    highest resolution ≤1080p within the size cap (DVIDS clips are full-length —
    a 4K/9 Mbps master of a 6-min clip is 400 MB+, far too big for one beat).
    Returns "" to skip the item when nothing fits the cap."""
    if not isinstance(files, list):
        return ""
    vids = []
    for f in files:
        if (f.get("type") or "").lower() != "video/mp4":
            continue
        src = f.get("src") or ""
        if not src:
            continue
        try:
            w = int(f.get("width") or 0)
            h = int(f.get("height") or 0)
            sz = int(f.get("size") or 0)
        except (TypeError, ValueError):
            w = h = sz = 0
        if w and h and h > w:            # skip portrait/vertical
            continue
        vids.append((w, h, sz, src))
    if not vids:
        return ""
    within = [v for v in vids if (v[2] == 0 or v[2] <= cap)]
    if not within:
        return ""                        # all renditions too big -> skip item
    hd720 = [v for v in within if 0 < v[0] <= 1280]
    if hd720:
        hd720.sort(key=lambda v: -v[0])  # ~720p — good enough, much smaller
        return hd720[0][3]
    le = [v for v in within if 0 < v[0] <= 1920]
    if le:
        le.sort(key=lambda v: v[0])      # else smallest of the 1080p band
        return le[0][3]
    within.sort(key=lambda v: (v[0] or (1 << 31)))   # else smallest width
    return within[0][3]


def _dvids_clip(sc, dest, *, variant: int = 0,
                seen_links=None, seen_lock=None) -> bool:
    """DVIDS VIDEO fetch (U.S. DoD; free key) — public-domain military /
    geopolitics b-roll. Search (`type=video&hd=1`) → Asset API → pick a 1080p
    mp4 within the size cap. PD by policy (no per-item license gate needed), then
    the CLIP topic-relevance gate. Mirrors the _pexels_fetch contract. Never raises."""
    if not _dvids_video_on():
        return False
    key = _dvids_key()
    if not key:
        return False
    queries = _phase1_queries(sc)
    if not queries:
        return False
    hdr = {"User-Agent": _PHASE1_UA}
    cap = _dvids_cap_bytes()
    for qi, query in enumerate(queries):
        broadest = (qi == len(queries) - 1)
        try:
            r = requests.get(_DVIDS_SEARCH_URL,
                             params={"q": query, "type": "video", "hd": "1",
                                     "max_results": "20", "api_key": key},
                             headers=hdr, timeout=25)
            r.raise_for_status()
            res = r.json().get("results", []) or []
        except Exception:                                      # noqa: BLE001
            continue
        qwords = {w for w in re.split(r"[^a-z0-9]+", query.lower())
                  if len(w) >= 3}
        cands = []                       # (relevance, asset_id)
        for it in res:
            aid = it.get("id")
            if not aid:
                continue
            title = str(it.get("title") or "")
            kws = it.get("keywords")
            kwtxt = " ".join(kws) if isinstance(kws, list) else str(kws or "")
            if _period_blocked(title):
                continue
            text = re.sub(r"[^a-z0-9]+", " ", (title + " " + kwtxt).lower())
            rel = sum(1 for qw in qwords if f" {qw} " in f" {text} ")
            cands.append((rel, aid))
        if not cands:
            continue
        if not broadest and qwords:
            kept = [c for c in cands if c[0] >= 1]
            if kept:
                cands = kept
        cands.sort(key=lambda c: -c[0])
        n = len(cands)
        for off in range(n):
            relv, aid = cands[(variant + off) % n]
            if not _claim_link(f"dvids:{aid}", seen_links, seen_lock):
                continue
            try:
                ar = requests.get(_DVIDS_ASSET_URL,
                                  params={"id": aid, "api_key": key},
                                  headers=hdr, timeout=25)
                ar.raise_for_status()
                a = ar.json().get("results", {})
                if isinstance(a, list):
                    a = a[0] if a else {}
                url = _pick_dvids_mp4(a.get("files"), cap)
            except Exception:                                  # noqa: BLE001
                continue
            if not url:
                continue
            if not _stream_download_atomic(url, dest, timeout=120,
                                           min_bytes=100_000, headers=hdr):
                continue
            if _is_blank_bright_clip(dest):
                dest.unlink(missing_ok=True)
                continue
            try:
                ok, _scd, _rsn = _vr_judge(
                    sc, FootageItem(getattr(sc, "index", 0), dest, True))
            except Exception:                                  # noqa: BLE001
                ok = True
            if not ok:
                dest.unlink(missing_ok=True)
                continue
            if os.environ.get("VIDLORE_LOG_STOCK_URL"):
                print(f"  [dvids-video] {dest.name} <- {url}  (PD/DoD)",
                      flush=True)
            return True
    return False


# --------------------------------------------------------------------------- #
# PHASE 2 — niche-routing + era gate + intertitle filter for the video archives
#
# Each SCENE is routed ONLY to the providers whose niche + era actually fit it,
# in best-first order, so a provider is never forced off-niche (the faults the
# showcase exposed: a NASA rocket on a "tanks" scene, a WWI film on a "modern
# training" scene). Space -> NASA. Modern military -> DVIDS. Historical -> Internet
# Archive / Europeana (Europeana first when the scene is European). A scene with
# no matching niche routes to NO new provider (it falls through to stock/AI), so
# these archives only ever serve beats they genuinely fit. Then a text-intertitle
# filter stops an old archival clip from landing on a title card instead of footage.
#   VIDLORE_VIDEO_NICHE_ROUTE=0  -> legacy fixed order (nasa,archive,europeana,dvids)
#   VIDLORE_VIDEO_ORDER=a,b,..   -> explicit override (debug/showcase), bypasses routing
#   VIDLORE_INTERTITLE_FILTER=0  -> disable the title-card filter
# --------------------------------------------------------------------------- #
_NICHE_SPACE = (
    "space", "moon", "lunar", "mars", "planet", "planets", "astronaut",
    "astronauts", "spacecraft", "rocket", "rockets", "satellite", "orbit",
    "orbital", "galaxy", "nebula", "solar", "nasa", "cosmic", "cosmos",
    "telescope", "apollo", "spaceflight", "spacewalk", "iss", "asteroid",
    "comet", "eclipse", "aurora", "universe", "interstellar", "launch",
    "liftoff", "space station", "earth from space", "outer space", "saturn",
    "jupiter", "milky way", "shuttle", "cosmonaut", "meteor")
_NICHE_MILITARY = (
    "military", "army", "navy", "naval", "marine", "marines", "soldier",
    "soldiers", "troops", "tank", "tanks", "artillery", "combat", "infantry",
    "battalion", "brigade", "regiment", "aircraft carrier", "fighter jet",
    "warship", "weapon", "weapons", "rifle", "missile", "deployment", "drill",
    "armored", "armoured", "helicopter", "squadron", "airstrike", "barracks",
    "defense", "defence", "commando", "sniper", "patrol", "convoy", "platoon",
    "warfare", "battlefield", "live-fire", "live fire", "exercise", "paratrooper")
_NICHE_HISTORICAL = (
    "history", "historical", "historic", "archival", "archive", "vintage",
    "ancient", "century", "centuries", "decade", "decades", "era", "wartime",
    "heritage", "world war", "ww1", "ww2", "wwi", "wwii", "cold war",
    "great war", "victorian", "medieval", "empire", "revolution", "antique",
    "1900", "1910", "1920", "1930", "1940", "1950", "1960", "1970", "1980",
    "1914", "1916", "1917", "1918", "1939", "1941", "1945", "iron curtain",
    "soviet", "nazi", "depression", "industrial revolution", "renaissance")
_NICHE_EUROPEAN = (
    "europe", "european", "german", "germany", "french", "france", "british",
    "britain", "england", "dutch", "netherlands", "italian", "italy",
    "spanish", "spain", "belgian", "belgium", "russian", "russia", "soviet",
    "poland", "polish", "austria", "austrian", "vienna", "berlin", "paris",
    "london", "moscow", "rome", "amsterdam", "prague", "budapest", "western front")
_NICHE_MODERN = (
    "today", "modern", "nowadays", "contemporary", "currently", "present day",
    "these days", "21st century", "recent", "recently", "2000", "2005", "2010",
    "2011", "2012", "2013", "2014", "2015", "2016", "2017", "2018", "2019",
    "2020", "2021", "2022", "2023", "2024", "2025", "still train", "now ")


def _scene_blob(sc) -> str:
    kw = " ".join(getattr(sc, "keywords", None) or [])
    nar = getattr(sc, "narration", "") or ""
    vis = getattr(sc, "visual", "") or ""
    return " " + re.sub(r"[^a-z0-9]+", " ", (kw + " " + nar + " " + vis).lower()) + " "


def _scene_niche(sc) -> dict:
    b = _scene_blob(sc)

    def hits(words):
        return sum(1 for w in words if f" {w} " in b or b.endswith(f" {w}"))
    return {"space": hits(_NICHE_SPACE), "military": hits(_NICHE_MILITARY),
            "historical": hits(_NICHE_HISTORICAL), "european": hits(_NICHE_EUROPEAN),
            "modern": hits(_NICHE_MODERN)}


def _pv_route(sc):
    """Ordered, niche+era-filtered provider list for THIS scene (the Phase-2
    router). Returns [] when no new provider fits the scene -> the tier is
    skipped and the beat falls through to stock / AI (never an off-niche clip)."""
    provs = {
        "nasa": ("nasavid", _nasa_clip, _nasa_video_on),
        "archive": ("archivevid", _archive_clip, _archive_video_on),
        "europeana": ("euvid", _europeana_clip, _europeana_video_on),
        "dvids": ("dvidsvid", _dvids_clip, _dvids_video_on),
    }
    raw = os.environ.get("VIDLORE_VIDEO_ORDER", "").strip()
    if raw:                                   # explicit override (debug/showcase)
        return [provs[k] for k in
                (x.strip().lower() for x in raw.split(",")) if k in provs]
    if os.environ.get("VIDLORE_VIDEO_NICHE_ROUTE", "1").strip().lower() \
            in ("0", "false", "no", "off"):
        return [provs[k] for k in ("nasa", "archive", "europeana", "dvids")]
    n = _scene_niche(sc)
    historical = n["historical"] > 0
    order = []
    if n["space"] > 0:
        order.append("nasa")                  # space is NASA's exclusive niche
    if n["military"] > 0 and not historical:
        order.append("dvids")                 # MODERN military -> DVIDS (era gate)
    if historical:                            # historical -> archives (era gate:
        order += (["europeana", "archive"]    # excludes DVIDS, which is modern-only)
                  if n["european"] > 0 else ["archive", "europeana"])
    seen, out = set(), []
    for k in order:
        if k not in seen:
            seen.add(k)
            out.append(provs[k])
    return out


def _frame_is_intertitle(arr) -> bool:
    """A film TITLE CARD / intertitle: a large UNIFORM, mid-tone background with a
    sparse band of high-contrast text glyphs and low colour. Tuned CONSERVATIVE —
    a near-black frame (e.g. space/night footage) or a colourful photographic
    frame is never flagged, so real footage is not over-rejected (it only ever
    catches a clear text card)."""
    import numpy as np
    L = 0.299 * arr[..., 0] + 0.587 * arr[..., 1] + 0.114 * arr[..., 2]
    med = float(np.median(L))
    if med < 45.0 or med > 215.0:        # near-black (space/night) or blown white
        return False                     # -> not an intertitle; keep the footage
    near_bg = float((np.abs(L - med) < 26).mean())     # uniform background
    glyph = float((np.abs(L - med) > 70).mean())       # sparse high-contrast text
    sat = float((arr.max(axis=2) - arr.min(axis=2)).mean())
    return near_bg > 0.62 and 0.006 < glyph < 0.20 and sat < 42.0


def _clip_duration(path) -> float:
    try:
        import subprocess
        import imageio_ffmpeg
        ff = imageio_ffmpeg.get_ffmpeg_exe()
        out = subprocess.run([ff, "-hide_banner", "-i", str(path)],
                             capture_output=True, text=True, timeout=20).stderr
        m = re.search(r"Duration:\s*(\d+):(\d+):(\d+\.?\d*)", out)
        if m:
            h, mi, s = m.groups()
            return int(h) * 3600 + int(mi) * 60 + float(s)
    except Exception:                                          # noqa: BLE001
        pass
    return 0.0


def _archival_text_heavy(video_path) -> bool:
    """True if a downloaded archival clip is mostly TEXT (title cards / inter-
    titles) rather than footage. Samples frames SPREAD across the clip (so a
    title sequence at the start doesn't over-reject) and rejects on a text
    majority. Fail-open: any error -> not text-heavy (never blocks a render)."""
    if os.environ.get("VIDLORE_INTERTITLE_FILTER", "1").strip().lower() \
            in ("0", "false", "no", "off"):
        return False
    try:
        import numpy as np
        import tempfile
        import subprocess
        import imageio_ffmpeg
        ff = imageio_ffmpeg.get_ffmpeg_exe()
        dur = _clip_duration(video_path)
        fracs = [0.12, 0.32, 0.5, 0.68, 0.88]
        d = Path(tempfile.mkdtemp(prefix="itf_"))
        try:
            frames = []
            for i, fr in enumerate(fracs):
                t = (dur * fr) if dur > 0 else float(i)
                fp = d / f"f_{i}.jpg"
                subprocess.run([ff, "-hide_banner", "-loglevel", "error",
                                "-ss", f"{t:.2f}", "-i", str(video_path),
                                "-frames:v", "1", "-vf", "scale=200:-1", str(fp)],
                               timeout=20, capture_output=True)
                if fp.exists() and fp.stat().st_size > 0:
                    frames.append(fp)
            if len(frames) < 3:
                return False                              # can't judge -> keep
            try:
                from . import visual_relevance as _vrm
                _clip_ok = _vrm.available()
            except Exception:                              # noqa: BLE001
                _vrm, _clip_ok = None, False
            text = 0
            for f in frames:
                flagged = False
                try:
                    if _is_text_page(f):
                        flagged = True
                    else:
                        a = np.asarray(Image.open(f).convert("RGB"),
                                       dtype="float32")
                        if _frame_is_intertitle(a):
                            flagged = True
                        elif _clip_ok:                     # CLIP designed-graphic
                            try:                            # probe (ornate cards)
                                if _vrm.graphic_signal(
                                        str(f), is_video=False
                                ).get("looks_designed"):
                                    flagged = True
                            except Exception:              # noqa: BLE001
                                pass
                except Exception:                          # noqa: BLE001
                    pass
                if flagged:
                    text += 1
            # reject only on a clear MAJORITY of text frames (>=60%), so a single
            # stray flag can never reject a genuine footage clip.
            return text * 5 >= len(frames) * 3
        finally:
            shutil.rmtree(d, ignore_errors=True)
    except Exception:                                          # noqa: BLE001
        return False


def _cached_asset_reusable(cpath, sc=None) -> bool:
    """RC5 — warm-cache re-validation (the warm-cache bypass fix).

    Before a CACHED externally-fetched footage / image asset is reused on a
    cache-hit / scene-reuse / replay path, prove it is still safe. A previously
    cached anime cover / game-UI screenshot / poster could otherwise return on a
    warm rerender WITHOUT going through fresh discovery (the engines may be off
    on a replay) — the VR post-pass re-judges pixels but never consults the
    relevance quarantine, and on a model hiccup can come back unscored. This is
    the cheap guard that closes it:

      • render_quarantine.is_quarantined(path) — a hash/url already barred this
        project (or globally for metadata-obvious game/anime/UI junk) is dropped.
      • visual_relevance.graphic_signal(path) — the keyword-INDEPENDENT designed-
        graphic probe (graphic_dom): catches the cartoon / DVD-cover / poster /
        UI / text-board classes cheaply. We deliberately do NOT re-run the full
        CLIP scene-match here (that is the VR post-pass's job and is more
        expensive) — metadata-quarantine + graphic_dom is enough to catch the
        junk classes the task targets.

    Returns True when the cached asset is safe to reuse. On reject, the poisoned
    cache file is removed so it cannot be re-served, and the caller falls through
    to re-source / the fail-closed ladder. Fully defensive: ANY error → True
    (never block a render on the guard itself; the VR post-pass remains the
    backstop). Synthetic caches (slides, engine cards, AI stills) are NOT routed
    here — only EXTERNALLY-FETCHED photos/clips that could be an off-topic graphic.
    """
    try:
        if cpath is None:
            return True
        _p = str(cpath)
        # (1) quarantine — cheap, no CLIP. Bars a hash/url rejected earlier this
        # project, or globally-obvious metadata junk (game/anime/UI) across runs.
        try:
            from . import render_quarantine as _rq
            if _rq.is_quarantined(_p):
                print(f"  [warm-cache] reject reuse (quarantined): "
                      f"{os.path.basename(_p)}", flush=True)
                try:
                    Path(_p).unlink(missing_ok=True)
                except Exception:                              # noqa: BLE001
                    pass
                return False
        except Exception:                                      # noqa: BLE001
            pass
        # (2) designed-graphic probe — only runs when the CLIP model is loaded;
        # returns looks_designed=False (skipped) otherwise, so a model-absent box
        # falls back to quarantine-only without a per-asset cost.
        try:
            from . import visual_relevance as _vrm
            _is_video = _p.lower().endswith((".mp4", ".mov", ".webm", ".mkv"))
            _g = _vrm.graphic_signal(_p, is_video=_is_video)
            if _g.get("looks_designed"):
                print(f"  [warm-cache] reject reuse (designed-graphic "
                      f"graphic_dom={_g.get('graphic_dom')}): "
                      f"{os.path.basename(_p)}", flush=True)
                try:
                    from . import render_quarantine as _rq2
                    _rq2.quarantine(
                        _p, reason=(f"relevance:warm-cache-designed-graphic "
                                    f"(graphic_dom={_g.get('graphic_dom')})"),
                        replacement_source_type="fallback-ladder",
                        replacement_reason="cached asset now reads as graphic",
                        timestamp=os.environ.get("VIDLORE_RUN_TS", ""))
                except Exception:                              # noqa: BLE001
                    pass
                try:
                    Path(_p).unlink(missing_ok=True)
                except Exception:                              # noqa: BLE001
                    pass
                return False
        except Exception:                                      # noqa: BLE001
            pass
        return True
    except Exception:                                          # noqa: BLE001
        return True


def _portrait_doc_suitable(path, prephoto: bool = False) -> bool:
    """RC5 — documentary-suitability check for a CHOSEN real portrait image.

    Added ON TOP of (never in place of) the identity gate in `_real_person_image`:
    after a portrait has been IDENTITY-VERIFIED (page/name-match) and accepted as
    a real face, this rejects it only when the image itself reads as a
    cartoon / poster / game asset (a stylised non-documentary depiction) via the
    keyword-independent graphic_dom probe — so a named figure never appears as an
    anime/game/poster rendering. On reject the caller drops the candidate and the
    ladder continues to the next real source, then a documentary AI portrait /
    monogram / name-only fallback — NEVER a random AI face for a named figure.

    PRE-PHOTOGRAPHIC curated ARTWORK (`prephoto`: Napoleon/Caesar oil paintings,
    engravings) is EXEMPT — those are legitimately painted (high graphic_dom by
    design) and must be kept. Fully defensive: ANY error, or the scorer being
    unavailable, → True (keep the identity-verified portrait; never block on the
    suitability probe alone). Returns True when the portrait is documentary-safe.
    """
    try:
        if prephoto:
            return True                       # period painting/engraving — keep
        if not path or not Path(path).exists():
            return True
        from . import visual_relevance as _vrm
        _g = _vrm.graphic_signal(str(path), is_video=False)
        if _g.get("looks_designed"):
            print(f"  [real-person] REJECT portrait (cartoon/poster/game "
                  f"graphic_dom={_g.get('graphic_dom')}) -> next tier / "
                  f"AI / monogram", flush=True)
            return False
        return True
    except Exception:                                          # noqa: BLE001
        return True


# RC5 — per-beat relevance VERDICT taxonomy. Maps the free-text `_why` reason a
# VR judge / classifier returns onto a stable, auditable verdict code recorded in
# ASSET_DECISION_MANIFEST.json so every beat's decision can be reviewed without
# re-deriving anything. Pure string logic; never raises.
def _vr_verdict_code(accept: bool, why: str) -> str:
    try:
        if accept:
            return "ACCEPT"
        w = (why or "").lower()
        if "quarantin" in w:
            return "REJECT_QUARANTINED"
        if ("anime" in w or "cartoon" in w or "manga" in w
                or "illustration" in w or "comic" in w):
            return "REJECT_CARTOON_ANIME"
        if ("game" in w or "hud" in w or "screenshot" in w or " ui" in w
                or "interface" in w or "console" in w):
            return "REJECT_GAME_UI"
        if ("poster" in w or "cover" in w or "dvd" in w or "wallpaper" in w
                or "merch" in w or "box art" in w or "boxart" in w):
            return "REJECT_POSTER_OR_COVER"
        if ("text" in w or "sign" in w or "infographic" in w or "chart" in w
                or "logo" in w or "caption" in w or "designed-graphic" in w
                or "graphic-not-footage" in w):
            return "REJECT_TEXT_HEAVY"
        if ("unscored" in w or "unavailable" in w or "low-confidence" in w
                or "low confidence" in w or "no-score" in w or w == "error"):
            return "REJECT_LOW_CONFIDENCE"
        if ("duplicate" in w or "repetition" in w or "weak" in w
                or "no-subject" in w):
            return "REJECT_WEAK_CONNECTION"
        if ("wrong-dominant-concept" in w or "subject-absent" in w
                or "distractor" in w or "crowd" in w or "person-on" in w
                or "war-footage" in w or "vehicle-on" in w or "period" in w
                or "modern" in w or "dark" in w or "clarity" in w):
            return "REJECT_OFF_TOPIC"
        return "REJECT_OFF_TOPIC"
    except Exception:                                          # noqa: BLE001
        return "REJECT_OFF_TOPIC"


def _pexels_fetch(query: str, key: str, dest: Path, variant: int = 0,
                  min_rel: int = 0,
                  seen_links: set | None = None,
                  seen_lock=None) -> bool:
    """Single-query Pexels fetch. `variant` walks distinct videos so
    different beats / a Regenerate get different clips.

    `min_rel` is a RELEVANCE FLOOR: only a clip whose public slug actually
    contains at least `min_rel` of the query words is accepted. With
    `min_rel >= 1` a search that returns only tangential clips (none of the
    query words appear in any slug -> relevance 0) is treated as a MISS, so
    the caller can fall through to the scene-accurate AI shot instead of
    grabbing an off-topic popular clip. This is the core "irrelevant stock"
    fix: e.g. a 1955 Cold-War-Berlin query no longer locks onto a modern
    'hands rolling paper' clip just because Pexels returned something."""
    try:
        r = requests.get(
            _PEXELS_URL,
            headers={"Authorization": key},
            params={"query": query, "per_page": 15,
                    "orientation": "landscape", "size": "medium"},
            timeout=25,
        )
        r.raise_for_status()
        vids = r.json().get("videos", [])
        if not vids:
            return False
        # ONE best file per DISTINCT video, so `variant` walks across
        # different videos (different beats = different footage) — not
        # resolution-variants of the same clip.
        # RELEVANCE RE-RANK: Pexels' own order is good but its top hit is
        # sometimes a tangential popular clip. Each video's public `url`
        # carries a descriptive slug (…/video/aerial-view-of-the-ocean-123/),
        # so we score every candidate by how many of the QUERY words appear
        # in its slug and stable-sort by that score. Ties keep Pexels'
        # order, and when NO slug matches (score all 0) the order is
        # byte-identical to before — so this only ever promotes an
        # obviously-on-topic clip above an off-topic popular one.
        qwords = {w for w in re.split(r"[^a-z0-9]+", query.lower())
                  if len(w) >= 3}
        ranked: list[tuple[int, int, str]] = []   # (relevance, dimscore, link)
        _l2p: dict[str, str] = {}                  # file link -> public page URL
        for v in vids:
            best = None
            for f in v.get("video_files", []):
                w = f.get("width") or 0
                h = f.get("height") or 0
                if w < 1280 or h < 720:
                    continue
                sc = -abs(w - W) - abs(h - H)
                if best is None or sc > best[0]:
                    best = (sc, f["link"])
            if best is None:
                continue
            slug = re.sub(r"[^a-z0-9]+", " ", (v.get("url") or "").lower())
            # CONTENT-TYPE BLOCKLIST — reject abstract data-dashboard / UI /
            # tech-background clips at the metadata level, BEFORE downloading.
            # These leak in via tangential matches on 'data' / 'analysis' /
            # 'tech' in narration and ruin the documentary feel.
            slug_dashes = (v.get("url") or "").lower()
            if any(bad in slug_dashes for bad in _PEXELS_BAD_SLUG):
                continue
            # PERIOD GUARD (search-side): on a pre-1945 documentary, drop a clip
            # whose slug describes a modern subject (a city street with cars, a
            # COVID-masked crowd) before download — the pixel gate can't tell it
            # from genuine period footage, but its slug gives it away. No-op on
            # modern/unknown-era videos.
            if _period_blocked(slug):
                continue
            rel = sum(1 for qw in qwords if f" {qw} " in f" {slug} ")
            ranked.append((rel, best[0], best[1]))
            _l2p[best[1]] = (v.get("url") or "")
        if not ranked:
            return False
        # RELEVANCE FLOOR — drop candidates whose slug shares too few words
        # with the query. With min_rel>=1 a search that returned only
        # off-topic clips (every slug scores 0) yields an empty set here and
        # we report a MISS, so the caller falls through to the AI shot. When
        # the query carries no scorable words (qwords empty) the floor can't
        # apply, so we keep Pexels' own ranking (back-compat).
        if min_rel >= 1 and qwords:
            kept = [t for t in ranked if t[0] >= min_rel]
            if not kept:
                return False
            ranked = kept
        # stable sort by relevance DESC (Python sort is stable, so equal
        # relevance preserves Pexels' original ranking). variant then walks
        # across the re-ordered distinct videos as before.
        ranked.sort(key=lambda t: -t[0])
        # Walk through candidates in rank order. Download each, then run a
        # visual filter — any clip that turns out to be abstract dashboard /
        # UI footage (despite a clean slug) is rejected and we try the next.
        # VIDEO-WIDE DEDUPE (atomic claim — avoids the race where two
        # parallel beats both see seen_links empty, both download the same
        # top-ranked link). Strategy: under the lock, find the FIRST link
        # not yet in seen_links and IMMEDIATELY claim it (add to set)
        # BEFORE downloading. If the download / visual-filter rejects the
        # clip, release the claim and try again.
        n = len(ranked)
        attempts = 0
        while attempts < n:
            attempts += 1
            # ATOMIC CLAIM: pick + reserve next unused link in one lock
            chosen_link = None
            if seen_links is not None and seen_lock is not None:
                with seen_lock:
                    for off in range(n):
                        cand = ranked[(variant + off) % n][2]
                        if cand not in seen_links:
                            chosen_link = cand
                            seen_links.add(cand)        # reserve immediately
                            break
            elif seen_links is not None:
                for off in range(n):
                    cand = ranked[(variant + off) % n][2]
                    if cand not in seen_links:
                        chosen_link = cand
                        seen_links.add(cand)
                        break
            else:
                # No dedupe — pick variant offset as before (back-compat)
                chosen_link = ranked[(variant + attempts - 1) % n][2]
            if chosen_link is None:
                return False                              # all links taken
            link = chosen_link
            # ATOMIC download (.part → os.replace) so the parallel encode
            # pool never reads a half-written / zero-byte clip. A failed or
            # too-small download leaves NO file (claim sticks; try next).
            if not _stream_download_atomic(link, dest, timeout=60,
                                           min_bytes=50_000):
                continue                                       # claim sticks
            if _is_dashboard_clip(dest):
                dest.unlink(missing_ok=True)
                continue                                       # try next
            if _is_generic_stock_clip(dest):
                dest.unlink(missing_ok=True)
                continue
            if _is_blank_bright_clip(dest):                    # near-white blank
                dest.unlink(missing_ok=True)
                continue
            # Good clip kept; the claim was made before download so this
            # link will never be picked again by another scene/beat.
            if os.environ.get("VIDLORE_LOG_STOCK_URL"):
                print(f"  [stock-url] {dest.name} <- {_l2p.get(link, link)}",
                      flush=True)
            return True
        return False
    except Exception:
        return False


def _pexels_clip(scene_or_query, key: str, dest: Path, variant: int = 0,
                 theme_broll: str = "documentary cinematic",
                 domain: str = "", culture: str = "",
                 seen_links: set | None = None,
                 seen_lock=None) -> bool:
    """Walk the semantic->safe query ladder for THIS scene; the first
    SPECIFIC query that returns a real clip wins (best relevance). If
    only the generic on-theme tail would match, return False so the
    caller uses the precise AI-directed shot instead of a generic clip
    (this is the core of the Issue #1 footage-relevance fix).

    `seen_links` is a SHARED set across the whole render — any link
    already consumed by another scene is rejected so the same Pexels
    clip never repeats in one video.

    Back-compat: a plain string still works as a single literal query."""
    if isinstance(scene_or_query, str):
        return _pexels_fetch(scene_or_query, key, dest, variant,
                              seen_links=seen_links, seen_lock=seen_lock)
    for q, is_specific in _pexels_queries(scene_or_query, theme_broll,
                                          domain, culture):
        if not is_specific:
            break  # only the generic tail left -> let AI tier take it
        # Require the matched clip to actually share a word with the query
        # (relevance floor) — a search that only returns tangential popular
        # clips is a MISS, so we keep walking the ladder and ultimately let
        # the AI-directed shot win rather than locking onto off-topic stock.
        if _pexels_fetch(q, key, dest, variant, min_rel=1,
                         seen_links=seen_links, seen_lock=seen_lock):
            return True
    return False


# --------------------------------------------------------------------------- #
# Shutterstock VIDEO search (optional tier 2)
# --------------------------------------------------------------------------- #
# Mirrors the Pexels client: same relevance floor, same bad-slug
# rejection, same dashboard/generic-stock visual filter, same
# variant-walks-distinct-videos contract.  Tried AFTER Pexels misses
# but BEFORE the AI tiers, so a real-world Shutterstock clip beats an
# AI render when stock has the shot.
#
# IMPORTANT — license / watermark caveat (do not ignore for production):
#   Shutterstock's `assets.preview_mp4.url` returns a WATERMARKED preview
#   for search-only / free-trial tokens.  For unwatermarked masters the
#   account needs a paid subscription and a license call before download.
#   This client uses the preview URL by default; it logs a one-line
#   warning the first time a Shutterstock clip is selected so the user
#   knows the deliverable will carry a watermark unless their token has
#   license access.

# SAFEGUARDS:
#   _SHUTTERSTOCK_WARNED_WATERMARK — one-line "preview is watermarked"
#                                    warning, printed at most once.
#   _SHUTTERSTOCK_USE_COUNT        — running tally of how many clips
#                                    THIS render has pulled from
#                                    Shutterstock.  Reset by
#                                    `reset_shutterstock_counter()`
#                                    at the start of every render.
#   VIDLORE_SHUTTERSTOCK=0         — disable entirely (kill switch).
#   VIDLORE_SHUTTERSTOCK_MAX=N     — hard cap on clips per render
#                                    (default 5 during free-trial /
#                                    cost-conscious phase).  Set to
#                                    a large number once on a paid
#                                    license.
_SHUTTERSTOCK_WARNED_WATERMARK = False
_SHUTTERSTOCK_USE_COUNT = 0


def reset_shutterstock_counter() -> None:
    """Called at the start of each render to zero the per-video
    Shutterstock usage tally.  Pipeline calls this in render_from_script
    so the cap is per-render, not per-process."""
    global _SHUTTERSTOCK_USE_COUNT, _SHUTTERSTOCK_WARNED_WATERMARK
    _SHUTTERSTOCK_USE_COUNT = 0
    _SHUTTERSTOCK_WARNED_WATERMARK = False


def _shutterstock_enabled() -> bool:
    """Honour the VIDLORE_SHUTTERSTOCK=0 kill switch."""
    v = os.environ.get("VIDLORE_SHUTTERSTOCK", "1").strip().lower()
    return v not in ("0", "false", "no", "off")


def _shutterstock_cap() -> int:
    """Per-render cap.  Default 5 = cost-conscious for free-trial /
    quota-limited tokens.  Override via VIDLORE_SHUTTERSTOCK_MAX env."""
    try:
        return max(0, int(os.environ.get("VIDLORE_SHUTTERSTOCK_MAX", "5")))
    except ValueError:
        return 5


def _shutterstock_fetch(query: str, key: str, dest: Path,
                        variant: int = 0, min_rel: int = 0,
                        seen_links: set | None = None,
                        seen_lock=None) -> bool:
    """Single-query Shutterstock fetch.  Mirrors `_pexels_fetch`:
      • `variant` walks distinct videos
      • `min_rel` is the relevance floor (per-slug word overlap)
      • applies the same bad-slug and dashboard / generic-stock visual
        rejection so corporate stock leaks are filtered before commit.

    Returns True on a clean download, False on any miss / error.
    Authentication uses `Authorization: Bearer <key>` (the standard
    Shutterstock OAuth bearer header).  401/403 → silent miss so the
    caller falls through to the next source.

    SAFEGUARDS:
      • kill switch:  VIDLORE_SHUTTERSTOCK=0 → return False immediately.
      • per-render cap: stop firing after VIDLORE_SHUTTERSTOCK_MAX (5)
        clips have been pulled this render.
      • watermark warning: printed once per render when the first clip
        is selected (preview MP4s are watermarked unless the token has
        license scope)."""
    global _SHUTTERSTOCK_WARNED_WATERMARK, _SHUTTERSTOCK_USE_COUNT
    if not key:
        return False
    if not _shutterstock_enabled():
        return False
    cap = _shutterstock_cap()
    if _SHUTTERSTOCK_USE_COUNT >= cap:
        # Per-render cap reached — silent fall-through to next source.
        return False
    try:
        r = requests.get(
            _SHUTTERSTOCK_URL,
            headers={
                "Authorization": f"Bearer {key}",
                "Accept": "application/json",
            },
            params={
                "query": query,
                "per_page": 15,
                # Shutterstock enum format uses underscore (16_9), not
                # colon — colon returns a 400 VALIDATION_ENUM_MISMATCH.
                "aspect_ratio": "16_9",
                "sort": "popular",
            },
            timeout=25,
        )
        if r.status_code in (401, 403):
            # Token rejected (missing license / wrong scope) — silent
            # miss so the cascade continues.
            return False
        r.raise_for_status()
        data = r.json().get("data", []) or []
        if not data:
            return False
        qwords = {w for w in re.split(r"[^a-z0-9]+", query.lower())
                  if len(w) >= 3}
        ranked: list[tuple[int, str, str]] = []   # (relevance, slug, link)
        for v in data:
            assets = v.get("assets") or {}
            preview = (assets.get("preview_mp4") or {}).get("url") or ""
            if not preview:
                # Fallback: some accounts only get `thumb_video` previews.
                preview = (assets.get("thumb_video") or {}).get("url") or ""
            if not preview:
                continue
            descr = (v.get("description") or "").lower()
            slug = re.sub(r"[^a-z0-9]+", " ", descr)
            # Reuse Pexels' corporate-stock blocklist on the description.
            if any(bad in descr for bad in _PEXELS_BAD_SLUG):
                continue
            # PERIOD GUARD (search-side): drop a modern-era clip on a pre-1945
            # documentary before download (see _period_blocked / _pexels_fetch).
            if _period_blocked(slug):
                continue
            rel = sum(1 for qw in qwords if f" {qw} " in f" {slug} ")
            ranked.append((rel, slug, preview))
        if not ranked:
            return False
        if min_rel >= 1 and qwords:
            kept = [t for t in ranked if t[0] >= min_rel]
            if not kept:
                return False
            ranked = kept
        ranked.sort(key=lambda t: -t[0])
        n = len(ranked)
        attempts = 0
        while attempts < n:
            attempts += 1
            # ATOMIC CLAIM (see _pexels_fetch for full reasoning)
            chosen_link = None
            if seen_links is not None and seen_lock is not None:
                with seen_lock:
                    for off in range(n):
                        cand = ranked[(variant + off) % n][2]
                        if cand not in seen_links:
                            chosen_link = cand
                            seen_links.add(cand)
                            break
            elif seen_links is not None:
                for off in range(n):
                    cand = ranked[(variant + off) % n][2]
                    if cand not in seen_links:
                        chosen_link = cand
                        seen_links.add(cand)
                        break
            else:
                chosen_link = ranked[(variant + attempts - 1) % n][2]
            if chosen_link is None:
                return False
            link = chosen_link
            # ATOMIC download (.part → os.replace): the parallel encode pool
            # never observes a half-written / zero-byte clip.
            if not _stream_download_atomic(link, dest, timeout=60,
                                           min_bytes=50_000):
                continue
            if _is_dashboard_clip(dest):
                dest.unlink(missing_ok=True)
                continue
            if _is_generic_stock_clip(dest):
                dest.unlink(missing_ok=True)
                continue
            if _is_blank_bright_clip(dest):                    # near-white blank
                dest.unlink(missing_ok=True)
                continue
            _SHUTTERSTOCK_USE_COUNT += 1
            if not _SHUTTERSTOCK_WARNED_WATERMARK:
                _SHUTTERSTOCK_WARNED_WATERMARK = True
                print(
                    "  [shutterstock] first clip selected — note: "
                    "preview MP4s carry a WATERMARK unless your "
                    "token has license scope (license + /licenses/"
                    "videos download flow not yet wired); cap this "
                    "render at %d clips" % cap, flush=True)
            print(
                "  [shutterstock] clip %d/%d  q='%s' -> %s"
                % (_SHUTTERSTOCK_USE_COUNT, cap, query[:48],
                   dest.name), flush=True)
            return True
        return False
    except Exception:                                          # noqa: BLE001
        return False


def _shutterstock_clip(scene_or_query, key: str, dest: Path,
                       variant: int = 0,
                       theme_broll: str = "documentary cinematic",
                       domain: str = "", culture: str = "",
                       seen_links: set | None = None,
                       seen_lock=None) -> bool:
    """Walk the same query ladder Pexels uses, but hit Shutterstock.
    Same SPECIFIC-only contract: only the SPECIFIC rungs fire here
    (the generic tail falls through to AI / generic-stock tiers).

    `seen_links` participates in the same video-wide dedupe set used
    for Pexels, so a Shutterstock link can also block a later Pexels
    fetch (cross-provider dedupe is by exact URL only, but that's
    enough — collisions only happen within one provider in practice)."""
    if isinstance(scene_or_query, str):
        return _shutterstock_fetch(scene_or_query, key, dest, variant,
                                    seen_links=seen_links, seen_lock=seen_lock)
    for q, is_specific in _pexels_queries(scene_or_query, theme_broll,
                                          domain, culture):
        if not is_specific:
            break
        if _shutterstock_fetch(q, key, dest, variant, min_rel=1,
                                seen_links=seen_links, seen_lock=seen_lock):
            return True
    return False


# --------------------------------------------------------------------------- #
# Pollinations AI image (free, keyless; key only lifts rate limits)
