# reportage feel" as HEAVY baked-in grain that NO post-grade can later remove
# (user: a clean AI WWII war-room recreation still looked like noisy degraded
# film). Default is now a CLEAN modern documentary capture; restore the filmic-
# grain wording any time with VIDLORE_AI_FILM_GRAIN=1.
_AI_FILM_GRAIN = os.environ.get("VIDLORE_AI_FILM_GRAIN", "0").strip().lower() \
    in ("1", "true", "yes", "on")
_STYLE = (
    "Photorealistic documentary photography, natural source lighting, "
    "motivated practical light only, restrained colour grade, muted "
    "desaturated palette, shallow depth of field with realistic lens "
    "falloff, clean sharp modern digital capture, candid unposed framing, "
    "observed moment, professional documentary still. "
    + ("shot on 35mm film, Kodak Portra 400 grain, subtle film grain, "
       "slight lens imperfections, archival reportage feel. "
       if _AI_FILM_GRAIN else "")
    + "AVOID: digital art, illustration, painting, render, fantasy, "
    "surreal, glossy, over-sharpened, perfect-skin retouching, plastic "
    "highlights, lens flare effects, Midjourney aesthetic, AI-art look, "
    "stylised, neon, hyper-saturated, "
    + ("" if _AI_FILM_GRAIN else
       "heavy film grain, visible noise, grainy, speckled, vintage degraded "
       "film, aged film, scratches, dust, heavy sepia, washed-out faded, ")
    + "no text, no words, no caption, no watermark, no logo, no border, "
    "no UI, no screenshot"
)


# --------------------------------------------------------------------------- #
# AI BUDGET + PURPOSE GATE
# --------------------------------------------------------------------------- #
# Symbolic / abstract / unfilmable keyword cues -- when these appear in a
# scene's narration, AI generation is one of the few ways to produce a
# specific relevant visual. Used by ``_ai_purpose_appropriate``.
_AI_SYMBOLIC_HINTS: tuple[str, ...] = (
    # covert / intelligence / secrecy
    "secret meeting", "secret room", "covert ", "classified",
    "intelligence briefing", "intelligence agency", "intelligence officer",
    "spy ", "spies ", "double agent", "espionage",
    "tunnel", "underground", "hidden chamber", "hidden room",
    "listening post", "wiretap", "intercept", "decode",
    # historical reconstruction
    "ancient", "medieval", "renaissance", "centuries ago",
    "long before", "before photography", "before cameras",
    "lost civilisation", "lost civilization",
    # symbolic / atmospheric
    "silhouette", "lone figure", "alone in", "in shadow",
    "burning document", "shredded paper", "red phone", "war room",
    "candlelit", "lamplit", "lantern light",
    # conceptual / impossible-to-film
    "psychological", "consciousness", "the mind", "inside the mind",
    "the human brain", "neural", "hidden network", "covert network",
    "manipulation", "propaganda machine",
)


def _ai_purpose_appropriate(sc, beat_idx: int, total_beats: int) -> str:
    """Return a non-empty PURPOSE string when AI generation suits this
    scene; empty string -> AI is a poor fit (keep stock).

    Now LOOSER (user feedback: 'minimum 8 AI per video').  Any of:
        - scene was marked _ai_priority_target by the top-N pre-selection
          (beat 0 only -- one AI per priority scene, not per beat)
        - LLM 'visual' says reconstruction / reenactment / depiction
        - narration is unfilmable historical (pre-photography era)
        - narration carries a symbolic / atmospheric cue OR a subject word
        - scene role is hook / reveal / climax / turn (high-impact beat)
    """
    # ---- PRIORITY FORCE (min-8 floor) ----------------------------------
    # If fetch_footage pre-selected this (scene, beat) pair as one of the
    # top-N AI targets, return a guaranteed purpose.  New scheme: a SET
    # of beat indices per scene (so short briefs can hit the min-8 floor
    # by spending multiple beats per scene).  Legacy boolean flag is
    # honoured for back-compat: if no set is present but the legacy
    # `_ai_priority_target` is True, beat 0 still gets the purpose.
    _pri_beats = getattr(sc, "_ai_priority_beats", None)
    if _pri_beats is not None:
        if beat_idx in _pri_beats:
            return "priority_target"
    elif beat_idx == 0 and getattr(sc, "_ai_priority_target", False):
        return "priority_target"

    role = (getattr(sc, "role", "") or "").lower()
    narration = (getattr(sc, "narration", "") or "").lower()
    visual = (getattr(sc, "visual", "") or "").lower()
    blob = " " + narration + " " + visual + " "

    if visual and any(k in visual for k in (
            "reconstruction", "reenactment", "re-enactment",
            "dramatisation", "dramatization", "depiction of",
            "imagined scene", "imagined moment")):
        return "llm_directed"

    if any(k in blob for k in (
            "before photography", "before cameras", "before film",
            "long before recording", "in antiquity",
            "in the ancient world", "centuries ago",
            "thousands of years ago", "the medieval era",
            "the renaissance era", "no photographs survive",
            "no recording exists", "lost to history",
            "1850", "1860", "1870", "1880", "1890",
            "1900", "1910", "1920", "1930")):
        return "deep_historical"

    # Symbolic / conceptual cues -- subject OR atmosphere now
    # (was an AND pair; too strict for the 8-per-video minimum target).
    SUBJ_OR_ATMOSPH = (
        "spy", "spies", "covert", "classified", "intelligence",
        "intercept", "wiretap", "interrogation", "agent",
        "tunnel", "underground", "bunker", "war room",
        "hidden", "secret", "covert operation",
        "burning paper", "shredded", "code book", "cipher",
        "psychological", "consciousness", "the mind",
        "silhouette", "lone figure", "alone in",
        "in shadow", "in shadows", "shadowed",
        "candlelit", "lamplit", "lantern light",
        "dimly lit", "moonlit",
    )
    if any(s in blob for s in SUBJ_OR_ATMOSPH):
        return "symbolic_concept"

    # ── HIGH-IMPACT narrative gates (TIGHTENED) ─────────────────────
    # Old gate ran on EVERY hook/tease/open/stakes/reveal/turn/climax
    # role — which on a 6-scene doc meant most beats qualified.  New
    # rule: only fire AI when the narrative role is the climax/reveal
    # itself, AND the scene's intensity is in the top tier (4-5).  The
    # opening hook gets its own dedicated path (the character intro
    # check above) so we don't double-stack AI on the cold open.
    try:
        intensity = int(getattr(sc, "intensity", 0) or 0)
    except (TypeError, ValueError):
        intensity = 0
    if role in ("reveal", "turn", "climax") and intensity >= 4:
        return "climax_reveal"

    return ""


def _ai_priority_score(sc) -> float:
    """0..100 score for how worthy this scene is for an AI image.
    Higher = better candidate. Used to PICK the top-N scenes for
    guaranteed AI generation when the user sets a MIN target."""
    role = (getattr(sc, "role", "") or "").lower()
    narration = (getattr(sc, "narration", "") or "").lower()
    visual = (getattr(sc, "visual", "") or "").lower()
    blob = " " + narration + " " + visual + " "
    score = 20.0

    # Role weights -- high-impact beats deserve the strongest visuals
    role_w = {
        "hook": 35, "tease": 35, "open": 32, "stakes": 30,
        "reveal": 32, "turn": 30, "climax": 32,
        "evidence": 18, "context": 12, "payoff": 22, "aftermath": 18,
    }
    score += role_w.get(role, 12)

    # Content cues
    if any(k in blob for k in ("spy", "agent", "officer", "elder",
                                "leader", "his name", "her name",
                                "named", "called")):
        score += 18                          # character moment
    if any(k in blob for k in ("silhouette", "shadow", "tunnel",
                                "underground", "candlelit", "hidden",
                                "war room")):
        score += 15                          # symbolic / atmospheric
    if any(k in blob for k in ("1850", "1860", "1870", "1880", "1890",
                                "1900", "ancient", "century-old",
                                "centuries", "long before")):
        score += 14                          # historical
    if any(k in visual for k in ("reconstruction", "reenactment",
                                  "depiction of", "imagined")):
        score += 20                          # LLM explicitly asked
    # Penalise scenes already perfectly served by stock
    if any(k in blob for k in ("modern", "today", "current", "right now",
                                "in our era")):
        score -= 12
    return max(0.0, min(100.0, score))


class AIBudget:
    """Hard-cap + per-purpose AI usage tracker, shared across the beat
    thread pool.  Caller flow::

        purpose = _ai_purpose_appropriate(sc, beat_idx, total_beats)
        if purpose and budget.claim(purpose):
            ok = _fal_image(...)
            if not ok: budget.refund(purpose)
    """
    def __init__(self, total_beats: int, cap_fraction: float = 0.05) -> None:
        import threading as _t
        self.total = max(1, int(total_beats))
        # at least 1 generation allowed for non-trivial videos; otherwise 0
        # which the gate uses to refuse AI entirely.
        cap = max(0, int(round(self.total * float(cap_fraction))))
        if self.total >= 12 and cap < 1:
            cap = 1                 # let an intro hook through even on short docs
        self.cap = cap
        self.used = 0
        self.used_by_purpose: dict[str, int] = {}
        self._lock = _t.Lock()

    def claim(self, purpose: str) -> bool:
        if not purpose or self.cap <= 0:
            return False
        with self._lock:
            if self.used >= self.cap:
                return False
            self.used += 1
            self.used_by_purpose[purpose] = (
                self.used_by_purpose.get(purpose, 0) + 1)
            return True

    def refund(self, purpose: str) -> None:
        with self._lock:
            if self.used > 0:
                self.used -= 1
            if purpose and self.used_by_purpose.get(purpose, 0) > 0:
                self.used_by_purpose[purpose] -= 1

    def stats(self) -> dict:
        with self._lock:
            return {
                "cap": self.cap,
                "used": self.used,
                "total_beats": self.total,
                "share_pct": round(100.0 * self.used / self.total, 1),
                "by_purpose": dict(self.used_by_purpose),
            }


# ─────────────────────── AI-still telemetry (provider policy) ───────────────
# User policy (2026-06-02): fal.ai is the PRIMARY AI-still provider with NO
# fixed image ceiling; every generation is validated and may be retried; cost,
# latency and accept/reject are logged for every still. This module-level,
# thread-safe collector records one entry per generation attempt and aggregates
# the totals the audit asks for (total fal generations / cost / avg latency /
# rejected / retried / cache hits). It writes AI_STILL_LOG.json next to the
# render's ASSET_DECISION_MANIFEST.json. No secrets are ever recorded.
def _fal_cost_per_image() -> float:
    """Best-effort per-image USD cost ESTIMATE for the active fal model.
    Override with VIDLORE_FAL_COST_PER_IMAGE. Default ≈ fal-ai/flux/schnell
    landscape_16_9 (~0.6 MP × ~$0.003/MP ≈ $0.0018). It is an estimate for
    budgeting/audit only — fal's invoice is authoritative."""
    try:
        v = os.environ.get("VIDLORE_FAL_COST_PER_IMAGE", "").strip()
        if v:
            return max(0.0, float(v))
    except Exception:                                          # noqa: BLE001
        pass
    return 0.0018


def _imagen_cost_per_image() -> float:
    """Per-image USD cost estimate for the active Imagen model. Default ≈
    Imagen 4 Fast ($0.02/image, 2026). Override with VIDLORE_IMAGEN_COST_PER_IMAGE.
    Estimate for budgeting/audit only — Google's invoice is authoritative."""
    try:
        v = os.environ.get("VIDLORE_IMAGEN_COST_PER_IMAGE", "").strip()
        if v:
            return max(0.0, float(v))
    except Exception:                                          # noqa: BLE001
        pass
    _model = os.environ.get("VIDLORE_IMAGEN_MODEL", "imagen-4.0-fast-generate-001")
    if "ultra" in _model:
        return 0.06
    if "fast" in _model:
        return 0.02
    return 0.04          # standard Imagen 3/4


class _AIStillLog:
    """Thread-safe per-render telemetry for AI still generation."""
    def __init__(self) -> None:
        import threading as _t
        self._lock = _t.Lock()
        self.entries: list = []

    def reset(self) -> None:
        with self._lock:
            self.entries = []

    def record(self, entry: dict) -> None:
        with self._lock:
            self.entries.append(dict(entry))

    def summary(self) -> dict:
        with self._lock:
            es = list(self.entries)
        def _p(provider):
            return [e for e in es if e.get("provider") == provider]
        fal = _p("fal")
        polli = _p("pollinations")
        imagen = _p("imagen")
        fal_live = [e for e in fal if not e.get("cache_hit")]
        fal_gen = [e for e in fal_live if e.get("generated")]
        fal_acc = [e for e in fal if e.get("accepted")]
        fal_rej = [e for e in fal_live if e.get("generated")
                   and not e.get("accepted")]
        fal_lat = [e.get("latency_s") for e in fal_gen
                   if isinstance(e.get("latency_s"), (int, float))]
        # Imagen 4 Fast is PRIMARY (user 2026-06-06): track its generations +
        # cost so the per-render audit is accurate when most stills are Imagen.
        img_live = [e for e in imagen if not e.get("cache_hit")]
        img_gen = [e for e in img_live if e.get("generated")]
        img_acc = [e for e in imagen if e.get("accepted")]
        img_cost = round(len(img_gen) * _imagen_cost_per_image(), 4)
        fal_cost = round(len(fal_gen) * _fal_cost_per_image(), 4)
        return {
            "primary_provider": "imagen" if imagen else "fal",
            "imagen_generations": len(img_gen),
            "imagen_accepted": len(img_acc),
            "imagen_cache_hits": sum(1 for e in imagen if e.get("cache_hit")),
            "imagen_total_cost_usd_est": img_cost,
            "imagen_cost_per_image_usd_est": _imagen_cost_per_image(),
            "fal_generations": len(fal_gen),
            "fal_accepted": len(fal_acc),
            "fal_rejected_images": len(fal_rej),
            "fal_retried_beats": sum(1 for e in fal
                                     if (e.get("retry_count") or 0) > 0
                                     and e.get("accepted")),
            "fal_total_cost_usd_est": fal_cost,
            "fal_avg_latency_s": (round(sum(fal_lat) / len(fal_lat), 2)
                                  if fal_lat else None),
            "fal_cache_hits": sum(1 for e in fal if e.get("cache_hit")),
            "pollinations_emergency_used": len([e for e in polli
                                                if e.get("accepted")]),
            "ai_still_total_cost_usd_est": round(img_cost + fal_cost, 4),
            "cost_per_image_usd_est": _fal_cost_per_image(),
            "total_attempts": len(es),
        }

    def write(self, run_dir) -> None:
        try:
            import json as _json
            from pathlib import Path as _P
            with self._lock:
                es = list(self.entries)
            (_P(run_dir) / "AI_STILL_LOG.json").write_text(_json.dumps({
                "policy": "Google Imagen 4 Fast PRIMARY; fal.ai FLUX SECONDARY "
                          "(used when Imagen is unavailable/errors, and forced on "
                          "the last ladder rung); Pollinations emergency-only. Every "
                          "still validated + retried. Costs are ESTIMATES "
                          "(VIDLORE_IMAGEN_COST_PER_IMAGE / VIDLORE_FAL_COST_PER_IMAGE).",
                "summary": self.summary(),
                "attempts": es,
            }, indent=1, default=str))
        except Exception:                                      # noqa: BLE001
            pass


_AISTILL = _AIStillLog()


# ── AI-still prompt sanitizer (Phase-2 visual polish, 2026-06-06) ──────
# fal / pollinations bake garbled, hallucinated glyphs whenever a prompt
# asks for SPECIFIC legible text or numbers inside the picture — the
# scene-0 "$40,000,000 budget document" came back reading "$40,00,000"
# with nonsense headings ("AQUNE ACUTIC WEED CONTROL"). Documentary data
# belongs in the engine's OWN overlays (typographically correct), never
# painted into the AI photo. This strips only the "render this exact
# text/number" instructions from a visual prompt and preserves the rest of
# the scene description. It fires ONLY when such an instruction is present,
# so ordinary prompts pass through byte-identical (most stills unchanged).
_PROMPT_TEXT_CUE = re.compile(
    r"\b("
    r"in\s+(?:bold\s+)?(?:black|red|white|gold|blue|dark|large)?\s*"
    r"(?:ink|lettering|type(?:face)?|font|print|capitals|caps)"
    r"|the\s+(?:figure|number|numerals?|word|words|text|phrase|headline|"
    r"heading|title|caption|label|amount|sum|date|sign|slogan|inscription)"
    r"|(?:bold|large|small|red|black|white|gold)\s+(?:ink|lettering|text|"
    r"type|print|capital|caps|headline|heading|title|stamp|numerals?)"
    r"|stamp(?:ed)?|emboss(?:ed)?|engrav(?:ed|ing)|hand-?written|typewritten|"
    r"typed|inscrib(?:ed|ing)|lettered|labell?ed|captioned|titled|"
    r"reads?\b|reading\b|spelling|spelled|that\s+says|which\s+says|saying"
    r")\b",
    re.IGNORECASE)
_PROMPT_QUOTED = re.compile(
    r"['\"‘’“”][^'\"‘’“”]{1,70}"
    r"['\"‘’“”]")
_PROMPT_MONEY = re.compile(r"[$£€]\s?\d[\d,.\s]{1,}")


def _sanitize_visual_prompt(visual: str) -> str:
    """Drop clauses that instruct the model to render legible text/numbers
    into the picture; keep the rest of the scene description. Returns the
    cleaned string (== input when nothing matches). Never raises."""
    try:
        s = (visual or "").strip()
        if not s:
            return s
        if not (_PROMPT_TEXT_CUE.search(s) or _PROMPT_QUOTED.search(s)
                or _PROMPT_MONEY.search(s)):
            return s                       # fast path: nothing to strip
        parts = re.split(r"\s*[,;]\s+", s)
        kept = []
        for seg in parts:
            if _PROMPT_TEXT_CUE.search(seg) or _PROMPT_QUOTED.search(seg):
                continue                   # offending clause → drop entirely
            kept.append(seg.strip())
        out = ", ".join(k for k in kept if k).strip()
        out = re.sub(r"\s{2,}", " ", out)
        out = re.sub(r"\s+,", ",", out).strip(" ,;")
        if len(out) < 18:                  # never send an empty/too-thin prompt
            out = _PROMPT_MONEY.sub("", _PROMPT_QUOTED.sub("", s))
            out = re.sub(r"\s{2,}", " ", out).strip(" ,;")
        return out or s
    except Exception:                                              # noqa: BLE001
        return visual or ""


def _polli_prompt(scene: Scene) -> str:
    """Prefer the LLM visual-director shot (a precise description of what
    THIS sentence should show) — that is what makes footage intentional
    and emotionally synced. With no LLM, derive a prompt from the
    narration itself so the picture still depicts what is being said."""
    visual = _sanitize_visual_prompt((getattr(scene, "visual", "") or "").strip())
    if visual:
        return f"{visual}. {_STYLE}"
    text = re.sub(r"\s+", " ", scene.narration).strip()
    situation = " ".join(text.split()[:36]).rstrip(".,;:")
    subject = ", ".join(scene.keywords[:3]) if scene.keywords else ""
    head = f"{subject}. " if subject else ""
    return f"{head}{situation}. {_STYLE}"


def _fal_prompt_variants(scene: Scene, base_prompt: str) -> list:
    """Ordered (label, prompt) RETRY LADDER for a fal still that failed visual
    validation (user provider policy, 2026-06-02):

        base → improved-literal → simplified → alternate-composition

    Every rung stays on the SAME subject (it never drifts off-topic); only the
    phrasing / framing changes so the model gets a fresh, cleaner attempt at a
    literal, documentary-suitable image. A different seed is used per rung by
    the caller. Duplicate prompt strings are collapsed so we never spend a fal
    call re-rendering an identical request."""
    kws = [k.strip() for k in (getattr(scene, "keywords", None) or [])
           if isinstance(k, str) and k.strip()]
    subj = ", ".join(kws[:4]) if kws else ""
    if not subj:
        _t = re.sub(r"\s+", " ",
                    (getattr(scene, "narration", "") or "")).strip()
        subj = " ".join(_t.split()[:8]).rstrip(".,;:")
    visual = _sanitize_visual_prompt((getattr(scene, "visual", "") or "").strip())
    out = [("base", base_prompt)]
    if subj:
        out.append((
            "improved-literal",
            f"A clear, literal documentary photograph of {subj}. "
            f"{(visual + '. ') if visual else ''}{_STYLE}"))
        out.append(("simplified", f"{subj}. {_STYLE}"))
        out.append((
            "alt-composition",
            f"Wide establishing documentary shot of {subj}, environmental "
            f"context, eye-level, natural light. {_STYLE}"))
    # collapse duplicate prompt strings, preserving order + first label
    seen: set = set()
    uniq: list = []
    for lbl, p in out:
        if p not in seen:
            seen.add(p)
            uniq.append((lbl, p))
    return uniq


