def _looks_like_face(src: Path) -> bool:
    """Light heuristic: does this image plausibly contain a human face?

    No face-detection model available — instead check for a meaningful
    fraction of skin-tone pixels concentrated in the upper-center region
    (where a portrait's face sits) AND reject near-uniform / text / very
    low-detail images. Used to validate real-person photos pulled from
    Wikimedia Commons so a name search that returns a building / flag /
    logo doesn't get used as someone's portrait.
    """
    try:
        import numpy as np
        img = Image.open(src).convert("RGB")
        if min(img.size) < 80:
            return False
        a = np.asarray(img.resize((96, 96), Image.BILINEAR), dtype="float32")
        R, G, B = a[..., 0], a[..., 1], a[..., 2]
        # Broad skin-tone mask (covers light→dark skin): R>G>B ordering,
        # R reasonably high, modest saturation.
        skin = (
            (R > 60) & (R < 250) & (G > 35) & (B > 20)
            & (R > G) & (G > B * 0.92)
            & ((R - B) > 12) & ((R - B) < 130)
        )
        frac_all = float(skin.mean())
        # Upper-center band (rows 12..64, cols 24..72) — face zone.
        band = skin[12:64, 24:72]
        frac_face = float(band.mean())
        # Need some skin in the face zone, not just scattered noise.
        return frac_face > 0.12 and frac_all > 0.06
    except Exception:                                       # noqa: BLE001
        return False


# V1.1 — provenance of the last real-person portrait resolved per name, so the
# pipeline/manifest can record where a famous face actually came from.
_PORTRAIT_PROVENANCE: dict = {}

# RC4 — the FILE/ITEM title of the image a name-search source (Commons / LoC)
# actually chose, captured so `_real_person_image` can IDENTITY-VERIFY it
# (`_name_match`) before trusting an unverified face. Name search alone returns
# a hit for ANY plausible match, so a wrong cleric's photo could be selected
# for "Ayatollah Khomeini"; these let the caller reject a title that does not
# name the requested person. Reset to None at the start of every search.
_LAST_WIKIMEDIA_TITLE: str | None = None
_LAST_LOC_TITLE: str | None = None

# RC4 — leading honorific / title tokens that are NOT part of a person's given
# name. Stripping them lets the page-verified Wikipedia lead-image gate match
# the REAL article ("Ayatollah Khomeini" → "Khomeini" → the genuine portrait).
_HONORIFIC_PREFIXES = (
    "ayatollah", "grand ayatollah", "president", "vice president",
    "prime minister", "deputy prime minister", "minister", "general",
    "lieutenant general", "major general", "brigadier general", "admiral",
    "vice admiral", "rear admiral", "imam", "grand imam", "sheikh", "shaikh",
    "shaykh", "king", "queen", "shah", "sultan", "dr", "doctor", "sir",
    "saint", "st", "pope", "supreme leader", "grand", "emperor", "empress",
    "colonel", "lieutenant colonel", "captain", "major", "commander",
    "marshal", "field marshal", "chancellor", "premier", "lord", "lady",
    "prince", "princess", "tsar", "czar", "kaiser",
)

# RC4 — canonical Wikipedia article titles for figures whose COMMON reference
# (title+surname, or a bare surname) resolves on Wikipedia to a same-surname
# RELATIVE, not the famous person. Surname matching CANNOT disambiguate these:
# "Khomeini" and "Ayatollah Khomeini" both resolve to *Ahmad* Khomeini (the son),
# whose page legitimately contains "Khomeini" — only the full given name
# "Ruhollah Khomeini" reaches the real article. Mapping the common reference to
# the exact biography title fixes the central case; when a name is NOT here, the
# surname-only reference is treated as identity-ambiguous (→ monogram, never a
# wrong face). Extend as needed.
_CANONICAL_PORTRAIT_NAME = {
    "khomeini": "Ruhollah Khomeini",
    "ayatollah khomeini": "Ruhollah Khomeini",
    "grand ayatollah khomeini": "Ruhollah Khomeini",
    "imam khomeini": "Ruhollah Khomeini",
    "ayatollah ruhollah khomeini": "Ruhollah Khomeini",
}


def _is_surname_only_reference(name: str) -> bool:
    """RC4 — True when, after stripping honorifics, only a single (surname) token
    remains AND it is not a canonical alias. Such a reference ("Ayatollah
    Khomeini", "General Patton") is identity-AMBIGUOUS — a bare surname can match
    a relative — so a sourced face cannot be trusted; the caller falls back to a
    monogram / name-only card rather than risk the wrong person."""
    raw = (name or "").strip()
    if not raw or raw.lower() in _CANONICAL_PORTRAIT_NAME:
        return False
    toks = [t for t in re.split(r"\s+", raw) if t]
    low = [t.lower().strip(".,") for t in toks]
    i = 0
    multi = sorted((p for p in _HONORIFIC_PREFIXES if " " in p),
                   key=lambda s: -len(s.split()))
    single = {p for p in _HONORIFIC_PREFIXES if " " not in p}
    while i < len(toks) - 1:
        m = False
        for phrase in multi:
            pl = phrase.split(); n = len(pl)
            if i + n <= len(toks) - 1 and low[i:i + n] == pl:
                i += n; m = True; break
        if m:
            continue
        if low[i] in single:
            i += 1; continue
        break
    return (len(toks) - i) <= 1


def _person_name_variants(name: str) -> list[str]:
    """RC4 — yield identity-verification name variants, honorific-normalized.

    Returns the original name plus a copy with any leading honorific/title
    tokens stripped ("Ayatollah Khomeini" → "Khomeini", "President Saddam
    Hussein" → "Saddam Hussein"). Deduplicated, order-preserved, and every
    variant keeps at least one token. Used to retry the page-title-verified
    Wikipedia lead-image lookup so an honorific never hides the real portrait."""
    raw = (name or "").strip()
    if not raw:
        return []
    # RC4 — a disambiguated canonical biography title (e.g. "Ayatollah Khomeini"
    # → "Ruhollah Khomeini") is tried FIRST so the page-verified lead image is
    # the famous person, not a same-surname relative.
    _canon = _CANONICAL_PORTRAIT_NAME.get(raw.lower())
    out: list[str] = [_canon, raw] if _canon and _canon.lower() != raw.lower() else [raw]
    toks = [t for t in re.split(r"\s+", raw) if t]
    low = [t.lower().strip(".,") for t in toks]
    # strip as many leading honorific tokens as possible (handles multi-word
    # prefixes like "grand ayatollah" / "prime minister" greedily, longest
    # phrase first), never consuming the final remaining token.
    i = 0
    multi = sorted((p for p in _HONORIFIC_PREFIXES if " " in p),
                   key=lambda s: -len(s.split()))
    single = {p for p in _HONORIFIC_PREFIXES if " " not in p}
    while i < len(toks) - 1:
        matched = False
        for phrase in multi:
            pl = phrase.split()
            n = len(pl)
            if i + n <= len(toks) - 1 and low[i:i + n] == pl:
                i += n
                matched = True
                break
        if matched:
            continue
        if low[i] in single:
            i += 1
            continue
        break
    if i > 0:
        stripped = " ".join(toks[i:]).strip()
        if stripped and stripped.lower() != raw.lower():
            out.append(stripped)
    # dedup, order-preserved
    seen: set[str] = set()
    uniq: list[str] = []
    for v in out:
        k = v.lower()
        if v and k not in seen:
            seen.add(k)
            uniq.append(v)
    return uniq


def _name_match(name: str, title: str) -> float:
    """0..1 token-overlap between a requested name and a Wikipedia page title.
    The SURNAME (last token) must appear, plus ≥1 more token, to score high —
    this is the strict name-match gate that stops a random person's photo being
    used for a famous name."""
    def _toks(s):
        return [t for t in re.split(r"[\s\-.,_]+", (s or "").lower())
                if t and t not in {"the", "of", "sir", "dr", "mr", "mrs", "jr",
                                    "sr", "i", "ii", "iii"}]
    nt, tt = _toks(name), set(_toks(title))
    if not nt or not tt:
        return 0.0
    surname = nt[-1]
    if surname not in tt:
        return 0.0
    overlap = sum(1 for t in nt if t in tt)
    return overlap / max(1, len(nt))


def _looks_like_portrait(src: Path) -> tuple[bool, str]:
    """B&W / sepia TOLERANT portrait check. Returns (ok, reason).

    Unlike `_looks_like_face` (skin-tone only — rejects historical grayscale),
    this accepts grayscale and sepia portraits by falling back to luma
    STRUCTURE in the face zone (a real portrait has tonal gradients there),
    while still rejecting thumbnails, near-uniform images (flags/logos/blanks)
    and text/document pages.
    """
    try:
        import numpy as np
        if _is_text_page(src):
            return False, "text_page"
        img = Image.open(src).convert("RGB")
        if min(img.size) < 200:
            return False, "too_small_thumbnail"
        a = np.asarray(img.resize((96, 96), Image.BILINEAR), dtype="float32")
        R, G, B = a[..., 0], a[..., 1], a[..., 2]
        gray = 0.299 * R + 0.587 * G + 0.114 * B
        mx = a.max(axis=-1)
        mn = a.min(axis=-1)
        sat = float(((mx - mn) / (mx + 1e-3)).mean())
        overall_std = float(gray.std())
        if overall_std < 12.0:
            return False, "near_uniform"           # flag / logo / blank
        band = gray[10:74, 22:74]                   # upper-centre face zone
        band_std = float(band.std())
        # COLOUR path — skin-tone in the face zone (the original strong signal)
        if sat > 0.18:
            skin = (
                (R > 60) & (R < 250) & (G > 35) & (B > 20)
                & (R > G) & (G > B * 0.92)
                & ((R - B) > 12) & ((R - B) < 130)
            )
            if float(skin[12:64, 24:72].mean()) > 0.12 and float(skin.mean()) > 0.06:
                return True, "colour_skin_face"
        # GRAYSCALE / SEPIA / colour-without-skin → require facial STRUCTURE:
        # meaningful tonal variation concentrated in the face zone.
        if band_std > 20.0 and band_std >= overall_std * 0.6:
            tag = "grayscale_portrait" if sat < 0.18 else "portrait_structure"
            return True, tag
        return False, "no_face_structure"
    except Exception as e:                          # noqa: BLE001
        return False, f"error:{str(e)[:30]}"


def _image_license(img_url: str) -> tuple[str | None, bool | None]:
    """Best-effort license + public-domain flag for a Commons/Wikipedia image
    file, via the Commons imageinfo extmetadata. Returns (license_short, is_pd)."""
    try:
        fname = img_url.split("/")[-1].split("?")[0]
        if not fname:
            return None, None
        from urllib.parse import unquote
        r = requests.get(
            _WIKIMEDIA_API,
            params={"action": "query", "format": "json",
                    "titles": f"File:{unquote(fname)}",
                    "prop": "imageinfo", "iiprop": "extmetadata"},
            headers=_UA, timeout=15)
        pages = list((r.json().get("query", {}) or {}).get("pages", {}).values())
        md = ((pages[0].get("imageinfo") or [{}])[0].get("extmetadata") or {}) if pages else {}
        lic = (md.get("LicenseShortName", {}) or {}).get("value")
        blob = (str(lic) + " " + str((md.get("UsageTerms", {}) or {}).get("value"))).lower()
        is_pd = ("public domain" in blob) or (lic or "").lower().startswith("pd")
        return lic, (True if is_pd else (False if lic else None))
    except Exception:                               # noqa: BLE001
        return None, None


def _portrait_canvas(src: Path, dest: Path) -> bool:
    """Save a portrait to the W×H canvas WITHOUT clipping the head — a face-safe
    full-head portrait fit to the canvas height over a blurred-darkened fill of
    the same image. Replaces `_cover_to_canvas` for PERSON portraits (the cover
    crop scaled a tall 0.73-aspect photo to fill 16:9 and sheared off the
    forehead + legs). Falls back to the old cover crop on any error."""
    try:
        from .motion_graphics.look import portrait_blurfill_canvas
        img = Image.open(src).convert("RGB")
        if min(img.size) < 200:
            return False
        out = portrait_blurfill_canvas(img, W, H)
        out.save(dest, "JPEG", quality=90)
        return dest.exists() and dest.stat().st_size > 10_000
    except Exception:                                          # noqa: BLE001
        return _cover_to_canvas(src, dest)


def _wikipedia_lead_portrait(name: str, dest: Path) -> tuple[str | None, dict]:
    """Fetch the CANONICAL portrait for a famous person — the lead/infobox image
    of their Wikipedia article (page-title name-matched). This is far more
    reliable than a Commons text search for getting the RIGHT person, and works
    for historical B&W figures. Returns (path_or_None, provenance_dict)."""
    prov = {"person": name, "source": None, "source_url": None, "image_url": None,
            "domain": None, "license": None, "public_domain": None,
            "cached_path": None, "validator": None, "name_match": None,
            "fallback_reason": None}
    try:
        # 1) direct title (follow redirects), then search fallback
        page = {}
        r = requests.get(
            "https://en.wikipedia.org/w/api.php",
            params={"action": "query", "format": "json", "redirects": 1,
                    "titles": name, "prop": "pageimages|info",
                    "piprop": "original", "inprop": "url"},
            headers=_UA, timeout=20)
        pages = list((r.json().get("query", {}) or {}).get("pages", {}).values())
        if pages and "original" in (pages[0] or {}) and pages[0].get("missing") is None:
            page = pages[0]
        else:
            r2 = requests.get(
                "https://en.wikipedia.org/w/api.php",
                params={"action": "query", "format": "json",
                        "generator": "search", "gsrsearch": name, "gsrlimit": 4,
                        "prop": "pageimages|info", "piprop": "original",
                        "inprop": "url"},
                headers=_UA, timeout=20)
            cand = [p for p in (r2.json().get("query", {}) or {}).get("pages", {}).values()
                    if "original" in (p or {})]
            cand.sort(key=lambda p: _name_match(name, p.get("title", "")), reverse=True)
            page = cand[0] if cand else {}
        if not page or "original" not in page:
            prov["fallback_reason"] = "no wikipedia lead image"
            return None, prov
        title = page.get("title", "")
        nm = _name_match(name, title)
        prov["name_match"] = round(nm, 2)
        if nm < 0.5:
            prov["fallback_reason"] = f"name mismatch (page='{title}')"
            return None, prov
        img_url = page["original"]["source"]
        page_url = page.get("fullurl") or \
            ("https://en.wikipedia.org/wiki/" + title.replace(" ", "_"))
        tmp = dest.with_suffix(".dl")
        with requests.get(img_url, headers=_UA, stream=True, timeout=30) as dl:
            dl.raise_for_status()
            if "image" not in dl.headers.get("content-type", ""):
                prov["fallback_reason"] = "lead url not an image"
                return None, prov
            with open(tmp, "wb") as fh:
                for chunk in dl.iter_content(1 << 16):
                    fh.write(chunk)
        ok_canvas = _portrait_canvas(tmp, dest)
        tmp.unlink(missing_ok=True)
        if not ok_canvas or not dest.exists():
            prov["fallback_reason"] = "canvas failed"
            return None, prov
        ok, reason = _looks_like_portrait(dest)
        prov["validator"] = reason
        if not ok:
            dest.unlink(missing_ok=True)
            prov["fallback_reason"] = f"validator rejected: {reason}"
            return None, prov
        lic, pd = _image_license(img_url)
        if lic is None and "/commons/" in img_url:
            # hosted on Wikimedia Commons → free media; exact license on the
            # file page (the extra extmetadata call may be unavailable offline)
            lic = "Wikimedia Commons (free media — see file page)"
        prov.update(source="Wikipedia lead image", source_url=page_url,
                    image_url=img_url, domain="en.wikipedia.org",
                    license=lic, public_domain=pd, cached_path=str(dest))
        return str(dest), prov
    except Exception as e:                          # noqa: BLE001
        prov["fallback_reason"] = f"error: {str(e)[:50]}"
        return None, prov


# Roles that mark a PUBLIC FIGURE likely to have real photos on
# Wikimedia Commons / Wikipedia. Used to gate the real-image-first
# lookup so we only spend a network call on names that plausibly have
# clean public photos (presidents, generals, leaders…). Unfamous
# subjects skip straight to AI portraiture.
_PUBLIC_FIGURE_ROLE_WORDS = (
    "president", "prime minister", "minister", "general", "admiral",
    "commander", "colonel", "brigadier", "ayatollah", "supreme leader",
    "chancellor", "premier", "dictator", "king", "queen", "prince",
    "princess", "emperor", "shah", "sultan", "senator", "governor",
    "ambassador", "secretary", "director", "chief", "spymaster",
    "founder", "ceo", "chairman", "leader", "politician", "diplomat",
    "scientist", "nobel", "author", "journalist", "editor", "reporter",
    "actor", "actress", "singer", "musician", "athlete", "champion",
    "billionaire", "tycoon", "magnate", "pope", "cardinal", "bishop",
    "warlord", "rebel leader", "revolutionary", "activist",
)


def _real_person_image(
    name: str, role: str, dest: Path, *,
    gender: str = "unknown", cache_dir: Path | None = None,
) -> str | None:
    """Try to fetch a REAL, scene-relevant photo of a named PUBLIC
    figure from Wikimedia Commons before falling back to AI.

    Returns the path string if a confident real photo was found, else
    None (caller then uses the AI portrait). Confidence requires:
      • the role reads as a public figure (or `VIDLORE_REAL_PERSON=all`),
      • a Commons file-search hit for the exact name,
      • the image passes the text-page / book-artifact / UI filters
        (already enforced inside `_wikimedia_image`), AND
      • `_looks_like_face` accepts it (skin-tone in the face zone).

    Disable entirely with `VIDLORE_REAL_PERSON=0`.

    Logs a one-line validation record:
      [real-person] name | role | source | confidence | match/reject
    """
    mode = (os.environ.get("VIDLORE_REAL_PERSON", "1") or "").strip().lower()
    if mode in ("0", "false", "no", "off"):
        return None
    if not name or len(name.strip()) < 3:
        return None
    rl = (role or "").lower()
    # A proper full name (2-4 mostly-capitalised tokens) is very likely a real
    # person who has a Wikipedia page — let the lead-image NAME-MATCH gate decide
    # rather than a role keyword. This rescues famous figures whose role word
    # isn't in the curated list (inventor, banker, industrialist, physicist…).
    _ntoks = [t for t in re.split(r"[\s.\-]+", (name or "").strip()) if t]
    _looks_named = (2 <= len(_ntoks) <= 4
                    and sum(1 for t in _ntoks if t[:1].isupper()) >= 2)
    is_public = (mode == "all") or _looks_named or any(
        w in rl for w in _PUBLIC_FIGURE_ROLE_WORDS
    )
    if not is_public:
        print(f"  [real-person] {name[:34]} | {role[:24]} | — | "
              f"low (not a public-figure role) | reject→AI", flush=True)
        return None
    if not _wikimedia_on():
        return None

    # RC5 — pre-photographic exemption for the documentary-suitability probe.
    # A figure who PREDATES photography (Napoleon, Caesar…) is legitimately
    # represented by a period oil painting / engraving, which reads as a
    # "designed graphic" by graphic_dom. Compute the flag ONCE up front so the
    # suitability check (added below at every real-portrait return) keeps those
    # artworks while still rejecting a cartoon/poster/game depiction of a MODERN,
    # photographable figure. Does NOT alter identity verification.
    _prephoto0 = False
    try:
        from . import portrait_intel as _pintel0
        _prephoto0 = bool(_pintel0.prefers_artwork(name))
    except Exception:                                          # noqa: BLE001
        _prephoto0 = False

    # Cache by name only — a real person's canonical photo is stable.
    ck = scene_key("realperson", name.lower().strip())
    cpath = (cache_dir / f"{ck}.jpg") if cache_dir is not None else None
    provpath = (cache_dir / f"{ck}.provenance.json") if cache_dir is not None else None

    def _record(prov: dict) -> None:
        _PORTRAIT_PROVENANCE[name] = prov
        if provpath is not None:
            try:
                provpath.write_text(json.dumps(prov, indent=2), encoding="utf-8")
            except Exception:                              # noqa: BLE001
                pass

    if cpath is not None and cpath.exists():
        try:
            shutil.copyfile(cpath, dest)
            prov = {}
            if provpath is not None and provpath.exists():
                try:
                    prov = json.loads(provpath.read_text(encoding="utf-8"))
                except Exception:                          # noqa: BLE001
                    prov = {}
            prov.setdefault("person", name)
            prov["cache_hit"] = True
            # RC5 — warm-cache suitability: a portrait cached under a gate-off
            # render could be a cartoon/poster/game depiction. Re-check the
            # cached face before reuse (identity was proven at cache time).
            if _portrait_doc_suitable(dest, prephoto=_prephoto0):
                _PORTRAIT_PROVENANCE[name] = prov
                print(f"  [real-person] {name[:34]} | {role[:24]} | "
                      f"{prov.get('source','cache')} | cache | MATCH", flush=True)
                return str(dest)
            try:
                cpath.unlink(missing_ok=True)
                dest.unlink(missing_ok=True)
            except Exception:                              # noqa: BLE001
                pass
        except Exception:                                  # noqa: BLE001
            pass

    # 1) CANONICAL: Wikipedia lead/infobox image (page-title name-matched).
    #    Best for famous figures incl. historical B&W — strict name match.
    #    RC4: retry over honorific-normalized name variants so a title token
    #    ("Ayatollah", "President"…) can't hide the real article — the first
    #    PAGE-VERIFIED variant (the gate already rejects name_match < 0.5) wins.
    prov = {}
    p = None
    for _variant in _person_name_variants(name):
        p, prov = _wikipedia_lead_portrait(_variant, dest)
        if p and dest.exists():
            break
    if p and dest.exists() and not _portrait_doc_suitable(
            dest, prephoto=_prephoto0):
        # identity-verified but reads as cartoon/poster/game → drop, try Commons
        try:
            dest.unlink(missing_ok=True)
        except Exception:                                  # noqa: BLE001
            pass
        p = None
    if p and dest.exists():
        prov.setdefault("person", name)
        prov["identity_verified"] = True
        if cpath is not None:
            try:
                shutil.copyfile(dest, cpath)
            except Exception:                              # noqa: BLE001
                pass
        _record(prov)
        print(f"  [real-person] {name[:34]} | {role[:24]} | "
              f"wikipedia.lead | {prov.get('name_match')} | "
              f"MATCH ({prov.get('validator')})", flush=True)
        return str(dest)

    # 2) Wikimedia Commons portrait search — B&W/sepia-TOLERANT validation.
    #    PRE-PHOTOGRAPHIC people (Napoleon, Caesar, Washington…) get painting/
    #    engraving queries FIRST via portrait_intel, so the search returns a
    #    verified period artwork rather than a random modern look-alike.
    queries = [f"{name} portrait", f"{name} photograph", name]
    _prephoto = False
    try:
        from . import portrait_intel as _pintel
        _prephoto = _pintel.prefers_artwork(name)
        if _prephoto:
            queries = _pintel.portrait_queries(name, prephoto=True)
            print(f"  [portrait-intel] {name[:34]} pre-photographic → "
                  f"artwork queries {queries[:2]}", flush=True)
    except Exception:                                          # noqa: BLE001
        pass
    # RC4 — name-search sources (Commons / LoC) must be IDENTITY-VERIFIED, not
    # just face-shaped: `_looks_like_portrait` confirms a face, NOT *whose*. We
    # capture the chosen file/item title and require `_name_match >= 0.5` before
    # trusting it, so a wrong person's photo (the Khomeini bug) can never be
    # baked. Pre-photographic CURATED ARTWORK (`_prephoto`) is exempt — those
    # queries deliberately ask for period paintings whose titles needn't carry
    # the surname — but provenance stays honest. `VIDLORE_UNVERIFIED_PORTRAIT=1`
    # restores the old name-search-only behaviour.
    _allow_unverified = os.environ.get(
        "VIDLORE_UNVERIFIED_PORTRAIT", "0").strip().lower() in (
        "1", "true", "yes", "on")
    global _LAST_WIKIMEDIA_TITLE
    _LAST_WIKIMEDIA_TITLE = None
    if _wikimedia_image(queries, dest, variant=0) and dest.exists():
        _ok, _reason = _looks_like_portrait(dest)
        _wtitle = _LAST_WIKIMEDIA_TITLE or ""
        _wnm = _name_match(name, _wtitle) if _wtitle else 0.0
        _identity_ok = (_prephoto or _allow_unverified
                        or (bool(_wtitle) and _wnm >= 0.5))
        # RC5 — documentary-suitability ON TOP of identity (artwork-exempt):
        # an identity-matched but cartoon/poster/game image is dropped so a
        # named figure is never shown as a stylised non-documentary rendering.
        _suit_ok = _portrait_doc_suitable(dest, prephoto=_prephoto)
        if _ok and _identity_ok and _suit_ok:
            cprov = {"person": name, "source": "Wikimedia Commons search",
                     "source_url": "https://commons.wikimedia.org/",
                     "image_url": None, "domain": "commons.wikimedia.org",
                     "license": "see Commons file", "public_domain": None,
                     "cached_path": str(cpath) if cpath else str(dest),
                     "validator": _reason,
                     "commons_title": _wtitle or None,
                     "name_match": (round(_wnm, 2) if _wtitle else None),
                     "identity_verified": bool(_wtitle and _wnm >= 0.5),
                     "fallback_reason": (
                         "artwork (pre-photographic, curated)" if _prephoto
                         and _wnm < 0.5 else
                         ("identity NOT verified (VIDLORE_UNVERIFIED_PORTRAIT)"
                          if _allow_unverified and not (_wtitle and _wnm >= 0.5)
                          else None))}
            _record(cprov)
            if cpath is not None:
                try:
                    shutil.copyfile(dest, cpath)
                except Exception:                          # noqa: BLE001
                    pass
            print(f"  [real-person] {name[:34]} | {role[:24]} | "
                  f"wikimedia.commons | nm={cprov['name_match']} "
                  f"idv={cprov['identity_verified']} | MATCH ({_reason})",
                  flush=True)
            return str(dest)
        else:
            # Commons hit but not a usable face OR identity not verified →
            # drop it, fall through to LoC (never bake a wrong-person face).
            if _ok and not _identity_ok:
                print(f"  [real-person] {name[:34]} | {role[:24]} | "
                      f"wikimedia.commons | REJECT identity "
                      f"(title='{_wtitle[:40]}' nm={_wnm:.2f})", flush=True)
            try:
                dest.unlink(missing_ok=True)
            except Exception:                              # noqa: BLE001
                pass

    # 3) Library of Congress — REAL public-domain historical photos. Great for
    #    pre-1928 figures whose Wikipedia lead image is weak or absent. LoC search
    #    is NAME-BASED (not page-verified), so we require the B&W/sepia-tolerant
    #    validator to accept a real face before trusting it; _loc_image already
    #    rejects text pages, book covers and thumbnails. Provenance is honest
    #    about the lower (name-search) match confidence.
    # OPT-IN (default OFF). LoC search is name-based and can return real-but-not-
    # portrait results (murals, statues, busy scenes where the face is small),
    # so it stays off by default and is enabled for historical work where the
    # Wikipedia lead / Commons photo is weak. Validator-protected + honest
    # "not page-verified" provenance either way.
    _loc_portrait_on = os.environ.get("VIDLORE_LOC_PORTRAIT", "0").strip().lower() \
        in ("1", "true", "yes", "on")
    if _loc_portrait_on:
        global _LAST_LOC_TITLE
        _LAST_LOC_TITLE = None
        if _loc_image([f"{name} portrait", f"{name} photograph", name], dest,
                      force=True) and dest.exists():
            _lok, _lr = _looks_like_portrait(dest)
            # RC4 — identity-verify the LoC item title too (name-search alone
            # is not whose-face proof). Artwork-exempt + env-overridable, same
            # as Commons.
            _ltitle = _LAST_LOC_TITLE or ""
            _lnm = _name_match(name, _ltitle) if _ltitle else 0.0
            _loc_identity_ok = (_prephoto or _allow_unverified
                                or (bool(_ltitle) and _lnm >= 0.5))
            # RC5 — documentary-suitability (artwork-exempt) ON TOP of identity.
            _loc_suit_ok = _portrait_doc_suitable(dest, prephoto=_prephoto)
            if _lok and _loc_identity_ok and _loc_suit_ok:
                lprov = {"person": name, "source": "Library of Congress",
                         "source_url": "https://www.loc.gov/photos/",
                         "image_url": None, "domain": "loc.gov",
                         "license": "Library of Congress — typically public domain / "
                                    "no known restrictions (verify item page)",
                         "public_domain": None,
                         "cached_path": str(cpath) if cpath else str(dest),
                         "validator": _lr,
                         "loc_title": _ltitle or None,
                         "name_match": (round(_lnm, 2) if _ltitle else
                                        "loc_name_search (not page-verified)"),
                         "identity_verified": bool(_ltitle and _lnm >= 0.5),
                         "fallback_reason": (
                             "artwork (pre-photographic, curated)" if _prephoto
                             and _lnm < 0.5 else
                             ("identity NOT verified "
                              "(VIDLORE_UNVERIFIED_PORTRAIT)"
                              if _allow_unverified and not (_ltitle
                              and _lnm >= 0.5) else None))}
                _record(lprov)
                if cpath is not None:
                    try:
                        shutil.copyfile(dest, cpath)
                    except Exception:                      # noqa: BLE001
                        pass
                print(f"  [real-person] {name[:34]} | {role[:24]} | "
                      f"loc.gov | nm={lprov['name_match']} "
                      f"idv={lprov['identity_verified']} | MATCH ({_lr})",
                      flush=True)
                return str(dest)
            if _lok and not _loc_identity_ok:
                print(f"  [real-person] {name[:34]} | {role[:24]} | "
                      f"loc.gov | REJECT identity "
                      f"(title='{_ltitle[:40]}' nm={_lnm:.2f})", flush=True)
            try:
                dest.unlink(missing_ok=True)
            except Exception:                              # noqa: BLE001
                pass

    # all trustworthy real sources exhausted → AI fallback (honest provenance)
    _record({"person": name, "source": None, "domain": None,
             "validator": None, "name_match": prov.get("name_match"),
             "fallback_reason": prov.get("fallback_reason")
                 or "no real portrait (wikipedia/commons/loc)",
             "cached_path": None})
    print(f"  [real-person] {name[:34]} | {role[:24]} | none | "
          f"no real portrait (wiki/commons/loc) | →AI", flush=True)
    return None


def resolve_legend_portrait(
    name: str, *, role: str = "", narration: str = "", dest: Path,
    cfg=None, cache_dir: "Path | None" = None, allow_ai: bool = False,
    seed: int = 0,
) -> dict:
    """Portrait fallback ladder for the biography `portrait_legend_reveal`
    cold-open. The primitive accepts a face-safe `portrait_path` and draws a
    premium monogram pedestal when it is absent; this resolves a REAL portrait
    for it, reusing the same validated sourcing the name_reveal cards use.

    Ladder (honest, ordered — never fabricates over a real archival image):
      1. archival / public-domain real portrait — Wikipedia lead / Commons / LoC
      2. validated web portrait — Commons search (B&W/sepia-tolerant validator)
      3. relevant fal.ai portrait STILL — only when `allow_ai` and fal is
         configured; labelled `fal_ai_portrait` so it is never mistaken for a
         real photo. Never AI VIDEO.
      4. premium monogram pedestal — `portrait_path` stays None (the primitive
         draws its monogram medallion).

    Returns a plain dict (never raises):
        {portrait_path, portrait_subject, portrait_source_type,
         portrait_source_path, portrait_validation_score, portrait_fallback_reason}
    Tiers 1-2 run the existing `_real_person_image` gates (name-match, face
    structure, text-page / wrong-era / low-quality rejection); a rejected
    candidate falls through to the next tier and the reason is surfaced.
    """
    out = {"portrait_path": None, "portrait_subject": (name or "").strip(),
           "portrait_source_type": "monogram_pedestal",
           "portrait_source_path": None,
           "portrait_validation_score": None,
           "portrait_fallback_reason": None}
    nm = (name or "").strip()
    if not nm:
        out["portrait_fallback_reason"] = "no subject name"
        return out
    dest = Path(dest)
    # gender only steers the (tier-3) AI prompt; tiers 1-2 ignore it.
    try:
        gender = _detect_gender_from_context(nm, narration or "", "")
    except Exception:                                          # noqa: BLE001
        gender = "unknown"

    # ── tiers 1-2: real archival / validated web portrait ──────────────
    rp = None
    try:
        rp = _real_person_image(nm, role or "", dest, gender=gender,
                                cache_dir=cache_dir)
    except Exception:                                          # noqa: BLE001
        rp = None
    prov = dict((_PORTRAIT_PROVENANCE.get(nm) or {}))
    if rp and Path(rp).exists():
        _src = str(prov.get("source") or "").lower()
        if any(k in _src for k in ("wikipedia", "commons", "congress", "loc")):
            stype = "archival_public_domain"
        elif _src:
            stype = "validated_web"
        else:
            stype = "real_portrait"
        _score = prov.get("name_match")
        out.update(portrait_path=str(rp), portrait_source_type=stype,
                   portrait_source_path=str(rp),
                   portrait_validation_score=(_score if isinstance(
                       _score, (int, float)) else None))
        return out
    # surface the real-tier reason (e.g. "name mismatch", "validator rejected")
    out["portrait_fallback_reason"] = (prov.get("fallback_reason")
                                       or "no real portrait (wikipedia/commons/loc)")

    # ── tier 3: fal.ai portrait STILL (opt-in; never AI video) ─────────
    if allow_ai and cfg is not None and getattr(cfg, "fal_key", ""):
        try:
            subj = (f"{nm}, {role}".strip().strip(",") if role else nm)
            prompt = _cinematic_portrait_prompt(subj, gender, (narration or "")[:240])
            fdest = dest.with_name(dest.stem + "_fal.jpg")
            _model = getattr(cfg, "fal_model", "") or "fal-ai/flux/schnell"
            if _fal_image(prompt, fdest, cfg.fal_key, _model, int(seed)) \
                    and fdest.exists():
                _ok_face, _reason = _looks_like_portrait(fdest)
                if _ok_face:
                    out.update(portrait_path=str(fdest),
                               portrait_source_type="fal_ai_portrait",
                               portrait_source_path=str(fdest),
                               portrait_validation_score=None,
                               portrait_fallback_reason=None)
                    print(f"  [legend-portrait] {nm[:34]} | fal_ai_portrait | "
                          f"MATCH ({_reason})", flush=True)
                    return out
                try:
                    fdest.unlink(missing_ok=True)
                except Exception:                              # noqa: BLE001
                    pass
                out["portrait_fallback_reason"] = f"fal portrait rejected: {_reason}"
        except Exception as _fe:                               # noqa: BLE001
            out["portrait_fallback_reason"] = f"fal portrait error: {str(_fe)[:40]}"

    # ── tier 4: monogram pedestal (portrait_path stays None) ───────────
    return out


def _detect_gender_from_context(
    name: str, narration: str = "", body: str = ""
) -> str:
    """Return 'female' | 'male' | 'unknown' for a named person.

    Two passes, strongest signal first:
      1. PRONOUN pass over the surrounding narration + body. If the
         narration contains clear gendered pronouns (she/her/herself,
         he/him/himself) within a 60-word window, trust it absolutely
         — the script author already established the character.
      2. NAME pass against the curated `_FEMALE_NAMES` / `_MALE_NAMES`
         sets. Splits compound names (first-middle-last) and tries each
         token. Returns 'unknown' if no token matches.

    The narration pass is critical: many name_reveal cards carry only
    "FAMILY NAME · ROLE · LOCATION" (e.g. "PEREZ-SHAKDAM · JOURNALIST")
    with no recognizable first name. The script's pronouns are the
    truth.
    """
    blob = ((narration or "") + " " + (body or "")).lower()
    # word-boundary pronoun counts
    fcount = (
        len(re.findall(r"\bshe\b", blob))
        + len(re.findall(r"\bher\b", blob))
        + len(re.findall(r"\bherself\b", blob))
        + len(re.findall(r"\bhers\b", blob))
    )
    mcount = (
        len(re.findall(r"\bhe\b", blob))
        + len(re.findall(r"\bhim\b", blob))
        + len(re.findall(r"\bhis\b", blob))
        + len(re.findall(r"\bhimself\b", blob))
    )
    # Decisive when one side dominates by 2+ AND there's at least one
    # explicit gendered token. Otherwise fall through to the name table.
    if fcount >= mcount + 2 and fcount >= 2:
        return "female"
    if mcount >= fcount + 2 and mcount >= 2:
        return "male"
    # Name table — split on whitespace, hyphens, periods. Skip
    # honorifics (mr / mrs / dr / etc) that aren't given names.
    _SKIP = {"mr", "mrs", "ms", "miss", "dr", "prof", "general", "captain",
             "colonel", "major", "sergeant", "agent", "rabbi", "imam",
             "father", "sister", "brother", "sheikh", "sheikha", "sir",
             "lady", "lord"}
    for tok in re.split(r"[\s\-.,]+", name.lower()):
        if not tok or tok in _SKIP:
            continue
        if tok in _FEMALE_NAMES:
            return "female"
        if tok in _MALE_NAMES:
            return "male"
    # GENDERED-NOUN pass (user-reported 2026-06-06: a female stock photo shown
    # for "THE OLD FARMER"). An UNNAMED archetype character card ("the old man",
    # "a grandmother", "the widow", "the blacksmith") states its gender in the
    # NOUN, not a name or (always) a pronoun — so the name table above misses it
    # and the 2-margin pronoun gate may be too weak on a short scene. A gendered
    # noun anywhere in the subject + narration is a decisive signal, so the AI
    # portrait gets a correct gender-lock instead of drifting to a random person.
    _subj = (name or "").lower() + " " + blob
    _MALE_NOUNS = (
        r"\b(old man|grandfather|grandpa|grandad|father|dad|husband|widower|"
        r"patriarch|gentleman|the man|a man|young man|son|brother|uncle|nephew|"
        r"king|prince|emperor|monk|priest|friar|groom|boy|bachelor|landlord|"
        r"craftsman|tradesman|fisherman|woodsman|blacksmith|gravedigger)\b")
    _FEM_NOUNS = (
        r"\b(old woman|grandmother|grandma|granny|mother|mom|mum|wife|widow|"
        r"matriarch|lady|the woman|a woman|young woman|daughter|sister|aunt|"
        r"niece|queen|princess|empress|nun|bride|girl|spinster|seamstress|"
        r"midwife|housewife|landlady|waitress|actress|heiress)\b")
    _mn = len(re.findall(_MALE_NOUNS, _subj))
    _fn = len(re.findall(_FEM_NOUNS, _subj))
    if _mn > _fn and _mn >= 1:
        return "male"
    if _fn > _mn and _fn >= 1:
        return "female"
    # Pronoun fallback — accept a weaker signal (any side wins) only if
    # the name table couldn't decide.
    if fcount > mcount:
        return "female"
    if mcount > fcount:
        return "male"
    return "unknown"


def _cinematic_portrait_prompt(
    subject_desc: str,
    gender: str = "unknown",
    narration_hint: str = "",
) -> str:
    """Subject-aware documentary portrait prompt (v12).

    `subject_desc` is "NAME, ROLE" (e.g. "Catherine Perez-Shakdam,
    journalist, Paris"). `gender` is 'female' | 'male' | 'unknown'.
    `narration_hint` is up to ~40 words pulled from the scene's
    narration so the model has setting context (e.g. "Tehran general's
    study", "Paris newsroom", "Vietnamese rice paddy at dawn") instead
    of inventing one.

    The PREVIOUS prompt was hard-coded for an elderly male farmer in a
    straw hat with denim suspenders in a wheat field. That produced a
    male farmer portrait for "Catherine Perez-Shakdam, journalist,
    Paris" because the farmer-specific clothing/setting clauses
    dominated the subject description. This rewrite removes ALL
    clothing/setting hard-coding — the model picks what fits the role
    + the gender-lock keeps it on the correct side.
    """
    gender_lock = {
        "female": (
            "portrait of a FEMALE subject, woman, feminine features, "
            "AVOID male features, AVOID beard, AVOID stubble, "
            "AVOID mustache"
        ),
        "male": (
            "portrait of a MALE subject, man, masculine features, "
            "AVOID female features, AVOID feminine styling"
        ),
        "unknown": "portrait of a single subject",
    }.get(gender, "portrait of a single subject")

    setting_hint = ""
    if narration_hint:
        # Trim to ~40 words and strip newlines so it fits cleanly in the
        # prompt without confusing the parser.
        n = re.sub(r"\s+", " ", narration_hint).strip()
        n = " ".join(n.split()[:40])
        if n:
            setting_hint = (
                f"setting context from the scene: {n}. "
                "Choose environment, clothing and era to match this context, "
            )

    return (
        f"hyper-realistic editorial documentary photograph of {subject_desc}. "
        f"{gender_lock}. "
        "REAL PHOTOGRAPH not illustration not render, "
        "head-and-shoulders three-quarter portrait, "
        "shot on Hasselblad H6D-100c with 85mm f/1.8 portrait lens, "
        "soft natural light from window or environment "
        "(not studio strobes), "
        "shallow depth of field f/1.8, eyes tack-sharp in focus, "
        "creamy out-of-focus environmental bokeh background, "
        f"{setting_hint}"
        "authentic clothing appropriate to the subject's role, era, "
        "culture and location — do NOT default to farmer denim or "
        "straw hat unless the subject is explicitly a farmer, "
        "natural unposed expression, looking slightly off camera, "
        "realistic skin texture with natural pores and age-appropriate "
        "features (no airbrushed plastic finish), "
        f"{'warm Kodak Portra 400 film grain, ' if _AI_FILM_GRAIN else 'clean natural digital clarity, '}"
        "soft documentary color grade, "
        "National Geographic Magnum Photos editorial aesthetic, "
        "documentary photojournalism feel, candid not posed. "
        # Negative prompt — push hard against CGI render look AND
        # against the previous farmer/cornfield default
        "AVOID 3D render, AVOID CGI, AVOID digital painting, "
        "AVOID Octane render, AVOID Unreal Engine, "
        "AVOID smooth airbrushed plastic skin, AVOID waxy face, "
        "AVOID Midjourney aesthetic, AVOID anime, AVOID cartoon, "
        "AVOID statue, AVOID sculpture, AVOID mannequin, "
        "AVOID overly stylized cinematic lighting, "
        "AVOID flat studio backdrop, AVOID grey seamless, "
        "AVOID over-sharpened HDR, AVOID glossy highlights, "
        "AVOID generic stock-photo composition, "
        "no text, no caption, no words, no letters, no watermark, "
        "no logo"
    )


# ── Shared HTTP session for fal.ai (TLS keep-alive: ~300ms saved/req) ──
import threading as _fal_threading
_FAL_SESSION: requests.Session | None = None
_FAL_SESSION_LOCK = _fal_threading.Lock()

def _fal_session() -> requests.Session:
    global _FAL_SESSION
    if _FAL_SESSION is None:
        with _FAL_SESSION_LOCK:
            if _FAL_SESSION is None:
                s = requests.Session()
                _adp = requests.adapters.HTTPAdapter(
                    pool_connections=16, pool_maxsize=16, max_retries=0)
                s.mount("https://", _adp)
                s.mount("http://", _adp)
                _FAL_SESSION = s
    return _FAL_SESSION


# ── Cross-render PROMPT-HASH cache for fal.ai images ──
def _fal_prompt_cache_path(prompt: str, model: str) -> Path:
    """Per-model+prompt cache so different fal models stay separate but
    the same (model, prompt) pair across runs/scenes reuses the disk
    file. Lives in ~/.vidlore/fal_cache/<model>/<sha>.jpg."""
    import hashlib, os as _os, re as _re
    safe_model = _re.sub(r"[^A-Za-z0-9_\-]", "_", model or "fal")[:64]
    digest = hashlib.sha256((prompt or "").encode("utf-8")).hexdigest()[:32]
    base = Path(
        _os.environ.get("VIDLORE_FAL_CACHE",
                         str(Path.home() / ".vidlore" / "fal_cache"))) \
        / safe_model
    base.mkdir(parents=True, exist_ok=True)
    return base / f"{digest}.jpg"


def _fal_image(
    prompt: str, dest: Path, key: str, model: str, seed: int
) -> bool:
    """fal.ai FLUX — paid, reliable, ~1-3s. The primary cinematic engine:
    the LLM-directed shot prompt is rendered exactly, so the visual
    always matches the sentence.

    SPEED OPTIMIZATIONS (user-requested 2026-05-25):
      * Cross-render PROMPT-HASH CACHE — same (model, prompt) anywhere
        reuses the disk file (zero API call). Massive win on
        re-renders / regenerated scenes / parallel similar prompts.
      * Persistent HTTP session — TLS keep-alive cuts ~300ms/request.
      * Tighter generation timeout (60s, was 90s) + tighter download
        timeout (40s, was 60s) so a single stuck request doesn't
        block the whole render. Still well above fal's typical 1-3s.
    """
    # 1) Prompt-hash cross-render cache
    _cache_p = _fal_prompt_cache_path(prompt, model)
    if _cache_p.exists() and _cache_p.stat().st_size > 10_000:
        try:
            shutil.copyfile(_cache_p, dest)
            return True
        except Exception:                                  # noqa: BLE001
            pass

    session = _fal_session()
    try:
        r = session.post(
            f"https://fal.run/{model}",
            headers={
                "Authorization": f"Key {key}",
                "Content-Type": "application/json",
            },
            json={
                "prompt": prompt[:1800],
                "image_size": "landscape_16_9",
                "num_images": 1,
                "seed": seed,
                "enable_safety_checker": True,
            },
            timeout=60,
        )
        if r.status_code != 200:
            return False
        imgs = (r.json() or {}).get("images") or []
        url = imgs[0].get("url") if imgs else None
        if not url:
            return False
        tmp = dest.with_suffix(".dl")
        with session.get(url, stream=True, timeout=40) as dl:
            dl.raise_for_status()
            with open(tmp, "wb") as fh:
                for chunk in dl.iter_content(1 << 16):
                    fh.write(chunk)
        ok = _cover_to_canvas(tmp, dest)
        tmp.unlink(missing_ok=True)
        if ok:
            # Populate cross-render cache for future hits
            try:
                shutil.copyfile(dest, _cache_p)
            except Exception:                              # noqa: BLE001
                pass
        return ok
    except Exception:
        return False


# ── Google Imagen (Vertex AI) — PRIMARY AI-still provider (user 2026-06-06) ──
# Imagen 4 Fast is the primary cinematic still engine; fal.ai FLUX is the
# secondary fallback (used when Imagen is unavailable / errors / a beat's whole
# Imagen ladder failed validation). All resolution is lazy + defensive: if the
# google-genai SDK or the service-account credentials are missing, every Imagen
# call simply reports "unavailable" and the caller falls straight to fal.ai — so
# a machine without Google creds keeps working exactly as before.
_IMAGEN_LOCK = _fal_threading.Lock()
_IMAGEN_CLIENT = None
_IMAGEN_OK = None


def _imagen_creds_path() -> "str | None":
    """Locate the GCP service-account JSON: explicit env first, then a
    `.secrets/gcp_vidlore.json` next to the package (works in source AND in a
    bundled dist where the file is copied alongside the vidlore/ folder)."""
    for ev in ("VIDLORE_GCP_CREDENTIALS", "GOOGLE_APPLICATION_CREDENTIALS"):
        p = os.environ.get(ev)
        if p and Path(p).exists():
            return p
    here = Path(__file__).resolve().parent          # …/vidlore
    home = Path.home()
    cands = [
        # user config
        home / ".config" / "vidlore" / "gcp_vidlore.json",
        home / ".vidlore" / "gcp_vidlore.json",
        # SIMPLEST: a plain gcp_vidlore.json dropped right in the dist / package
        # folder (visible, not hidden) — just put the file next to vidlore\.
        here.parent / "gcp_vidlore.json",
        here / "gcp_vidlore.json",
        Path.cwd() / "gcp_vidlore.json",
        # …/.secrets/ variants (also supported)
        here.parent / ".secrets" / "gcp_vidlore.json",
        here / ".secrets" / "gcp_vidlore.json",
        Path.cwd() / ".secrets" / "gcp_vidlore.json",
    ]
    for cand in cands:
        try:
            if cand.exists():
                return str(cand)
        except Exception:                                  # noqa: BLE001
            continue
    return None


def _gemini_api_key():
    """The SIMPLE path: a Gemini Developer-API key (one string — no project,
    region, or service-account). Checks env vars first, then a plain text file
    `gemini_api_key.txt` next to the package / dist / home (paste the key on its
    own line). On a Windows PC this is ALL you need:
        pip install google-genai      +      put the key in gemini_api_key.txt
    """
    for ev in ("VIDLORE_GEMINI_API_KEY", "GEMINI_API_KEY", "GOOGLE_API_KEY"):
        v = (os.environ.get(ev) or "").strip()
        if v:
            return v
    here = Path(__file__).resolve().parent
    for base in (here.parent, here, Path.cwd(),
                 Path.home() / ".config" / "vidlore", Path.home() / ".vidlore"):
        try:
            f = base / "gemini_api_key.txt"
            if f.exists():
                for line in f.read_text(encoding="utf-8").splitlines():
                    line = line.strip()
                    if line and not line.startswith("#"):
                        return line
        except Exception:                                  # noqa: BLE001
            continue
    return None


def _imagen_available() -> bool:
    """True iff Imagen can be used: not disabled, SDK importable, AND a credential
    present — a simple Gemini API key (preferred) OR a service-account JSON."""
    global _IMAGEN_OK
    if _IMAGEN_OK is not None:
        return _IMAGEN_OK
    with _IMAGEN_LOCK:
        if _IMAGEN_OK is not None:
            return _IMAGEN_OK
        if os.environ.get("VIDLORE_IMAGEN", "1") == "0":
            _IMAGEN_OK = False
            return False
        if not (_gemini_api_key() or _imagen_creds_path()):
            _IMAGEN_OK = False
            return False
        try:
            import google.genai  # noqa: F401
            _IMAGEN_OK = True
        except Exception:                                  # noqa: BLE001
            _IMAGEN_OK = False
        return _IMAGEN_OK


def _imagen_client():
    """Lazily build (and cache) a genai client. PREFERS the simple Gemini
    Developer-API key (just a string); falls back to a Vertex AI service-account
    JSON only if no key is set. Thread-safe single init. Returns None on failure."""
    global _IMAGEN_CLIENT
    if _IMAGEN_CLIENT is not None:
        return _IMAGEN_CLIENT
    with _IMAGEN_LOCK:
        if _IMAGEN_CLIENT is not None:
            return _IMAGEN_CLIENT
        try:
            from google import genai
            key = _gemini_api_key()
            if key:
                # SIMPLE path — Gemini Developer API: just the key, nothing else.
                _IMAGEN_CLIENT = genai.Client(api_key=key)
            else:
                # Fallback — Vertex AI via a service-account JSON.
                import json as _json
                cp = _imagen_creds_path()
                os.environ.setdefault("GOOGLE_APPLICATION_CREDENTIALS", cp)
                proj = _json.loads(Path(cp).read_text(encoding="utf-8"))["project_id"]
                loc = os.environ.get("VIDLORE_IMAGEN_LOCATION", "us-central1")
                _IMAGEN_CLIENT = genai.Client(vertexai=True, project=proj,
                                              location=loc)
        except Exception:                                  # noqa: BLE001
            _IMAGEN_CLIENT = None
        return _IMAGEN_CLIENT


def _imagen_image(prompt: str, dest: Path, seed: int) -> bool:
    """Google Imagen (Vertex AI) — PRIMARY still. Renders the LLM-directed shot
    prompt to a 16:9 image, fit to canvas exactly like fal. Prompt+seed cross-
    render cache (zero re-cost on repeats). Defensive: returns False (never
    raises) so the caller falls through to fal.ai."""
    model = os.environ.get("VIDLORE_IMAGEN_MODEL", "imagen-4.0-fast-generate-001")
    _cache_p = _fal_prompt_cache_path(f"{prompt}|seed={seed}", "imagen:" + model)
    if _cache_p.exists() and _cache_p.stat().st_size > 10_000:
        try:
            shutil.copyfile(_cache_p, dest)
            return True
        except Exception:                                  # noqa: BLE001
            pass
    client = _imagen_client()
    if client is None:
        return False
    try:
        from google.genai import types
    except Exception:                                      # noqa: BLE001
        return False
    def _finish(tmp_path) -> bool:
        ok = _cover_to_canvas(tmp_path, dest)
        try:
            tmp_path.unlink(missing_ok=True)
        except Exception:                                  # noqa: BLE001
            pass
        if ok:
            try:
                shutil.copyfile(dest, _cache_p)
            except Exception:                              # noqa: BLE001
                pass
        return ok

    # A Gemini image model (e.g. gemini-2.5-flash-image / "Nano Banana") returns
    # the image inline via generate_content — works on a plain API key tier.
    if model.startswith("gemini"):
        try:
            r = client.models.generate_content(
                model=model, contents=prompt[:1800],
                config=types.GenerateContentConfig(response_modalities=["IMAGE"]))
            for _cnd in (getattr(r, "candidates", None) or []):
                _ct = getattr(_cnd, "content", None)
                for _pt in (getattr(_ct, "parts", None) or []):
                    _inl = getattr(_pt, "inline_data", None)
                    if _inl and getattr(_inl, "data", None):
                        tmp = dest.with_suffix(".imgpng")
                        tmp.write_bytes(_inl.data)
                        return _finish(tmp)
        except Exception:                                  # noqa: BLE001
            return False
        return False

    # Imagen models — generate_images. Seeded/watermark-free first, then plainer
    # configs (some API-key tiers reject aspect_ratio / person_generation / seed).
    _cfgs = [
        dict(number_of_images=1, aspect_ratio="16:9",
             person_generation="allow_adult",
             seed=int(seed) & 0x7FFFFFFF, add_watermark=False),
        dict(number_of_images=1, aspect_ratio="16:9",
             person_generation="allow_adult"),
        dict(number_of_images=1, aspect_ratio="16:9"),
        dict(number_of_images=1),
    ]
    for _c in _cfgs:
        try:
            r = client.models.generate_images(
                model=model, prompt=prompt[:1800],
                config=types.GenerateImagesConfig(**_c))
            gi = list(getattr(r, "generated_images", None) or [])
            if not gi:
                continue
            tmp = dest.with_suffix(".imgpng")
            gi[0].image.save(str(tmp))
            return _finish(tmp)
        except Exception:                                  # noqa: BLE001
            continue
    return False


def _ai_primary_generate(prompt: str, dest: Path, cfg, seed: int,
                         force_fal: bool = False) -> tuple:
    """Generate ONE AI still with the provider policy: Imagen 4 Fast PRIMARY,
    fal.ai FLUX SECONDARY. Returns (ok: bool, provider: str). `force_fal` skips
    Imagen (used on the final ladder rung so fal gets a shot before the free
    Pollinations emergency tier)."""
    if not force_fal and _imagen_available():
        try:
            if _imagen_image(prompt, dest, seed):
                return True, "imagen"
        except Exception:                                  # noqa: BLE001
            pass
    fal_key = getattr(cfg, "fal_key", "") or ""
    if fal_key:
        try:
            if _fal_image(prompt, dest, fal_key,
                          getattr(cfg, "fal_model", ""), seed):
                return True, "fal"
        except Exception:                                  # noqa: BLE001
            pass
    return False, "none"


def _fal_video(prompt: str, dest: Path, key: str, model: str) -> bool:
    """fal.ai text-to-video via the QUEUE API (submit -> poll -> fetch).
    Produces a real ~5s moving cinematic clip from the editor's shot
    prompt — the genuine 'not a still' Vidlore motion. ~$0.10-0.15/clip,
    ~1-2 min each (overlapped across scenes by the thread pool)."""
    import time as _t

    base = f"https://queue.fal.run/{model}"
    hdr = {"Authorization": f"Key {key}", "Content-Type": "application/json"}
    try:
        sub = requests.post(
            base, headers=hdr,
            json={"prompt": prompt[:1500], "aspect_ratio": "16:9"},
            timeout=60,
        )
        if sub.status_code not in (200, 201):
            return False
        j = sub.json()
        status_url = j.get("status_url")
        resp_url = j.get("response_url")
        if not status_url or not resp_url:
            return False
        deadline = _t.time() + 360
        while _t.time() < deadline:
            st = requests.get(status_url, headers=hdr, timeout=30)
            stj = st.json() if st.status_code == 200 else {}
            s = stj.get("status")
            if s == "COMPLETED":
                break
            if s in ("FAILED", "ERROR", "CANCELLED"):
                return False
            _t.sleep(4)
        else:
            return False
        res = requests.get(resp_url, headers=hdr, timeout=60)
        if res.status_code != 200:
            return False
        url = ((res.json() or {}).get("video") or {}).get("url")
        if not url:
            return False
        with requests.get(url, stream=True, timeout=120) as dl:
            dl.raise_for_status()
            with open(dest, "wb") as fh:
                for chunk in dl.iter_content(1 << 16):
                    fh.write(chunk)
        return dest.exists() and dest.stat().st_size > 50_000
    except Exception:
        return False


# Shared HTTP session for Pollinations — keep-alive saves the
# TLS handshake (~200-500ms) on every subsequent image request.
# Pollinations is the hottest external endpoint in a typical render;
# pooling its connections is a meaningful per-image speed win.
import threading as _polli_threading
_POLLI_SESSION: requests.Session | None = None
_POLLI_SESSION_LOCK = _polli_threading.Lock()

def _polli_session() -> requests.Session:
    global _POLLI_SESSION
    if _POLLI_SESSION is None:
        with _POLLI_SESSION_LOCK:
            if _POLLI_SESSION is None:
                s = requests.Session()
                # Generous pool so parallel scene fetches don't queue
                _adapter = requests.adapters.HTTPAdapter(
                    pool_connections=16, pool_maxsize=16, max_retries=0)
                s.mount("https://", _adapter)
                s.mount("http://", _adapter)
                _POLLI_SESSION = s
    return _POLLI_SESSION


# ─── Cross-render PROMPT-HASH cache (USER FIX 2026-05-25) ────────
# Lives in ~/.vidlore/aimg_cache/<sha256-of-prompt>.jpg so the SAME
# prompt across DIFFERENT runs / different briefs / different scenes
# reuses one disk file. Pollinations charges no money but its keyless
# generation takes ~60-90s cold — caching by prompt content avoids
# regenerating the same image even after `output/` is cleaned.
def _polli_prompt_cache_path(prompt: str) -> Path:
    import hashlib, os as _os
    digest = hashlib.sha256((prompt or "").encode("utf-8")).hexdigest()[:32]
    base = Path(
        _os.environ.get("VIDLORE_AIMG_CACHE",
                         str(Path.home() / ".vidlore" / "aimg_cache")))
    base.mkdir(parents=True, exist_ok=True)
    return base / f"{digest}.jpg"


def _pollinations_image(prompt: str, dest: Path, key: str, seed: int) -> bool:
    """Generate ONE AI image. Optimized for speed without sacrificing
    on-script relevance.

    Tactics (all user-requested 2026-05-25):
      1. Prompt-hash cross-render cache: same prompt anywhere → reuse
         a previously generated image (no API call).
      2. Race `turbo` and `flux` in parallel — first response wins,
         the loser is abandoned. Cuts worst-case wall from 240s → 90s.
      3. Tighter timeouts: turbo 60s, flux 90s (was 120s each).
      4. Persistent HTTP session — keep-alive shaves ~300ms/request.
      5. Robust validation — small/non-image responses are rejected so
         a noisy 200 doesn't ship a broken jpg.
    """
    # 1) Prompt-hash cache — instant return if we've made this prompt
    #    before (any run, any scene, any user). Validates size > 10KB.
    _prompt_cache = _polli_prompt_cache_path(prompt)
    if _prompt_cache.exists() and _prompt_cache.stat().st_size > 10_000:
        try:
            shutil.copyfile(_prompt_cache, dest)
            return True
        except Exception:                                  # noqa: BLE001
            pass

    url = _POLLI_URL + urllib.parse.quote(prompt[:480], safe="")
    base = {"width": W, "height": H, "nologo": "true", "safe": "true"}
    headers = {}
    if key:
        base["token"] = key
        headers["Authorization"] = f"Bearer {key}"
    session = _polli_session()

    def _try_model(model: str, sd: int, timeout: int) -> bytes | None:
        try:
            r = session.get(
                url, params={**base, "model": model, "seed": sd},
                headers=headers, timeout=timeout,
            )
            if r.status_code != 200:
                return None
            ctype = r.headers.get("content-type", "")
            if "image" not in ctype or len(r.content) < 8000:
                return None
            return r.content
        except Exception:                                  # noqa: BLE001
            return None

    # 2) PARALLEL RACE — fire turbo and flux at the same time, take
    #    the first valid image; cancel the loser.
    from concurrent.futures import ThreadPoolExecutor as _Pool
    from concurrent.futures import wait as _wait, FIRST_COMPLETED
    bytes_out: bytes | None = None
    with _Pool(max_workers=2) as pool:
        f_turbo = pool.submit(_try_model, "turbo", seed, 60)
        f_flux  = pool.submit(_try_model, "flux",  seed, 90)
        pending = {f_turbo, f_flux}
        while pending and bytes_out is None:
            done, pending = _wait(pending, return_when=FIRST_COMPLETED,
                                    timeout=95)
            if not done:
                break                                       # overall timeout
            for f in done:
                got = f.result()
                if got:
                    bytes_out = got
                    # Cancel the still-running sibling (best-effort)
                    for p in pending:
                        p.cancel()
                    pending = set()
                    break

    # ROBUSTNESS FALLBACK — the free endpoint RATE-LIMITS under burst (a render
    # that rescues many rejected beats fires many generations in a row, and the
    # keyless tier starts throttling / timing out after a few). Both models then
    # miss and the beat would drop to a bare TEXT SLIDE. So BACK OFF and RETRY:
    # space out from the throttled burst and try again — first the full prompt,
    # then a SIMPLIFIED core-subject prompt (also covers the over-long-prompt
    # failure mode). This is the difference between "relevant AI image" and
    # "FARMER text card" when many beats need a still. No paid key required;
    # setting POLLINATIONS_API_KEY lifts the rate limit further.
    if bytes_out is None:
        import time as _time
        _core = re.split(r"[,;.]", prompt.strip())[0].strip()
        _simple = " ".join(_core.split()[:10]) or prompt[:80]
        for _attempt, (_p, _backoff) in enumerate(
                ((prompt[:240], 2.5), (_simple[:240], 5.0), (_simple[:160], 9.0))):
            if bytes_out is not None:
                break
            _time.sleep(_backoff)            # let the rate-limit window reset
            try:
                _u2 = _POLLI_URL + urllib.parse.quote(_p, safe="")
                _r2 = session.get(
                    _u2, params={**base, "model": "turbo", "seed": seed + _attempt},
                    headers=headers, timeout=85)
                if _r2.status_code == 200 \
                        and "image" in _r2.headers.get("content-type", "") \
                        and len(_r2.content) >= 8000:
                    bytes_out = _r2.content
            except Exception:                                  # noqa: BLE001
                pass
    if bytes_out is None:
        return False

    # Save the image — validate dimensions, normalise to W×H jpeg
    tmp = dest.with_suffix(".dl")
    try:
        tmp.write_bytes(bytes_out)
        img = Image.open(tmp).convert("RGB")
        if min(img.size) < 256:
            return False
        if img.size != (W, H):
            img = img.resize((W, H), Image.LANCZOS)
        img.save(dest, "JPEG", quality=92)
    except Exception:                                      # noqa: BLE001
        return False
    finally:
        tmp.unlink(missing_ok=True)

    if not (dest.exists() and dest.stat().st_size > 10_000):
        return False

    # Populate the cross-render prompt cache so the next render (or any
    # other scene with this exact prompt) skips the API entirely.
    try:
        shutil.copyfile(dest, _prompt_cache)
    except Exception:                                      # noqa: BLE001
        pass
    return True


# --------------------------------------------------------------------------- #
# Openverse keyless image search (the default free, content-relevant tier)
# --------------------------------------------------------------------------- #
_OPENVERSE_URL = "https://api.openverse.org/v1/images/"
_UA = {"User-Agent": "vidrush-clone/0.1 (+https://localhost)"}


def _is_archive_book_artifact(src: Path) -> bool:
    """Detect a vintage BOOK ARTIFACT scan that escaped `_is_text_page`.

    Catches:
      • Old leather / cloth book covers (red/brown/black uniform texture
        with small embossed gilt text like a year or title) — these are
        PHOTOGRAPHS of a surface, not text pages, so `_is_text_page`
        passes them. They read as "random 1876 leather book" on screen.
      • Aged author-byline title pages with library-stamp annotations
        ("BY EDWARD STRAHAN", handwritten "Earl Shinn") that have some
        sepia midtones from yellowed paper which let `_is_text_page`'s
        `mid < 0.20` invariant fail.

    Heuristic: image is BOOK ARTIFACT iff
      (a) very low colour variance (uniform surface) AND warm/dark hue
          (leather/cloth/sepia), OR
      (b) high warm-cast mean (rmean > 160) AND tiny mid-region with
          glyph-density concentrated in <30% of the frame (text island
          on aged paper).
    Real photos have at least two colour regions (sky+ground, face+bg)
    so colour variance is much higher than a uniform book cover.

    Reported by user 2026-05-27 (5-min Mossad sample audit): "1876"
    leather cover + "BY EDWARD STRAHAN" title page leaked through.
    """
    try:
        import numpy as np
        img = Image.open(src).convert("RGB")
        if min(img.size) < 60:
            return False
        a = np.asarray(img.resize((128, 72), Image.BILINEAR),
                       dtype="float32")
        L = (0.299 * a[..., 0] + 0.587 * a[..., 1] + 0.114 * a[..., 2])
        # (a) Uniform warm/dark surface (leather/cloth book cover).
        # Split into 4x4 = 16 patches, compute per-patch mean colour;
        # uniform surface => all 16 means cluster tight.
        rgb_means = a.reshape(4, 18, 4, 32, 3).mean(axis=(1, 3))  # 4x4x3
        rgb_flat = rgb_means.reshape(-1, 3)                      # 16x3
        patch_std = float(rgb_flat.std(axis=0).mean())           # variance
        rmean = float(a[..., 0].mean())
        gmean = float(a[..., 1].mean())
        bmean = float(a[..., 2].mean())
        warm = (rmean > gmean + 8 and rmean > bmean + 12)
        dark_warm = warm and 40 < rmean < 130           # leather/cloth tones
        # Tight cluster (<14 RGB stddev across the whole frame) + warm cast +
        # mostly dark = leather/cloth book cover with subtle embossed text.
        if patch_std < 14.0 and dark_warm:
            return True
        # (b) Sepia title page with text island. High R-mean (warm paper),
        # tiny mid-tone region (the printed glyph block), bulk of frame
        # near-uniform paper.
        mid = float(((L >= 80) & (L <= 200)).mean())
        if rmean > 160 and gmean > 140 and patch_std < 18.0 and mid < 0.30:
            return True
        return False
    except Exception:                                       # noqa: BLE001
        return False


def _is_text_page(src: Path) -> bool:
    """Detect a BOOK-SCAN FRONTISPIECE / text-only page — the kind of result
    Internet Archive, LoC and Wikimedia frequently return for vaguely-
    worded queries (an old "Art Journal" title page, a Pennsylvania
    College alumni roster, an "Edward Strahan" copyright page, etc.).
    These read as RANDOM PRINTED PAGES with no documentary value and must
    NOT land in the film.

    Two-branch heuristic (no OCR, fast):

      (A) PURE WHITE/GREY BOOK PAGE — classic scan: bright paper, sparse
          dark ink, near-zero photographic mid-tones, low saturation.
      (B) SEPIA / AGED PAPER — warm cream paper with dark glyphs.  This
          was the killer false negative in the old filter: aged paper has
          saturation 30-50 (warm cast), so the previous `sat < 22`
          threshold let every old book page through.  Now we accept high
          saturation IF the paper is warm-cast (R > G > B) AND there are
          essentially zero photographic mid-tones (no subject content).

    Real photographs are eliminated because their `mid` is high (faces,
    landscapes, scenes all live in 80-200 luminance). A snow scene has
    high `light` but also high `mid` from horizon/subject. So `mid < 0.20`
    is the key invariant that separates "text on paper" from "photograph
    with bright sky/snow/wall".
    """
    try:
        import numpy as np
        img = Image.open(src).convert("RGB")
        if min(img.size) < 60:
            return False                                    # too small to judge
        a = np.asarray(img.resize((128, 72), Image.BILINEAR),
                       dtype="float32")
        L = (0.299 * a[..., 0] + 0.587 * a[..., 1] + 0.114 * a[..., 2])
        light = float((L > 200).mean())             # paper background
        dark = float((L < 80).mean())               # glyph ink
        mid = float(((L >= 80) & (L <= 200)).mean())  # photographic mid-tones
        sat = float((a.max(axis=2) - a.min(axis=2)).mean())  # colour life
        # warm-cast signature for sepia / aged paper
        rg = float(a[..., 0].mean() - a[..., 1].mean())  # R minus G
        gb = float(a[..., 1].mean() - a[..., 2].mean())  # G minus B
        rmean = float(a[..., 0].mean())

        # (A) PURE WHITE/GREY BOOK PAGE -- the original heuristic, kept
        # but tightened: paper + ink + no photo, near-monochrome.
        if (light > 0.55 and dark < 0.25
                and mid < 0.20 and sat < 25.0):
            return True
        # (B) SEPIA / AGED PAPER -- warm cream paper, dark ink, no photo
        # subject pixels.  Saturation can be HIGH because of the warm
        # cast, so we don't gate on sat here.  Instead we require the
        # warm-cast signature (R > G > B by a meaningful margin) AND a
        # bright red mean (the paper IS the dominant pixel).
        if (light > 0.50 and mid < 0.20
                and rg > 8.0 and gb > 10.0 and rmean > 180):
            return True
        # (C) DEEP SEPIA UNIFORM SURFACE — book pages PHOTOGRAPHED in
        # dim light (Library of Congress / archive.org book scans often
        # come back with `light=0.00, mid=1.00` because the whole frame
        # is sepia at 130-180 luminance — nothing bright enough to be
        # "paper white", everything in the mid band. Reported by user
        # 2026-05-28 on `loc_003_1.jpg` ("BY JULES JANIN, BALZAC,
        # CORMENIN") and `loc_027_2.jpg` ("BY EDWARD STRAHAN") which
        # both passed (A) and (B).
        # Signature: extreme warm cast (g-b > 25 — real photos rarely
        # exceed 15), high saturation from the cast, bulk of the frame
        # in the mid band (no bright sky, no deep shadow), and a
        # near-uniform paper surface (single colour cluster).
        if (gb > 22.0 and rg > 12.0 and mid > 0.60
                and sat > 35.0 and rmean > 150):
            return True
        return False
    except Exception:                                       # noqa: BLE001
        return False


# Host substrings whose pages are almost always a social / messaging /
# app screenshot or a private chat - never legitimate documentary B-roll.
# Used to REJECT web-reference URLs before download AND any YouTube frame
# whose extracted file later contains visible UI chrome from these apps.
_UI_HOSTS: tuple[str, ...] = (
    "t.me/", "telegram.me/", "telegram.org/",
    "twitter.com/", "x.com/", "mobile.twitter.com/",
    "facebook.com/", "fb.com/", "fb.watch/",
    "instagram.com/", "instagr.am/",
    "tiktok.com/", "vm.tiktok.com/",
    "reddit.com/r/", "redd.it/",
    "discord.com/", "discord.gg/",
    "whatsapp.com/", "wa.me/", "chat.whatsapp.com/",
    "linkedin.com/in/", "linkedin.com/posts/",
    "pinterest.com/pin/", "pinterest.com/", "pin.it/",
    "snapchat.com/",
    "mastodon.social/", "bsky.app/",
    "vk.com/", "ok.ru/",
    "weibo.com/", "weibo.cn/",
)


def _is_ui_host(url: str) -> bool:
    """Reject a URL before fetch if its host is a known social / messaging
    site whose pages render as private chat / feed screenshots."""
    if not url:
        return False
    u = url.lower()
    return any(h in u for h in _UI_HOSTS)


def _is_ui_screenshot(src: Path) -> bool:
    """Detect a SCREENSHOT of a web browser / messaging app / social feed
    that leaked from a web-reference or a YouTube frame.

    Distinctive signatures (any one fires):

      1. Browser chrome at the very top: a near-flat horizontal band,
         largely greyscale (window controls + URL pill).
      2. Messaging-app header colour: Telegram cyan, Discord indigo,
         Twitter blue concentrated in the top ~12% of the frame.
      3. High horizontal-text-edge density across the centre of the frame
         (the giveaway of a chat / article / feed layout).

    Returns True to REJECT the frame. Heuristic, never OCR-heavy; the goal
    is to catch the obvious offenders (Telegram, Twitter, Reddit, WhatsApp,
    plain browser windows) without burning CPU."""
    try:
        import numpy as np
        with Image.open(src) as im:
            im = im.convert("RGB")
            w, h = im.size
            if w < 320 or h < 200:
                return False
            a = np.asarray(im.resize((320, 180), Image.BILINEAR),
                           dtype="float32")
    except Exception:                                       # noqa: BLE001
        return False
    nw, nh = a.shape[1], a.shape[0]

    # ---- 1. browser chrome band at top --------------------------------- #
    top_h = max(8, int(nh * 0.08))
    top = a[:top_h]
    # how greyscale is the top band? (chrome is grey, headers are coloured)
    r, g, b = top[..., 0].mean(), top[..., 1].mean(), top[..., 2].mean()
    is_grey = abs(r - g) < 6 and abs(g - b) < 6
    # row-wise std along x: chrome rows are uniform across the width
    row_std_x = float(top.std(axis=1).mean())
    chrome_like = is_grey and row_std_x < 22.0 and 130 < top.mean() < 245

    # ---- 2. coloured messaging-app header ------------------------------ #
    hd_h = max(12, int(nh * 0.12))
    hd = a[:hd_h]
    hr, hg, hb = hd[..., 0].mean(), hd[..., 1].mean(), hd[..., 2].mean()
    # Telegram cyan-ish:  R<100, G>120, B>150
    tg_like = hr < 105 and hg > 110 and hb > 145
    # Twitter / Discord / Facebook saturated blue: B dominant, R<80
    blue_app_like = hb > 160 and hr < 90 and hb - hr > 70
    header_app = tg_like or blue_app_like

    # ---- 3. centre text density (rows of horizontal glyphs) ----------- #
    mid = a[int(nh * 0.25): int(nh * 0.85), int(nw * 0.10): int(nw * 0.90)]
    if mid.size > 0:
        gray = mid.mean(axis=2)
        # horizontal gradient = vertical edges between glyphs / icons
        vgrad = np.abs(np.diff(gray, axis=1))
        text_density = float((vgrad > 28).mean())
    else:
        text_density = 0.0

    # ---- 4. wide near-white card centred (chat bubble / article) ------- #
    cx = a[int(nh * 0.30): int(nh * 0.85), int(nw * 0.25): int(nw * 0.85)]
    if cx.size > 0:
        cx_L = (0.299 * cx[..., 0] + 0.587 * cx[..., 1]
                + 0.114 * cx[..., 2])
        bubble_like = float((cx_L > 215).mean()) > 0.35
    else:
        bubble_like = False

    # decision: any of the strong signatures
    if chrome_like and (text_density > 0.06 or bubble_like):
        return True
    if header_app and (text_density > 0.05 or bubble_like):
        return True
    # Fallback: very high text density AND a wide light card = chat / list
    if text_density > 0.12 and bubble_like:
        return True
    return False


def _cover_to_canvas(src: Path, dest: Path,
                     *, ai_grade: bool = True) -> bool:
    """Cover-crop + resize any image to exactly W x H and save as JPEG.

    When ``ai_grade`` is True (default for AI-generated stills), we
    apply a subtle "film emulsion" pass so the AI image sits on the
    SAME grading as the surrounding Pexels stock instead of betraying
    itself as a perfectly clean digital render.  Three small touches:

      1. **Shadow lift + highlight roll-off** — a soft S-curve so the
         deep blacks aren't crushed and the brights aren't clipped
         (matches how a documentary colourist breathes range into a
         crisp render).
      2. **Warm-shadow / cool-highlight split-tone** — almost
         imperceptible (+2-3 on R in shadows, -2 on B in highlights)
         so the AI doesn't have the "AI-perfect neutral grey" look
         that Pexels stock never has.
      3. **8% film grain** — uniform luma noise blended in screen
         mode so the texture matches handheld Pexels b-roll.

    Pexels footage skips this pass — it already has natural grain
    and a colourist's hand on it.
    """
    try:
        img = Image.open(src).convert("RGB")
        if min(img.size) < 200:
            return False
        sw, sh = img.size
        scale = max(W / sw, H / sh)
        nw, nh = int(sw * scale + 0.5), int(sh * scale + 0.5)
        img = img.resize((nw, nh), Image.LANCZOS)
        left, top = (nw - W) // 2, (nh - H) // 2
        img = img.crop((left, top, left + W, top + H))
        if ai_grade:
            img = _ai_grade(img)
        img.save(dest, "JPEG", quality=90)
        return dest.exists() and dest.stat().st_size > 10_000
    except Exception:
        return False


def _ai_grade(img: "Image.Image") -> "Image.Image":
    """Apply the AI ↔ Pexels emulsion match: S-curve, split-tone,
    film grain.  Look DNA overrides EVERY knob so a true-crime channel
    can crush blacks + cool the shadows + heavy grain while a Netflix
    Epic channel runs lifted shadows + warm split + restrained grain.

    Falls back to the cinematic defaults when no channel is active —
    so AI portraits still emulsion-match Pexels even in legacy mode.
    """
    try:
        import numpy as np
    except ImportError:                                            # noqa: BLE001
        return img
    # Look DNA pulls — each is optional, each has a safe default
    try:
        from .look_dna import look_get as _lg_g
        bright_lift = float(_lg_g("grade.brightness_lift", default=0.0))
        sat_lift    = float(_lg_g("grade.saturation_lift", default=0.0))
        shadow_lift = float(_lg_g("grade.shadow_lift",     default=0.025))
        high_roll   = float(_lg_g("grade.highlight_roll",  default=0.0))
        warm_split  = float(_lg_g("grade.warm_shadow_split", default=0.018))
        grain       = float(_lg_g("ai.grain_strength",     default=0.022))
    except Exception:                                              # noqa: BLE001
        bright_lift, sat_lift, shadow_lift = 0.0, 0.0, 0.025
        high_roll, warm_split, grain       = 0.0, 0.018, 0.022
    if not _AI_FILM_GRAIN:
        grain = 0.0          # AI-still post-grade grain is opt-in (VIDLORE_AI_FILM_GRAIN)
    try:
        a = np.asarray(img, dtype="float32") / 255.0
        # 1) Contrast S-curve (always +6 %)
        a = 0.5 + (a - 0.5) * 1.06
        a = np.clip(a, 0.0, 1.0)
        # Shadow lift (DNA-tunable)
        shadow_mask = np.clip(1.0 - a * 3.0, 0.0, 1.0)
        a = a + shadow_mask * shadow_lift
        # Highlight roll-off (DNA-tunable, negative = crush highlights)
        if abs(high_roll) > 1e-4:
            high_mask = np.clip((a - 0.7) * 3.3, 0.0, 1.0)
            a = a + high_mask * high_roll
        # Global brightness lift
        if abs(bright_lift) > 1e-4:
            a = a + bright_lift
        # 2) Split-tone with DNA-tunable warm amount (negative = cool shadows)
        L = 0.299 * a[..., 0] + 0.587 * a[..., 1] + 0.114 * a[..., 2]
        warm = np.clip(1.0 - L * 2.2, 0.0, 1.0)[..., None]
        cool = np.clip((L - 0.55) * 2.5, 0.0, 1.0)[..., None]
        tint_warm = np.array([warm_split,
                              warm_split * 0.33,
                              -warm_split * 0.66], dtype="float32")
        tint_cool = np.array([-0.010, -0.004, 0.014], dtype="float32")
        a = a + warm * tint_warm + cool * tint_cool
        # Saturation lift via simple scale toward grey (DNA-tunable)
        if abs(sat_lift) > 1e-4:
            grey = L[..., None]
            a = grey + (a - grey) * (1.0 + sat_lift * 4.0)
        a = np.clip(a, 0.0, 1.0)
        # 3) Film grain (DNA-tunable amplitude)
        rng = np.random.default_rng(seed=int(a.sum() * 1000) & 0x7FFFFFFF)
        noise = rng.normal(0.0, max(0.005, grain), a.shape[:2]).astype("float32")
        a = a + noise[..., None]
        a = np.clip(a, 0.0, 1.0)
        out = (a * 255.0 + 0.5).astype("uint8")
        return Image.fromarray(out, "RGB")
    except Exception:                                              # noqa: BLE001
        return img


def _visual_queries(scene: Scene, theme_broll: str = "documentary cinematic") -> list[str]:
    """Ordered search candidates, concrete -> on-theme.

    ``scene.keywords`` is now concrete-visual (see script_gen._keywords),
    so it leads. Every tail query is the *theme's* cinematic B-roll
    phrase, so a weak scene still gets on-topic footage — never a random
    or empty result, never a flat slide just because a noun was rare.
    """
    kw = [k for k in (scene.keywords or []) if k]
    cands: list[str] = []
    if len(kw) >= 2:
        cands.append(" ".join(kw[:3]))   # most specific concrete phrase
        cands.append(" ".join(kw[:2]))
    if kw:
        cands.append(kw[0])              # single strongest subject
        cands.append(f"{kw[0]} {theme_broll}")
    cands.append(theme_broll)            # always on-theme, never random
    cands.append("nature landscape")     # universal high-recall safety net

    seen: set[str] = set()
    out: list[str] = []
    for c in cands:
        c = c.strip()
        if c and c.lower() not in seen:
            seen.add(c.lower())
            out.append(c)
    # PERIOD GUARD: on a period documentary, prepend ERA-BIASED variants of the
    # top image queries so archival/vintage results lead — the image tiers
    # (Openverse etc.) previously got NO era bias, only the Pexels video path
    # did. Additive + defensive; no-op on modern/unknown-era videos.
    try:
        from . import period_guard as _pg
        _era = _VIDEO_CTX.get("era")
        if _era and _era.get("period_sensitive"):
            _bias = _pg.query_bias(_era)
            if _bias:
                _btag = " ".join(_bias[:2])
                out = [f"{q} {_btag}" for q in out[:2]] + out
    except Exception:                                          # noqa: BLE001
        pass
    return out


def _openverse_one(query: str, dest: Path, variant: int = 0) -> bool:
    try:
        r = requests.get(
            _OPENVERSE_URL,
            params={"q": query, "page_size": 12, "mature": "false",
                    "category": "photograph"},
            headers=_UA,
            timeout=25,
        )
        r.raise_for_status()
        results = r.json().get("results", []) or []
        # widest first — better source resolution for the 1080p canvas
        results.sort(key=lambda x: (x.get("width") or 0), reverse=True)
        # `variant` rotates the start so "Regenerate" yields a new image
        if results and variant:
            o = variant % len(results)
            results = results[o:] + results[:o]
        tmp = dest.with_suffix(".dl")
        for item in results:
            # search-side era guard: skip a modern-era photo on a period doc
            _tags = item.get("tags") or []
            _meta = (str(item.get("title") or "") + " " + " ".join(
                (t.get("name", "") if isinstance(t, dict) else str(t))
                for t in _tags))
            if _period_blocked(_meta):
                continue
            for link in (item.get("url"), item.get("thumbnail")):
                if not link:
                    continue
                try:
                    with requests.get(
                        link, headers=_UA, stream=True, timeout=30
                    ) as dl:
                        dl.raise_for_status()
                        if "image" not in dl.headers.get("content-type", ""):
                            continue
                        with open(tmp, "wb") as fh:
                            for chunk in dl.iter_content(1 << 16):
                                fh.write(chunk)
                    if _cover_to_canvas(tmp, dest):
                        return True
                except Exception:
                    continue
                finally:
                    tmp.unlink(missing_ok=True)
        return False
    except Exception:
        return False


def _openverse_image(queries: list[str], dest: Path, variant: int = 0) -> bool:
    """Try each candidate query in order; first hit wins."""
    for q in queries:
        if _openverse_one(q, dest, variant):
            return True
    return False


# --------------------------------------------------------------------------- #
# Wikimedia Commons — REAL photos of the actual subject (people, places,
# historical events, science). Free / public-domain & CC, legally safe to
# use in monetized YouTube videos (unlike Google Images, which only links
# to other people's copyrighted pictures). Keyless. This is the upgrade
# that gives a true documentary "real footage" feel.
# --------------------------------------------------------------------------- #
_WIKIMEDIA_API = "https://commons.wikimedia.org/w/api.php"
# file types we can actually use as a photo on the 1080p canvas
_WIKI_OK_MIME = ("image/jpeg", "image/png", "image/webp")


def _wikimedia_on() -> bool:
    return os.environ.get("VIDLORE_WIKIMEDIA", "1").strip().lower() not in (
        "0", "false", "no", "off"
    )


def _wikimedia_one(query: str, dest: Path, variant: int = 0) -> bool:
    try:
        r = requests.get(
            _WIKIMEDIA_API,
            params={
                "action": "query",
                "format": "json",
                "generator": "search",
                "gsrsearch": query,
                "gsrnamespace": 6,          # File: namespace only
                "gsrlimit": 18,
                "prop": "imageinfo",
                "iiprop": "url|size|mime",
                "iiurlwidth": 1920,         # ask for a 1920-wide render
            },
            headers=_UA,
            timeout=25,
        )
        r.raise_for_status()
        pages = list((r.json().get("query", {}) or {}).get("pages", {}).values())
        cands = []
        for p in pages:
            ii = (p.get("imageinfo") or [{}])[0]
            mime = (ii.get("mime") or "").lower()
            if mime not in _WIKI_OK_MIME:
                continue                    # skip svg/tif/pdf/video/audio
            w = ii.get("width") or 0
            if w < 600:                     # too small for a clean canvas
                continue
            link = ii.get("thumburl") or ii.get("url")
            if link:
                # RC4: keep the File: page title so the portrait caller can
                # IDENTITY-VERIFY whose photo this actually is.
                cands.append((w, link, p.get("title") or ""))
        cands.sort(key=lambda t: t[0], reverse=True)   # widest first
        if cands and variant:
            o = variant % len(cands)
            cands = cands[o:] + cands[:o]
        tmp = dest.with_suffix(".dl")
        for _, link, _title in cands:
            try:
                with requests.get(
                    link, headers=_UA, stream=True, timeout=30
                ) as dl:
                    dl.raise_for_status()
                    if "image" not in dl.headers.get("content-type", ""):
                        continue
                    with open(tmp, "wb") as fh:
                        for chunk in dl.iter_content(1 << 16):
                            fh.write(chunk)
                # v12: Wikimedia is full of LoC / IA mirrored title pages,
                # author byline pages, leather book covers, and other
                # pre-1923 book artifacts — these get returned for ANY
                # historical-flavoured query. Filter them out here so the
                # main pipeline never sees them.
                if _is_text_page(tmp):
                    continue
                if _is_archive_book_artifact(tmp):
                    continue
                if _cover_to_canvas(tmp, dest):
                    # RC4: record the accepted file title (drop the "File:"
                    # / extension noise) for the identity-verification gate.
                    global _LAST_WIKIMEDIA_TITLE
                    _LAST_WIKIMEDIA_TITLE = re.sub(
                        r"\.(jpe?g|png|gif|tiff?|webp)$", "",
                        re.sub(r"^File:", "", _title, flags=re.I).strip(),
                        flags=re.I).strip()
                    return True
            except Exception:
                continue
            finally:
                tmp.unlink(missing_ok=True)
        return False
    except Exception:
        return False


def _wikimedia_image(queries: list[str], dest: Path, variant: int = 0) -> bool:
    """Try each candidate query in order; first real photo wins."""
    for q in queries:
        if _wikimedia_one(q, dest, variant):
            return True
    return False


# --------------------------------------------------------------------------- #
# Library of Congress — REAL public-domain ARCHIVAL imagery (historical
# photos, newspapers, maps, war/intelligence/figures). Free, keyless, JSON
# API. This is the documentary-research upgrade for HISTORICAL / obscure /
# geopolitical topics where modern stock is weak — exactly the gap pure
# stock libraries leave. Gated to historically-flavoured scenes so it never
# pulls an old photo over a good modern clip.
# --------------------------------------------------------------------------- #
_LOC_URL = "https://www.loc.gov/photos/"
_HIST_WORDS = (
    "war", "empire", "soviet", "cold war", "nazi", "wwii", "wwi", "ancient",
    "dynasty", "regime", "revolution", "espionage", "intelligence", "spy",
    "kgb", "cia", "operation", "archive", "historic", "century", "medieval",
    "president", "general", "treaty", "border", "wall", "defector", "agent",
    "military", "battle", "vintage", "old", "1940s", "1950s", "1960s",
    "1970s", "1980s",
)


def _historical_hint(sc) -> bool:
    """True if a scene reads as HISTORICAL (a year, or history/intel words)
    — the gate for archival sources so they fire only where they belong."""
    blob = (" ".join(sc.keywords or []) + " " + (sc.query or "") + " "
            + (sc.narration or "")).lower()
    if re.search(r"\b(1[5-9]\d{2}|20[0-2]\d)\b", blob):     # a year
        return True
    return any(w in blob for w in _HIST_WORDS)


# ─────────────────────────────────────────────────────────────────────
# DEEP-HISTORICAL gate (v12, 2026-05-27)
#
# `_historical_hint` is intentionally generous — it triggers on any
# intel vocabulary ("spy", "intelligence", "general", "cia") so the
# generic ARCHIVAL lane (LoC, Wikimedia) can fire for Cold-War-era and
# modern intel scenes. But Internet Archive's image collection is 95%
# PRE-1923 PUBLIC DOMAIN BOOKS — vintage Art Journal title pages, 1876
# leather covers, Edward Strahan / Earl Shinn library annotations.
# Those land on a modern Mossad scene as "random 19th-century book"
# garbage. Reported by user on 5-min Mossad sample (Catherine card +
# 1876 + Strahan).
#
# `_archive_appropriate` is the TIGHTER gate that should be used by
# `_archive_image` and similar pre-1923 sources. It requires either
# an explicit pre-1950 year or a clear pre-modern era word. Modern
# intel topics no longer qualify just because they share vocabulary
# with WWII espionage.
# ─────────────────────────────────────────────────────────────────────

_TRULY_HISTORICAL_WORDS = (
    "medieval", "ancient", "antiquity", "prehistoric", "renaissance",
    "byzantine", "ottoman", "tudor", "victorian", "edwardian",
    "georgian", "colonial", "dynasty", "empire", "crusade",
    "reformation", "enlightenment", "industrial revolution",
    "civil war", "wwi", "wwii", "world war i", "world war ii",
    "nazi", "third reich", "weimar", "tsarist", "tsar",
    "ww1", "ww2",
)


def _archive_appropriate(sc) -> bool:
    """True only when a scene EXPLICITLY needs pre-1950 archival imagery.

    Mossad / CIA / intelligence stories are usually CONTEMPORARY even
    when they use vocabulary like 'spy', 'general', 'agent' that
    overlaps with WWII-era intel work. The looser `_historical_hint()`
    matches those words and lets Internet Archive return 1876 leather
    book covers, Edward Strahan title pages, etc. — completely off-
    topic. This tighter gate requires either:
      (a) an EXPLICIT pre-1950 year (1500-1949), OR
      (b) a CLEAR pre-modern era word from `_TRULY_HISTORICAL_WORDS`.
    """
    blob = (" ".join(sc.keywords or []) + " " + (sc.query or "") + " "
            + (sc.narration or "")).lower()
    if re.search(r"\b(1[5-9]\d{2}|19[0-4]\d)\b", blob):    # 1500-1949
        return True
    return any(w in blob for w in _TRULY_HISTORICAL_WORDS)


def _share_env(name: str, default: float, hi: float = 0.7) -> float:
    try:
        s = float(os.environ.get(name, str(default)))
    except (TypeError, ValueError):
        s = default
    return min(hi, max(0.0, s))


def _archival_share() -> float:
    """Target fraction of HISTORICAL footage beats served by public-domain
    ARCHIVAL imagery (Wikimedia / LoC / Internet Archive). Tunable via
    VIDLORE_ARCHIVAL_SHARE. Default 0.20 -> ~15-25% archival of the mix."""
    return _share_env("VIDLORE_ARCHIVAL_SHARE", 0.20)


def _yt_share() -> float:
    """Target fraction of DEEP-historical footage beats served by YouTube
    documentary frame extraction. Default 0.10 -> lands ~7-8% after lane
    misses fall back to archival; stays inside the 5-10% band."""
    return _share_env("VIDLORE_YT_SHARE", 0.10, hi=0.4)


def _webref_share() -> float:
    """Target fraction of DEEP-historical footage beats served by controlled
    web-reference imagery. Default 0.09 -> ~6-7% after misses. A strategic
    accent, never a flood."""
    return _share_env("VIDLORE_WEBREF_SHARE", 0.09, hi=0.35)


def _visual_lane(sc, beat: int) -> str:
    """THE BALANCE CONTROLLER. Assigns each footage beat a *primary* visual
    lane so the finished documentary lands on a real-world target mix:

        stock video     ~60%   (the backbone — motion footage leads)
        archival        ~20%   (Wikimedia / LoC / Internet Archive)
        youtube frame   ~8%    (deep-historical only)
        web reference   ~7%    (deep-historical only, smallest lane)

    Deterministic + INTERLEAVED (a big-stride ring) so lanes never clump and
    a scene mixes sources beat to beat. Non-historical scenes are always
    `stock` (enrichment sources are gated off them entirely). YouTube/web
    lanes only open on DEEP-historical beats (war / intelligence / archival
    subject matter) — exactly where rare documentary visuals add value; on
    milder history those shares fold back into stock. Lanes are a *first
    try*: a miss falls through to the next-best real source, and hard
    per-film budgets cap YT/web so they can never overshoot."""
    if not (sc.keywords and _historical_hint(sc)):
        return "stock"
    deep = _deep_historical_hint(sc)
    y = int(round(_yt_share() * 100)) if deep else 0
    w = int(round(_webref_share() * 100)) if deep else 0
    a = int(round(_archival_share() * 100))
    # interleave: walk a 100-slot ring in big coprime steps so consecutive
    # beats land far apart (no two enrichment beats back to back).
    seq = int(getattr(sc, "index", 0)) * 7 + int(beat)
    slot = (seq * 13) % 100
    if slot < y:
        return "yt"
    if slot < y + w:
        return "web"
    if slot < y + w + a:
        return "archival"
    return "stock"


def _loc_on() -> bool:
    """Library of Congress source switch.

    DEFAULT OFF (v12.2, 2026-05-28). User requested "LoC. block kar do"
    after the LoC search kept returning WPA folksong index cards (1939
    "Sea lion / Sung by Katharine and Christeen Shipp"), 1800s book
    title pages ("BY EDWARD STRAHAN", "BY JULES JANIN, BALZAC,
    CORMENIN"), and similar pre-1950 catalog artifacts even on modern
    Mossad/spy scenes. The image-side detectors caught some but not
    all; the only reliable fix is to disable the source.

    Set `VIDLORE_LOC_ENABLE=1` to re-enable for explicitly historical
    documentary work (WWI/WWII/civil-rights/pre-1950 content).
    """
    return os.environ.get("VIDLORE_LOC_ENABLE", "0").strip().lower() in (
        "1", "true", "yes", "on"
    )


def _loc_one(query: str, dest: Path, variant: int = 0, force: bool = False) -> bool:
    # `force=True` lets the PORTRAIT pipeline use LoC (validator-protected) even
    # though general footage LoC stays disabled (the WPA-index-card block).
    if not force and not _loc_on():
        return False
    try:
        r = requests.get(_LOC_URL,
                         params={"q": query, "fo": "json", "c": 30},
                         headers=_UA, timeout=20)
        r.raise_for_status()
        results = r.json().get("results", []) or []
        cands = []
        for it in results:
            ius = it.get("image_url") or []
            if not ius:
                continue
            url = ius[-1]                      # last = largest
            hh = re.search(r"h=(\d+)", url)
            ww = re.search(r"w=(\d+)", url)
            dim = max(int(hh.group(1)) if hh else 0,
                      int(ww.group(1)) if ww else 0)
            clean = url.split("#")[0]
            if clean.startswith("http") and dim >= 600:   # quality gate
                # RC4: keep the item title for the identity-verification gate.
                t = it.get("title")
                if isinstance(t, (list, tuple)):
                    t = t[0] if t else ""
                cands.append((dim, clean, str(t or "")))
        cands.sort(key=lambda t: t[0], reverse=True)       # largest first
        if cands and variant:
            o = variant % len(cands)
            cands = cands[o:] + cands[:o]
        tmp = dest.with_suffix(".dl")
        for _, link, _title in cands:
            try:
                with requests.get(link, headers=_UA, stream=True,
                                  timeout=30) as dl:
                    dl.raise_for_status()
                    if "image" not in dl.headers.get("content-type", ""):
                        continue
                    with open(tmp, "wb") as fh:
                        for chunk in dl.iter_content(1 << 16):
                            fh.write(chunk)
                # SKIP text-only book/frontispiece scans — these are useless
                # archival "results" the LoC search occasionally returns and
                # they read as random printed pages to the viewer.
                # v12: also catch leather/cloth book covers (1876 / Strahan).
                if _is_text_page(tmp):
                    continue
                if _is_archive_book_artifact(tmp):
                    continue
                if _cover_to_canvas(tmp, dest):
                    global _LAST_LOC_TITLE      # RC4: accepted item title
                    _LAST_LOC_TITLE = _title.strip()
                    return True
            except Exception:                              # noqa: BLE001
                continue
            finally:
                tmp.unlink(missing_ok=True)
        return False
    except Exception:                                      # noqa: BLE001
        return False


def _loc_image(queries: list[str], dest: Path, variant: int = 0,
               force: bool = False) -> bool:
    """Try each query; first usable archival photo wins."""
    for q in queries:
        if q and _loc_one(q, dest, variant, force=force):
            return True
    return False


# --------------------------------------------------------------------------- #
# Internet Archive — the deepest REAL archival well: scanned photos, declassi-
# fied documents, war/intelligence imagery, vintage maps & posters, obscure
# historical material modern stock can never cover. Free, keyless, two-step
# JSON API (search -> per-item file list -> download). Same HISTORICAL gate
# and quality floor as LoC so it never replaces a good modern clip and never
# pulls a tiny thumbnail. Off via VIDLORE_ARCHIVE=0.
# --------------------------------------------------------------------------- #
_ARCHIVE_SEARCH = "https://archive.org/advancedsearch.php"
_ARCHIVE_META = "https://archive.org/metadata/"
_ARCHIVE_DL = "https://archive.org/download/"
# image extensions we can actually place on the 1080p canvas
_ARCHIVE_EXT = (".jpg", ".jpeg", ".png", ".tif", ".tiff")
# file-name fragments that mark a derivative/thumbnail we must skip
_ARCHIVE_SKIP = ("_thumb", "__ia_thumb", "_itemimage", ".gif", "_spectrogram")


def _archive_on() -> bool:
    return os.environ.get("VIDLORE_ARCHIVE", "1").strip().lower() not in (
        "0", "false", "no", "off"
    )


def _archive_pick_file(identifier: str) -> list[str]:
    """Return downloadable image-file URLs for an IA item, largest first.
    Skips thumbnails/derivatives; prefers original scans."""
    try:
        r = requests.get(_ARCHIVE_META + identifier, headers=_UA, timeout=20)
        r.raise_for_status()
        files = (r.json() or {}).get("files", []) or []
    except Exception:                                      # noqa: BLE001
        return []
    cands: list[tuple[int, str]] = []
    for f in files:
        name = (f.get("name") or "")
        low = name.lower()
        if not low.endswith(_ARCHIVE_EXT):
            continue
        if any(s in low for s in _ARCHIVE_SKIP):
            continue
        try:
            size = int(f.get("size") or 0)
        except (TypeError, ValueError):
            size = 0
        # originals score higher than re-derived copies of the same scan
        src = (f.get("source") or "").lower()
        bonus = 1 if src == "original" else 0
        cands.append((size + bonus * (1 << 30), name))
    cands.sort(key=lambda t: t[0], reverse=True)
    return [_ARCHIVE_DL + identifier + "/" +
            requests.utils.quote(n) for _, n in cands[:4]]


def _archive_one(query: str, dest: Path, variant: int = 0) -> bool:
    try:
        r = requests.get(
            _ARCHIVE_SEARCH,
            params={"q": f'mediatype:image AND ({query})',
                    "fl[]": "identifier", "rows": 20, "page": 1,
                    "sort[]": "downloads desc", "output": "json"},
            headers=_UA, timeout=20)
        r.raise_for_status()
        docs = (((r.json() or {}).get("response") or {}).get("docs") or [])
        ids = [d.get("identifier") for d in docs if d.get("identifier")]
        if not ids:
            return False
        if variant:
            o = variant % len(ids)
            ids = ids[o:] + ids[:o]
        tmp = dest.with_suffix(".dl")
        tried = 0
        for ident in ids:
            if tried >= 6:                 # cap network work per beat
                break
            for link in _archive_pick_file(ident):
                tried += 1
                if tried > 6:
                    break
                try:
                    with requests.get(link, headers=_UA, stream=True,
                                      timeout=30) as dl:
                        dl.raise_for_status()
                        if "image" not in dl.headers.get("content-type", ""):
                            continue
                        with open(tmp, "wb") as fh:
                            for chunk in dl.iter_content(1 << 16):
                                fh.write(chunk)
                    # IA returns LOTS of book-frontispiece scans for vague
                    # historical queries (a vintage Art Journal title page is
                    # NOT a Cold War visual). Reject before they reach the film.
                    # v12: also catch leather/cloth book covers that pass
                    # `_is_text_page` (uniform photographic surface).
                    if _is_text_page(tmp):
                        continue
                    if _is_archive_book_artifact(tmp):
                        continue
                    if _cover_to_canvas(tmp, dest):
                        return True
                except Exception:                          # noqa: BLE001
                    continue
                finally:
                    tmp.unlink(missing_ok=True)
        return False
    except Exception:                                      # noqa: BLE001
        return False


def _archive_image(queries: list[str], dest: Path, variant: int = 0) -> bool:
    """Try each query; first usable Internet Archive image wins."""
    if not _archive_on():
        return False
    for q in queries:
        if q and _archive_one(q, dest, variant):
            return True
    return False


# --------------------------------------------------------------------------- #
# YouTube DOCUMENTARY FRAME EXTRACTION — many of the best historical visuals
# (war footage, declassified reels, archival establishing shots) live inside
# documentaries. This finds a relevant documentary, downloads a short capped-
# resolution slice, extracts scene-change candidate frames, then INTELLIGENTLY
# scores them: rejects blur / motion-blur / subtitle bands / talking-heads /
# too-dark/blown frames, rewards sharp cinematic establishing shots, de-dupes
# by perceptual hash, and keeps the single strongest frame. It is the DEEPEST
# archival fallback — gated to deep-historical beats AND globally budgeted so
# extracted frames never dominate (see `_yt_frames_beat` + the render budget).
# Needs yt_dlp (already installed) + numpy + PIL. Off via VIDLORE_YT_FRAMES=0.
# --------------------------------------------------------------------------- #
_YT_DEEP_WORDS = (
    "war", "wwii", "wwi", "soviet", "cold war", "nazi", "kgb", "cia",
    "espionage", "intelligence", "spy", "defector", "regime", "battle",
    "military", "operation", "archive", "declassified", "footage", "newsreel",
    "uprising", "revolution", "invasion", "bombing", "treaty", "wall",
    "communist", "dictator", "genocide", "empire", "colonial",
)


def _yt_frames_on() -> bool:
    return os.environ.get("VIDLORE_YT_FRAMES", "1").strip().lower() not in (
        "0", "false", "no", "off"
    )


def _ytdlp_ffmpeg_dir() -> str | None:
    """yt_dlp only recognises an executable literally named ``ffmpeg``/
    ``ffprobe``. The bundled imageio binary is named e.g. ``ffmpeg-macos-...``
    so we expose a small dir of correctly-named symlinks pointing at it and
    hand that dir to yt_dlp as ``ffmpeg_location``."""
    try:
        from .ffmpeg_tool import ffmpeg_exe
        import tempfile
        exe = Path(ffmpeg_exe())
        d = Path(tempfile.gettempdir()) / "vidlore_ffbin"
        d.mkdir(parents=True, exist_ok=True)
        for nm in ("ffmpeg", "ffprobe"):
            link = d / nm
            if not link.exists():
                try:
                    link.symlink_to(exe)
                except Exception:                          # noqa: BLE001
                    shutil.copy2(exe, link)
                    os.chmod(link, 0o755)
        # yt_dlp's FFmpegFD.available() is a classmethod that scans PATH only
        # (it ignores ffmpeg_location), and partial/range downloads gate on it.
        # So also put this dir on PATH (idempotent) for the range download.
        ds = str(d)
        cur = os.environ.get("PATH", "")
        if ds not in cur.split(os.pathsep):
            os.environ["PATH"] = ds + os.pathsep + cur
        return ds
    except Exception:                                      # noqa: BLE001
        return None


def _deep_historical_hint(sc) -> bool:
    """Stricter than `_historical_hint`: a scene that is DEEPLY archival —
    real war/intel/footage subject matter where documentary frames shine.
    Keeps YouTube extraction off mild-history beats so it stays rare."""
    blob = (" ".join(sc.keywords or []) + " " + (sc.query or "") + " "
            + (sc.narration or "")).lower()
    hits = sum(1 for w in _YT_DEEP_WORDS if w in blob)
    has_year = bool(re.search(r"\b(1[5-9]\d{2}|20[0-1]\d)\b", blob))
    return hits >= 1 and (hits >= 2 or has_year)


def _yt_frames_beat(sc, beat: int) -> bool:
    """Tight budget gate: only a SMALL slice (~`_yt_share`) of DEEP-historical
    beats are eligible to lead with a documentary frame. Deterministic and
    spread (different stride from archival) so frames interleave with stock +
    archival rather than clustering. The global render budget caps it further."""
    try:
        share = float(os.environ.get("VIDLORE_YT_SHARE", "0.16"))
    except (TypeError, ValueError):
        share = 0.16
    share = min(0.4, max(0.0, share))
    if share <= 0:
        return False
    period = 16
    slots = max(1, round(share * period))
    seq = (int(getattr(sc, "index", 0)) * 3 + int(beat))
    return ((seq * 7) % period) < slots


# ---- frame intelligence (numpy + PIL only; no OpenCV dependency) ---------- #
def _np_gray(img):
    import numpy as np
    return np.asarray(img.convert("L"), dtype="float32")


def _lap_var(gray) -> float:
    """Variance of the Laplacian — the classic sharpness/focus metric.
    Low = blurry or motion-blurred; high = crisp detail."""
    import numpy as np
    lap = (-4.0 * gray
           + np.roll(gray, 1, 0) + np.roll(gray, -1, 0)
           + np.roll(gray, 1, 1) + np.roll(gray, -1, 1))
    return float(lap[1:-1, 1:-1].var())


def _ahash(img) -> int:
    """8x8 average perceptual hash for duplicate detection."""
    import numpy as np
    small = np.asarray(img.convert("L").resize((8, 8), Image.LANCZOS),
                       dtype="float32")
    return int(np.packbits(small > small.mean()).view(">u8")[0])


def _hamming(a: int, b: int) -> int:
    return bin((a ^ b) & ((1 << 64) - 1)).count("1")


def _subtitle_penalty(gray) -> float:
    """Detect a burned-in subtitle band: a bright, high-contrast horizontal
    strip in the lower-centre that the mid-frame lacks. Returns 0..1."""
    import numpy as np
    h, w = gray.shape
    band = gray[int(h * 0.80):int(h * 0.99), int(w * 0.15):int(w * 0.85)]
    mid = gray[int(h * 0.45):int(h * 0.60), int(w * 0.15):int(w * 0.85)]
    if band.size == 0 or mid.size == 0:
        return 0.0
    bright_band = float((band > 205).mean())
    bright_mid = float((mid > 205).mean())
    # subtitles = many bright pixels in the band, high local contrast there,
    # and far fewer bright pixels in the mid-frame
    contrast = min(1.0, float(band.std()) / 70.0)
    excess = max(0.0, bright_band - bright_mid)
    if bright_band > 0.04 and excess > 0.03:
        return min(1.0, (excess * 6.0) * (0.5 + 0.5 * contrast))
    return 0.0


def _talkinghead_penalty(img) -> float:
    """Heuristic talking-head detector (no face model): a large skin-tone
    region concentrated in the centre = an interview close-up. Returns 0..1.
    Kept mild so an important portrait isn't hard-rejected, just deprioritised."""
    import numpy as np
    a = np.asarray(img.convert("RGB").resize((96, 54), Image.BILINEAR),
                   dtype="float32")
    r, g, b = a[..., 0], a[..., 1], a[..., 2]
    skin = ((r > 95) & (g > 40) & (b > 20) & (r > g) & (g > b)
            & ((r - g) > 12) & ((r - b) > 18))
    h, w = skin.shape
    centre = skin[int(h * 0.18):int(h * 0.92), int(w * 0.28):int(w * 0.72)]
    if centre.size == 0:
        return 0.0
    frac = float(centre.mean())
    return min(1.0, max(0.0, (frac - 0.18) * 2.2))


def _cinematic_bonus(gray) -> float:
    """Reward letterboxed / widescreen cinematic framing (dark bars top &
    bottom) and structured establishing shots (healthy edge density)."""
    import numpy as np
    h, w = gray.shape
    top = float(gray[:int(h * 0.07)].mean())
    bot = float(gray[int(h * 0.93):].mean())
    letterbox = 0.18 if (top < 22 and bot < 22) else 0.0
    return letterbox


def _frame_score(path: Path):
    """Score one candidate frame. Returns (score, ahash) or None if the frame
    fails a hard quality gate (too small / too dark / blown / too blurry)."""
    try:
        img = Image.open(path).convert("RGB")
    except Exception:                                      # noqa: BLE001
        return None
    if min(img.size) < 360:                                # resolution floor
        return None
    gray = _np_gray(img)
    mean = float(gray.mean())
    if mean < 22 or mean > 238:                            # black/blown frame
        return None
    sharp = _lap_var(gray)
    # NB: archival/documentary footage is inherently soft (old film, low-res
    # source), so the focus floor is calibrated for that — it rejects only
    # genuinely smeared / motion-blurred / dissolve-transition frames, not the
    # naturally grainy look of vintage footage.
    if sharp < 10.0:                                       # smeared / in-motion
        return None
    sub = _subtitle_penalty(gray)
    if sub > 0.6:                                          # heavy subtitles
        return None
    face = _talkinghead_penalty(img)
    colour = min(1.0, float(gray.std()) / 60.0)            # tonal range proxy
    cine = _cinematic_bonus(gray)
    score = (min(1.0, sharp / 70.0) * 0.46                # crisp detail
             + colour * 0.20                               # rich tonality
             + cine                                        # cinematic framing
             - sub * 0.55                                  # subtitle band
             - face * 0.30)                                # talking-head
    return (score, _ahash(img))


# Current YouTube blocks the default 'web' client with HTTP 403 (PO-token /
# nsig). Alternate player clients still serve a plain progressive stream the
# native downloader can fetch without ffmpeg — try them in order.
_YT_CLIENTS = ("android", "ios", "tv", "mweb", "web_safari")


def _yt_search_ids(query: str, n: int = 5) -> list[str]:
    """Flat YouTube search -> video ids, filtered to documentary-length
    (skip Shorts and multi-hour uploads)."""
    try:
        import yt_dlp
    except Exception:                                      # noqa: BLE001
        return []
    opts = {"quiet": True, "no_warnings": True, "skip_download": True,
            "extract_flat": "in_playlist", "noplaylist": True,
            "default_search": "ytsearch",
            "extractor_args": {"youtube": {"player_client": list(_YT_CLIENTS)}}}
    out: list[str] = []
    try:
        with yt_dlp.YoutubeDL(opts) as ydl:
            info = ydl.extract_info(f"ytsearch{n}:{query}", download=False)
        for e in (info or {}).get("entries", []) or []:
            dur = e.get("duration") or 0
            vid = e.get("id")
            if vid and (dur == 0 or 180 <= dur <= 3600):   # 3min..60min docs
                out.append(vid)
    except Exception:                                      # noqa: BLE001
        return []
    return out


def _yt_download(vid: str, dest: Path) -> bool:
    """Download a single LOW-RES video-only stream (360-480p, size-capped) via
    yt_dlp's NATIVE downloader — no ffmpeg, no range cut (both hit YouTube's
    403). Tries alternate player clients until one serves the stream. Returns
    True if a usable file landed at `dest`."""
    try:
        import yt_dlp
    except Exception:                                      # noqa: BLE001
        return False
    for client in _YT_CLIENTS:
        for f in dest.parent.glob(dest.stem + ".*"):
            f.unlink(missing_ok=True)
        opts = {
            "quiet": True, "no_warnings": True, "noprogress": True,
            "noplaylist": True, "retries": 1, "socket_timeout": 20,
            "max_filesize": 150 * 1024 * 1024,
            "format": ("bv*[height<=480][height>=360]/best[height<=480]/"
                       "worst[height>=360]/best"),
            "outtmpl": str(dest.with_suffix("")) + ".%(ext)s",
            "extractor_args": {"youtube": {"player_client": [client]}},
        }
        try:
            with yt_dlp.YoutubeDL(opts) as ydl:
                ydl.download([f"https://www.youtube.com/watch?v={vid}"])
        except Exception:                                  # noqa: BLE001
            continue
        for cand in dest.parent.glob(dest.stem + ".*"):
            if (cand.suffix.lower() in (".mp4", ".mkv", ".webm", ".m4v")
                    and cand.stat().st_size > 200_000):
                if cand != dest:
                    try:
                        cand.replace(dest)
                    except Exception:                      # noqa: BLE001
                        return cand.exists()
                return dest.exists()
    return False


def _yt_extract_candidates(video: Path, out_dir: Path,
                           start: float = 70.0, length: float = 220.0,
                           max_frames: int = 28) -> list[Path]:
    """Extract scene-change candidate frames (visually distinct shots) from a
    LOCAL downloaded file, seeking `start`..`start+length`. Start is well past
    the typical intro / title / credit sequence (channel bugs + 'A FILM BY'
    cards live in the first ~minute) so we sample real documentary footage,
    not branded title frames. A fixed-interval pass backs it up so we always
    get a spread of options."""
    from .ffmpeg_tool import ffmpeg_exe
    import subprocess
    out_dir.mkdir(parents=True, exist_ok=True)

    def _run(vf: str, out_pat: str) -> None:
        try:
            subprocess.run(
                [ffmpeg_exe(), "-y", "-hide_banner", "-loglevel", "error",
                 "-ss", f"{start:.1f}", "-i", str(video),
                 "-t", f"{length:.1f}", "-an",
                 "-vf", vf, "-vsync", "vfr",
                 "-frames:v", str(max_frames), "-q:v", "3", out_pat],
                capture_output=True, text=True, timeout=150)
        except Exception:                                  # noqa: BLE001
            pass

    # scene-change frames = genuinely different shots, not near-duplicates
    _run("select='gt(scene,0.30)',scale=1280:-2", str(out_dir / "f_%03d.jpg"))
    frames = sorted(out_dir.glob("f_*.jpg"))
    if len(frames) < 6:                                    # sparse -> sample
        _run("fps=1/5,scale=1280:-2", str(out_dir / "g_%03d.jpg"))
        frames = (sorted(out_dir.glob("f_*.jpg"))
                  + sorted(out_dir.glob("g_*.jpg")))
    return frames


def _youtube_frames(sc, queries: list[str], dest: Path, work: Path,
                    used_hashes=None, variant: int = 0) -> bool:
    """Find a documentary, extract candidate frames, pick the strongest
    distinct one and place it on the canvas. `used_hashes` is a shared set of
    perceptual hashes already used in the film, so frames never duplicate
    each other or earlier visuals."""
    if not _yt_frames_on():
        return False
    used_hashes = used_hashes if used_hashes is not None else set()
    work.mkdir(parents=True, exist_ok=True)
    ids: list[str] = []
    for q in queries:
        if not q:
            continue
        ids = _yt_search_ids(f"{q} documentary archival footage", n=5)
        if ids:
            break
    if not ids:
        return False
    if variant:
        o = variant % len(ids)
        ids = ids[o:] + ids[:o]
    fdir = work / "frames"
    vsrc = work / "yt_src.mp4"
    for vid in ids[:3]:                                    # at most 3 sources
        for f in work.glob("yt_src.*"):
            f.unlink(missing_ok=True)
        if not _yt_download(vid, vsrc):
            continue
        for f in fdir.glob("*.jpg"):
            f.unlink(missing_ok=True)
        cands = _yt_extract_candidates(vsrc, fdir)
        scored = []
        for fp in cands:
            # Reject UI-screenshot frames (Telegram / Twitter / browser
            # chrome that some YouTube docs cut to mid-video).
            if _is_ui_screenshot(fp):
                continue
            s = _frame_score(fp)
            if s is not None:
                scored.append((s[0], s[1], fp))
        scored.sort(key=lambda t: t[0], reverse=True)
        picked = False
        for score, h, fp in scored:
            if any(_hamming(h, u) <= 6 for u in used_hashes):
                continue                                   # near-duplicate
            if _cover_to_canvas(fp, dest):
                used_hashes.add(h)
                picked = True
                break
        # tidy the (potentially large) source + frames before returning/looping
        for f in work.glob("yt_src.*"):
            f.unlink(missing_ok=True)
        for f in fdir.glob("*.jpg"):
            f.unlink(missing_ok=True)
        if picked:
            return True
    return False


# --------------------------------------------------------------------------- #
# CONTROLLED WEB REFERENCE EXTRACTION — a restrained, internal-research layer
# for the cases pure stock + public-domain archives can't cover (obscure
# intelligence ops, specific historical moments, named documents/newspapers).
# It is NOT a scraper free-for-all: it is gated to deep-historical/news beats,
# hard-budgeted, prefers archival/encyclopedic/news domains, rejects junk
# (pinterest/meme/clipart/stock-watermark), scores + de-dupes every image, and
# LOGS the source URL + domain + title + attribution for every asset it keeps
# (research_sources.json). Two capture paths:
#   1. article image extraction (lxml HTML parse: og:image + <figure> photos)
#   2. webpage screenshot via the installed Chrome --headless (for document /
#      newspaper / archive-viewer pages where the image IS the page).
# Off by default per beat unless the balance gate + budget allow it; disable
# entirely with VIDLORE_WEBREF=0.
# --------------------------------------------------------------------------- #
_DDG_HTML = "https://html.duckduckgo.com/html/"
# domains we TRUST for documentary reference (archival / encyclopedic / news /
# museum / government). Ranked first; everything else is allowed but lower.
_REF_GOOD = (
    "wikipedia.org", "wikimedia.org", "loc.gov", "archives.gov", "nara.gov",
    "cia.gov", "fbi.gov", "history.com", "britannica.com", "smithsonianmag.com",
    "si.edu", "imperialwarmuseums.org", "iwm.org.uk", "nationalarchives.gov.uk",
    "bbc.co.uk", "bbc.com", "reuters.com", "apnews.com", "nytimes.com",
    "theguardian.com", "washingtonpost.com", "spiegel.de", "dw.com",
    "bundesarchiv.de", "rarehistoricalphotos.com", "gettyimages.com",
    "nationalgeographic.com", "pbs.org", "wilsoncenter.org", "nato.int",
    "un.org", "europeana.eu", "yadvashem.org", "ushmm.org",
)
# domains we REFUSE (low quality / memes / social / clipart / paywalled junk).
_REF_BAD = (
    "pinterest.", "reddit.com", "quora.com", "facebook.com", "instagram.com",
    "tiktok.com", "twitter.com", "x.com", "fandom.com", "wikia.",
    "shutterstock.com", "istockphoto.com", "dreamstime.com", "alamy.com",
    "123rf.com", "clipart", "memegenerator", "imgflip.com", "etsy.com",
    "amazon.", "ebay.", "aliexpress.", "youtube.com", "tumblr.com",
)


def _webref_on() -> bool:
    return os.environ.get("VIDLORE_WEBREF", "1").strip().lower() not in (
        "0", "false", "no", "off"
    )


def _webref_beat(sc, beat: int) -> bool:
    """Very tight balance gate: only a SMALL slice (~`VIDLORE_WEBREF_SHARE`,
    default 0.12) of deep-historical/news beats may reach the web-reference
    layer, on a different stride from archival + YT so the sources interleave
    and web refs never cluster. The global budget caps it further."""
    try:
        share = float(os.environ.get("VIDLORE_WEBREF_SHARE", "0.12"))
    except (TypeError, ValueError):
        share = 0.12
    share = min(0.35, max(0.0, share))
    if share <= 0:
        return False
    period = 16
    slots = max(1, round(share * period))
    seq = (int(getattr(sc, "index", 0)) * 5 + int(beat))
    return ((seq * 11) % period) < slots


def _domain(url: str) -> str:
    try:
        from urllib.parse import urlparse
        return (urlparse(url).netloc or "").lower().lstrip("www.")
    except Exception:                                      # noqa: BLE001
        return ""


def _ref_domain_rank(url: str) -> int:
    """-1 = banned (skip), higher = more trusted documentary source."""
    d = _domain(url)
    if not d or any(b in d for b in _REF_BAD):
        return -1
    for i, g in enumerate(reversed(_REF_GOOD)):
        if g in d:
            return 10 + i
    return 1                                               # allowed, neutral


def _chrome_exe() -> str | None:
    """Locate an installed Chrome/Chromium for headless screenshots."""
    import shutil as _sh
    for c in ("google-chrome", "chromium", "chromium-browser",
              "chrome"):
        p = _sh.which(c)
        if p:
            return p
    for app in ("/Applications/Google Chrome.app/Contents/MacOS/Google Chrome",
                "/Applications/Chromium.app/Contents/MacOS/Chromium"):
        if os.path.exists(app):
            return app
    return None


def _web_search_urls(query: str, n: int = 10) -> list[tuple[str, str, int]]:
    """Keyless web search (DuckDuckGo HTML) -> [(url, title, domain_rank)],
    banned domains dropped, trusted documentary domains ranked first."""
    try:
        import lxml.html as _lh
        from urllib.parse import parse_qs, urlparse, unquote
    except Exception:                                      # noqa: BLE001
        return []
    try:
        r = requests.post(_DDG_HTML, data={"q": query}, headers=_UA,
                          timeout=20)
        r.raise_for_status()
        doc = _lh.fromstring(r.text)
    except Exception:                                      # noqa: BLE001
        return []
    out: list[tuple[str, str, int]] = []
    seen: set[str] = set()
    for a in doc.xpath("//a[contains(concat(' ', normalize-space(@class), "
                       "' '), ' result__a ')]"):
        href = a.get("href") or ""
        # DDG wraps results as /l/?uddg=<encoded real url>
        real = href
        try:
            if "uddg=" in href:
                qs = parse_qs(urlparse(href).query)
                real = unquote(qs.get("uddg", [href])[0])
        except Exception:                                  # noqa: BLE001
            real = href
        if not real.startswith("http"):
            continue
        dom = _domain(real)
        if dom in seen:
            continue
        rank = _ref_domain_rank(real)
        if rank < 0:
            continue
        seen.add(dom)
        title = (a.text_content() or "").strip()
        out.append((real, title, rank))
        if len(out) >= n * 2:
            break
    out.sort(key=lambda t: t[2], reverse=True)             # trusted first
    return out[:n]


def _article_images(url: str, max_imgs: int = 12) -> list[tuple[str, str]]:
    """Extract candidate REAL photos from an article page (no screenshot):
    og:image / twitter:image first, then <figure>/<article> <img>. Returns
    [(image_url, caption)], junk (icons/logos/sprites/svg/data) filtered."""
    try:
        import lxml.html as _lh
        from urllib.parse import urljoin
    except Exception:                                      # noqa: BLE001
        return []
    try:
        r = requests.get(url, headers=_UA, timeout=20)
        r.raise_for_status()
        doc = _lh.fromstring(r.text)
    except Exception:                                      # noqa: BLE001
        return []
    cands: list[tuple[str, str]] = []
    seen: set[str] = set()

    def _add(src: str, cap: str) -> None:
        if not src:
            return
        s = urljoin(url, src.strip())
        low = s.lower()
        if not low.startswith("http"):
            return
        if low.endswith(".svg") or low.startswith("data:"):
            return
        if any(j in low for j in ("logo", "icon", "sprite", "avatar",
                                  "favicon", "thumb_", "pixel", "1x1",
                                  "spacer", "blank", "/ads/", "tracking")):
            return
        if s in seen:
            return
        seen.add(s)
        cands.append((s, (cap or "").strip()[:160]))

    # 1) social/open-graph hero image (usually the article's lead photo)
    for xp in ("//meta[@property='og:image']",
               "//meta[@property='og:image:url']",
               "//meta[@name='twitter:image']",
               "//meta[@name='twitter:image:src']"):
        for m in doc.xpath(xp):
            _add(m.get("content"), "lead image")
    # 2) figures (real captioned photos) then article body images
    for fig in doc.xpath("//figure"):
        imgs = fig.xpath(".//img")
        cap = ""
        caps = fig.xpath(".//figcaption")
        if caps:
            cap = caps[0].text_content()
        for im in imgs:
            _add(im.get("src") or im.get("data-src") or im.get("data-srcset"),
                 cap)
    for im in doc.xpath("//article//img | //*[contains(concat(' ', "
                        "normalize-space(@class), ' '), ' content ')]//img | "
                        "//*[@id='content']//img"):
        # prefer images that declare a real width (filters tiny UI sprites)
        try:
            w = int(im.get("width") or 0)
        except (TypeError, ValueError):
            w = 0
        if w and w < 300:
            continue
        _add(im.get("src") or im.get("data-src"), "")
        if len(cands) >= max_imgs:
            break
    return cands[:max_imgs]


def _web_screenshot(url: str, dest: Path, timeout: float = 35.0) -> bool:
    """Capture a full webpage screenshot with the installed Chrome --headless.
    Used for DOCUMENT-type references (newspaper pages, declassified files,
    archive viewers) where the image IS the page. Returns True on success."""
    exe = _chrome_exe()
    if not exe:
        return False
    import subprocess
    import tempfile
    shot = dest.with_suffix(".png")
    with tempfile.TemporaryDirectory() as prof:
        try:
            subprocess.run(
                [exe, "--headless=new", "--disable-gpu", "--no-sandbox",
                 "--hide-scrollbars", "--force-device-scale-factor=1",
                 f"--user-data-dir={prof}",
                 "--window-size=1600,2200",
                 "--virtual-time-budget=8000",
                 f"--screenshot={shot}", url],
                capture_output=True, text=True, timeout=timeout)
        except Exception:                                  # noqa: BLE001
            return False
    if shot.exists() and shot.stat().st_size > 20_000:
        ok = _cover_to_canvas(shot, dest)
        shot.unlink(missing_ok=True)
        return ok
    shot.unlink(missing_ok=True)
    return False


def _download_ref_image(url: str, dest: Path) -> bool:
    """Download one image URL and fit it to the canvas (cinematic cover-crop).
    Reuses the same validate/resize path as the other photo sources."""
    tmp = dest.with_suffix(".dl")
    try:
        with requests.get(url, headers=_UA, stream=True, timeout=30) as dl:
            dl.raise_for_status()
            if "image" not in dl.headers.get("content-type", ""):
                return False
            with open(tmp, "wb") as fh:
                for chunk in dl.iter_content(1 << 16):
                    fh.write(chunk)
        return _cover_to_canvas(tmp, dest)
    except Exception:                                      # noqa: BLE001
        return False
    finally:
        tmp.unlink(missing_ok=True)


def _log_reference(ref_dir, entry: dict, lock=None) -> None:
    """Append one source-attribution record to research_sources.json — the
    audit trail of every web reference the documentary used (url, domain,
    title, capture method, scene/beat). Best-effort; never breaks a render."""
    if not ref_dir:
        return
    try:
        import json
        p = Path(ref_dir) / "research_sources.json"
        rec = dict(entry)
        rec.setdefault("logged_at", __import__("time").strftime(
            "%Y-%m-%dT%H:%M:%S"))

        def _write() -> None:
            data = []
            if p.exists():
                try:
                    data = json.loads(p.read_text(encoding="utf-8"))
                except Exception:                          # noqa: BLE001
                    data = []
            data.append(rec)
            p.write_text(json.dumps(data, indent=2, ensure_ascii=False),
                         encoding="utf-8")

        if lock is not None:
            with lock:
                _write()
        else:
            _write()
    except Exception:                                      # noqa: BLE001
        pass


def _web_reference(sc, queries: list[str], dest: Path, work: Path,
                   used_hashes=None, variant: int = 0,
                   ref_dir=None, ref_lock=None) -> bool:
    """Controlled reference collector: search trusted documentary domains,
    extract a strong, distinct, on-topic image (article photo first, page
    screenshot as a document fallback), cinematic-crop it, de-dupe it against
    the film, and LOG its source. Returns True when a kept image lands."""
    if not _webref_on():
        return False
    used_hashes = used_hashes if used_hashes is not None else set()
    work.mkdir(parents=True, exist_ok=True)
    results: list[tuple[str, str, int]] = []
    for q in queries:
        if not q:
            continue
        results = _web_search_urls(f"{q} archival photograph", n=10)
        if results:
            break
    if not results:
        return False
    if variant:
        o = variant % len(results)
        results = results[o:] + results[:o]
    tmp_img = work / "ref_cand.jpg"
    tried = 0
    for url, title, rank in results:
        if tried >= 6:                                     # cap work per beat
            break
        # Pre-fetch host blocklist: messaging / social URLs render as
        # private chat / feed screenshots (e.g. t.me / twitter / reddit).
        if _is_ui_host(url):
            continue
        tried += 1
        picked_url = None
        method = None
        # 1) article images (real photos) — preferred
        for img_url, cap in _article_images(url, max_imgs=10):
            # Some pages embed Telegram / Twitter card thumbnails; reject
            # the IMG URL too if it sits under a known UI host.
            if _is_ui_host(img_url):
                continue
            if _download_ref_image(img_url, tmp_img):
                # Post-download UI-screenshot guard
                if _is_ui_screenshot(tmp_img):
                    tmp_img.unlink(missing_ok=True)
                    continue
                s = _frame_score(tmp_img)
                if s is None:
                    continue
                if any(_hamming(s[1], u) <= 6 for u in used_hashes):
                    continue
                if _cover_to_canvas(tmp_img, dest):
                    used_hashes.add(s[1])
                    picked_url, method = img_url, "article_image"
                    break
        # 2) document-page screenshot (newspaper / declassified file viewers).
        # OFF by default: full-page screenshots of generic landing/index pages
        # look weak. Article-image extraction (real photos) is preferred; opt
        # in with VIDLORE_WEBREF_SHOT=1 only when you want document captures.
        _shot_on = os.environ.get("VIDLORE_WEBREF_SHOT", "0").strip().lower() \
            in ("1", "true", "yes", "on")
        if _shot_on and not picked_url and rank >= 10:
            if _web_screenshot(url, tmp_img):
                if _is_ui_screenshot(tmp_img):
                    tmp_img.unlink(missing_ok=True)
                    continue
                s = _frame_score(tmp_img)
                if s is not None and not any(
                        _hamming(s[1], u) <= 6 for u in used_hashes):
                    if _cover_to_canvas(tmp_img, dest):
                        used_hashes.add(s[1])
                        picked_url, method = url, "screenshot"
        tmp_img.unlink(missing_ok=True)
        if picked_url:
            _log_reference(ref_dir, {
                "scene": int(getattr(sc, "index", -1)),
                "page_url": url, "image_url": picked_url,
                "domain": _domain(url), "title": title,
                "method": method, "query": queries[0] if queries else "",
            }, lock=ref_lock)
            return True
    return False


# --------------------------------------------------------------------------- #
# Pixabay & Unsplash — more REAL photos. Both are free for commercial use
# (safe on monetized YouTube), but each needs a free API key. If the key
# is missing the provider just returns False and the chain falls through
# unchanged, so nothing breaks for users who don't add a key.
#   PIXABAY_API_KEY     -> https://pixabay.com/api/docs/   (free)
#   UNSPLASH_ACCESS_KEY -> https://unsplash.com/developers  (free)
# --------------------------------------------------------------------------- #
_PIXABAY_URL = "https://pixabay.com/api/"
_UNSPLASH_URL = "https://api.unsplash.com/search/photos"


def _pixabay_key() -> str:
    return os.environ.get("PIXABAY_API_KEY", "").strip()


def _unsplash_key() -> str:
    return os.environ.get("UNSPLASH_ACCESS_KEY", "").strip()


def _download_cover(link: str, dest: Path, headers=None) -> bool:
    """Stream-download an image URL and cover-crop it to the canvas.

    v13.2 (2026-05-28): runs the SAME artifact filters Pixabay/Unsplash
    previously lacked (LoC / IA / Wikimedia already had them). User
    reported text-page / book-scan images leaking from Pixabay
    (pixabay_100/211/215) and Unsplash (unsplash_010/026/038) on the
    25-min render. Both sources route through here, so one guard covers
    both: reject text pages, sepia/leather book covers, archive book
    artifacts, and UI screenshots before they reach the film.
    """
    tmp = dest.with_suffix(".dl")
    try:
        with requests.get(
            link, headers=headers or _UA, stream=True, timeout=30
        ) as dl:
            dl.raise_for_status()
            if "image" not in dl.headers.get("content-type", ""):
                return False
            with open(tmp, "wb") as fh:
                for chunk in dl.iter_content(1 << 16):
                    fh.write(chunk)
        # Reject text-page / book artifact BEFORE the canvas cover so we
        # don't waste the encode + can fall through to the next candidate.
        try:
            if _is_text_page(tmp) or _is_archive_book_artifact(tmp):
                return False
            if _is_ui_screenshot(tmp):
                return False
        except Exception:                                  # noqa: BLE001
            pass
        if not _cover_to_canvas(tmp, dest):
            return False
        # Final re-check on the canvas output (cover-crop can change the
        # text/photo ratio enough to flip a borderline call).
        try:
            if _is_text_page(dest) or _is_archive_book_artifact(dest):
                dest.unlink(missing_ok=True)
                return False
        except Exception:                                  # noqa: BLE001
            pass
        return True
    except Exception:
        return False
    finally:
        tmp.unlink(missing_ok=True)


def _pixabay_one(query: str, dest: Path, variant: int = 0) -> bool:
    key = _pixabay_key()
    if not key:
        return False
    try:
        r = requests.get(
            _PIXABAY_URL,
            params={
                "key": key,
                "q": query,
                "image_type": "photo",
                "orientation": "horizontal",
                "safesearch": "true",
                "order": "popular",
                "per_page": 20,
            },
            headers=_UA,
            timeout=25,
        )
        r.raise_for_status()
        hits = r.json().get("hits", []) or []
        hits.sort(key=lambda h: (h.get("imageWidth") or 0), reverse=True)
        if hits and variant:
            o = variant % len(hits)
            hits = hits[o:] + hits[:o]
        for h in hits:
            # search-side era guard: skip a modern-era photo on a period doc
            if _period_blocked(f"{h.get('tags', '')} {h.get('pageURL', '')}"):
                continue
            link = h.get("largeImageURL") or h.get("webformatURL")
            if link and _download_cover(link, dest):
                return True
        return False
    except Exception:
        return False


def _unsplash_one(query: str, dest: Path, variant: int = 0) -> bool:
    key = _unsplash_key()
    if not key:
        return False
    try:
        r = requests.get(
            _UNSPLASH_URL,
            params={
                "query": query,
                "per_page": 20,
                "orientation": "landscape",
                "content_filter": "high",
            },
            headers={**_UA, "Authorization": f"Client-ID {key}"},
            timeout=25,
        )
        r.raise_for_status()
        results = r.json().get("results", []) or []
        results.sort(key=lambda x: (x.get("width") or 0), reverse=True)
        if results and variant:
            o = variant % len(results)
            results = results[o:] + results[:o]
        for it in results:
            # search-side era guard: skip a modern-era photo on a period doc
            _tags = it.get("tags") or []
            _meta = (str(it.get("alt_description") or "") + " "
                     + str(it.get("description") or "") + " " + " ".join(
                        (t.get("title", "") if isinstance(t, dict) else str(t))
                        for t in _tags))
            if _period_blocked(_meta):
                continue
            urls = it.get("urls") or {}
            for k in ("full", "regular", "raw"):
                link = urls.get(k)
                if link and _download_cover(link, dest):
                    return True
        return False
    except Exception:
        return False


def _pixabay_image(queries: list[str], dest: Path, variant: int = 0) -> bool:
    for q in queries:
        if _pixabay_one(q, dest, variant):
            return True
    return False


def _unsplash_image(queries: list[str], dest: Path, variant: int = 0) -> bool:
    for q in queries:
        if _unsplash_one(q, dest, variant):
            return True
    return False


# --------------------------------------------------------------------------- #
# Slide fallback (Pillow)
# --------------------------------------------------------------------------- #
# Bundled font shipped inside the package (vidlore/assets/) — same file
# on every OS, so Windows graphic cards render identically to the Mac
# (a missing system font was silently skipping ALL on-screen text).
_ASSET_DIR = Path(__file__).resolve().parent / "assets"
_BUNDLED_FONT = str(_ASSET_DIR / "VidloreSans-Bold.ttf")
_BUNDLED_FONT_R = str(_ASSET_DIR / "VidloreSans.ttf")


def _font(size: int) -> ImageFont.FreeTypeFont:
    for p in (
        _BUNDLED_FONT,
        _BUNDLED_FONT_R,
        "/System/Library/Fonts/Supplemental/Arial Bold.ttf",
        "/System/Library/Fonts/Helvetica.ttc",
        "/Library/Fonts/Arial.ttf",
        "/usr/share/fonts/truetype/dejavu/DejaVuSans-Bold.ttf",
        "C:/Windows/Fonts/ARIALUNI.TTF",
        "C:/Windows/Fonts/arialbd.ttf",
        "C:/Windows/Fonts/arial.ttf",
        "C:/Windows/Fonts/segoeui.ttf",
    ):
        if Path(p).exists():
            try:
                return ImageFont.truetype(p, size)
            except Exception:
                pass
    return ImageFont.load_default()


def _slide(scene: Scene, theme: dict, dest: Path, seed: int,
           background: str = "auto") -> None:
    rnd = random.Random(seed)
    # If the user picked a specific background pattern (one of the 10
    # Vidlore-style options), use it as the base layer instead of the
    # plain theme gradient. "auto" / unknown falls back to the gradient
    # so older briefs without the field keep rendering identically.
    base = None
    if background and background != "auto":
        try:
            from .backgrounds import generate as _bg_generate
            base = _bg_generate(background, (W, H), theme.get("accent"))
        except Exception:                                  # noqa: BLE001
            base = None
    if base is None:
        c1, c2 = theme["grad"]
        base = Image.new("RGB", (W, H))
        px = base.load()
        # diagonal gradient
        for y in range(H):
            t = y / H
            for x in range(0, W, 2):
                tx = (t * 0.7) + (x / W) * 0.3
                r = int(c1[0] + (c2[0] - c1[0]) * tx)
                g = int(c1[1] + (c2[1] - c1[1]) * tx)
                b = int(c1[2] + (c2[2] - c1[2]) * tx)
                px[x, y] = (r, g, b)
                if x + 1 < W:
                    px[x + 1, y] = (r, g, b)

    d = ImageDraw.Draw(base, "RGBA")
    # soft accent glow blobs
    ac = theme["accent"]
    for _ in range(3):
        cx, cy = rnd.randint(0, W), rnd.randint(0, H)
        rr = rnd.randint(260, 520)
        d.ellipse([cx - rr, cy - rr, cx + rr, cy + rr],
                  fill=(ac[0], ac[1], ac[2], 16))
    base = base.filter(ImageFilter.GaussianBlur(60))
    d = ImageDraw.Draw(base, "RGBA")

    # vignette
    vg = Image.new("L", (W, H), 0)
    ImageDraw.Draw(vg).ellipse([-W * 0.25, -H * 0.25, W * 1.25, H * 1.25], fill=255)
    vg = vg.filter(ImageFilter.GaussianBlur(220))
    dark = Image.new("RGB", (W, H), (0, 0, 0))
    base = Image.composite(base, dark, vg)

    d = ImageDraw.Draw(base, "RGBA")
    phrase = (scene.keywords[0] if scene.keywords else "").upper()
    if phrase:
        f = _font(150)
        for i, line in enumerate(textwrap.wrap(phrase, 16)[:2]):
            bb = d.textbbox((0, 0), line, font=f)
            tw = bb[2] - bb[0]
            lx, ly = (W - tw) / 2, H * 0.40 + i * 165
            # Readability fix (2026-06-01): this is the slide's HEADLINE, not a
            # ghost watermark — it was drawn at alpha 28 (~11% opacity) and read
            # as near-invisible on the dark vignette. Draw a soft shadow scrim
            # first, then the keyword at high-contrast off-white so it is clearly
            # legible at 1080p on any gradient.
            d.text((lx + 4, ly + 5), line, font=f, fill=(0, 0, 0, 165))
            d.text((lx, ly), line, font=f, fill=(238, 238, 230, 242))
    d.rectangle([W * 0.5 - 90, H * 0.74, W * 0.5 + 90, H * 0.74 + 6],
                fill=(ac[0], ac[1], ac[2], 210))
    base.save(dest, "PNG")


def _age_photo(path: Path) -> None:
    """Make a generated photo read as a genuine vintage archive scan:
    desaturate, lift blacks, warm sepia tint, soft grain + edge burn."""
    try:
        from PIL import ImageEnhance, ImageOps

        im = Image.open(path).convert("RGB")
        g = ImageOps.grayscale(im)
        # autocontrast first so a bright/high-key fal image still reads as
        # a punchy aged scan (not washed out), then a firm contrast push
        # and a slightly darker exposure.
        g = ImageOps.autocontrast(g, cutoff=1)
        g = ImageEnhance.Contrast(g).enhance(1.42)
        g = ImageEnhance.Brightness(g).enhance(0.93)
        sep = ImageOps.colorize(g, black=(20, 15, 9),
                                white=(214, 203, 178), mid=(120, 106, 80))
        # subtle film grain
        nz = Image.effect_noise(sep.size, 18).convert("L")
        sep = Image.blend(sep, Image.merge("RGB", (nz, nz, nz)), 0.07)
        # edge burn (archival darkened corners)
        vg = Image.new("L", sep.size, 0)
        ImageDraw.Draw(vg).ellipse(
            [-sep.size[0] * 0.16, -sep.size[1] * 0.16,
             sep.size[0] * 1.16, sep.size[1] * 1.16], fill=255)
        vg = vg.filter(ImageFilter.GaussianBlur(140))
        sep = Image.composite(sep, Image.new("RGB", sep.size, (18, 14, 9)), vg)
        sep.save(path, "JPEG", quality=88)
    except Exception:
        pass


