        # ---- CLASSIFIED: manila dossier with CLASSIFIED stamp --- #
        if kind == "classified":
            # graphic_text = "FILE_NUMBER :: TITLE" (split on '::')
            raw = (sc.graphic_text or "").strip()
            if "::" in raw:
                file_no, title = [p.strip()[:36] for p in raw.split("::", 1)]
            else:
                file_no, title = "7595-DA", raw[:36]
            body = (sc.graphic_body or "").strip()
            if not body:
                continue
            fn = f"clf_{sc.index:03d}.png"
            destp = work_dir / fn
            if not destp.exists():
                ok = _render_classified_dossier_card(
                    sc, theme or {}, destp,
                    file_no=file_no, title=title, body=body)
                if not ok:
                    continue
            out[sc.index] = fn
